    "Your Screen Time from the last 28 days plus today, as iOS reports it. Today is shown on its own and never counts in weekly comparisons.": "iOS ವರದಿ ಮಾಡಿದಂತೆ ಕಳೆದ 28 ದಿನಗಳ ಜೊತೆಗೆ ಇಂದಿನ ನಿಮ್ಮ ಸ್ಕ್ರೀನ್ ಟೈಮ್. ಇಂದು ಪ್ರತ್ಯೇಕವಾಗಿ ತೋರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ವಾರದ ಹೋಲಿಕೆಗಳಲ್ಲಿ ಎಂದೂ ಸೇರುವುದಿಲ್ಲ.",
    "Missing isn't zero": "ಇಲ್ಲದಿರುವುದು ಶೂನ್ಯವಲ್ಲ",
    "iOS sometimes reports late or only part of a day. Days without data are marked, never counted as zero. If Insights looks empty, tap Refresh.": "iOS ಕೆಲವೊಮ್ಮೆ ತಡವಾಗಿ ಅಥವಾ ದಿನದ ಒಂದು ಭಾಗವನ್ನು ಮಾತ್ರ ವರದಿ ಮಾಡುತ್ತದೆ. ಡೇಟಾ ಇಲ್ಲದ ದಿನಗಳನ್ನು ಗುರುತಿಸಲಾಗುತ್ತದೆ, ಶೂನ್ಯ ಎಂದು ಎಣಿಸಲಾಗುವುದಿಲ್ಲ. ಒಳನೋಟಗಳು ಖಾಲಿ ಕಂಡರೆ ರಿಫ್ರೆಶ್ ಟ್ಯಾಪ್ ಮಾಡಿ.",
    "Apps and totals": "ಆ್ಯಪ್‌ಗಳು ಮತ್ತು ಒಟ್ಟು ಮೊತ್ತ",
    "App times overlap, so they won't add up to your total screen time.": "ಆ್ಯಪ್ ಸಮಯಗಳು ಒಂದರ ಮೇಲೊಂದು ಬರುತ್ತವೆ, ಹಾಗಾಗಿ ನಿಮ್ಮ ಒಟ್ಟು ಸ್ಕ್ರೀನ್ ಟೈಮ್‌ಗೆ ಹೊಂದುವುದಿಲ್ಲ.",
    "Other devices": "ಇತರ ಸಾಧನಗಳು",
    "If Screen Time is shared over iCloud, other devices of the same kind may be included.": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಅನ್ನು iCloud ಮೂಲಕ ಹಂಚಿಕೊಂಡರೆ ಅದೇ ರೀತಿಯ ಇತರ ಸಾಧನಗಳೂ ಸೇರಬಹುದು.",
    "Private by design": "ಗೌಪ್ಯತೆಗಾಗಿ ರೂಪಿತ",
    "Your usage stays inside Apple's Screen Time report. Demora can't read, save or send it.": "ನಿಮ್ಮ ಬಳಕೆ Apple ನ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ವರದಿಯೊಳಗೇ ಇರುತ್ತದೆ. Demora ಅದನ್ನು ಓದಲು, ಉಳಿಸಲು ಅಥವಾ ಕಳುಹಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
    // Insights: comparison sentences, coverage and week names (report).
    "%@ h": "%@ ಗಂ",
    "%@ less than the week before": "ಹಿಂದಿನ ವಾರಕ್ಕಿಂತ %@ ಕಡಿಮೆ",
    "%@ more than the week before": "ಹಿಂದಿನ ವಾರಕ್ಕಿಂತ %@ ಹೆಚ್ಚು",
    "%@: %@ less than your estimate.": "%@: ನಿಮ್ಮ ಅಂದಾಜಿಗಿಂತ %@ ಕಡಿಮೆ.",
    "%@: %@ more than your estimate.": "%@: ನಿಮ್ಮ ಅಂದಾಜಿಗಿಂತ %@ ಹೆಚ್ಚು.",
    "%@: about the same as your estimate.": "%@: ನಿಮ್ಮ ಅಂದಾಜಿನ ಸುಮಾರಿಗೇ.",
    "(%@%%)": "(%@%%)",
    "About the same as the week before": "ಹಿಂದಿನ ವಾರದ ಸುಮಾರಿಗೇ",
    "Day": "ದಿನ",
    "Last 7 full days": "ಕಳೆದ 7 ಪೂರ್ಣ ದಿನಗಳು",
    "No comparison yet: both weeks need full data.": "ಇನ್ನೂ ಹೋಲಿಕೆ ಇಲ್ಲ: ಎರಡೂ ವಾರಗಳಿಗೆ ಪೂರ್ಣ ಡೇಟಾ ಬೇಕು.",
    "No data": "ಡೇಟಾ ಇಲ್ಲ",
    "No earlier week to compare.": "ಹೋಲಿಸಲು ಹಿಂದಿನ ವಾರ ಇಲ್ಲ.",
    "No full week yet": "ಇನ್ನೂ ಪೂರ್ಣ ವಾರ ಇಲ್ಲ",
    "Partly reported": "ಭಾಗಶಃ ವರದಿಯಾಗಿದೆ",
    "The week before": "ಹಿಂದಿನ ವಾರ",
    // Trend dashboard.
    "Trends": "ಪ್ರವೃತ್ತಿಗಳು",
    "Weekday patterns": "ವಾರದ ದಿನಗಳ ಮಾದರಿ",
    "Biggest app changes": "ಅತಿ ದೊಡ್ಡ ಆ್ಯಪ್ ಬದಲಾವಣೆಗಳು",
    "%d days": "%d ದಿನಗಳು",
    "No comparable app changes yet.": "ಹೋಲಿಸಬಹುದಾದ ಆ್ಯಪ್ ಬದಲಾವಣೆಗಳು ಇನ್ನೂ ಇಲ್ಲ.",
    "Selected period": "ಆಯ್ದ ಅವಧಿ",
    // Usage dashboard navigation, chart hints, and duration totals.
    "Previous week": "ಹಿಂದಿನ ವಾರ",
    "Next week": "ಮುಂದಿನ ವಾರ",
    "No trend yet": "ಇನ್ನೂ ಪ್ರವೃತ್ತಿ ಇಲ್ಲ",
    "%@ h %@ min": "%@ ಗಂ %@ ನಿಮಿ",
    // Usage & trends and the practical Guide.
    "%@ min": "%@ ನಿಮಿ",
    "%@ – %@": "%@ – %@",
    "A blank Screen Time report does not mean no usage. Try the refresh arrow, wait for iOS to load, and check access if it stays blank. If a schedule, daily reset or due change seems late, open Demora to reconcile state. An enforcement warning means monitoring needs attention; if a new rule exceeds capacity, reduce overlapping schedules rather than assuming it was saved.": "ಖಾಲಿ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ವರದಿ ಎಂದರೆ ಬಳಕೆ ಇಲ್ಲ ಎಂದಲ್ಲ. ರಿಫ್ರೆಶ್ ಬಾಣವನ್ನು ಪ್ರಯತ್ನಿಸಿ, iOS ಲೋಡ್ ಆಗುವವರೆಗೆ ಕಾಯಿರಿ, ಖಾಲಿಯಾಗಿಯೇ ಇದ್ದರೆ ಪ್ರವೇಶವನ್ನು ಪರಿಶೀಲಿಸಿ. ವೇಳಾಪಟ್ಟಿ, ದೈನಂದಿನ ರೀಸೆಟ್ ಅಥವಾ ಬಾಕಿ ಬದಲಾವಣೆ ತಡವಾಗಿದೆ ಎನಿಸಿದರೆ ಸ್ಥಿತಿಯನ್ನು ಸರಿಹೊಂದಿಸಲು Demora ತೆರೆಯಿರಿ. ಜಾರಿ ಎಚ್ಚರಿಕೆ ಎಂದರೆ ಮೇಲ್ವಿಚಾರಣೆಗೆ ಗಮನ ಬೇಕು; ಹೊಸ ನಿಯಮ ಸಾಮರ್ಥ್ಯ ಮೀರಿದರೆ ಅದು ಉಳಿದಿದೆ ಎಂದು ಭಾವಿಸದೆ ಅತಿಕ್ರಮಿಸುವ ವೇಳಾಪಟ್ಟಿಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಿ.",
    "A free period suspends daily limits within its scope, and usage during it is credited back using Screen Time checkpoints, not an exact live stopwatch. An unblock makes its selected apps usable but is not the same as free usage. Other overlapping rules can still block them. Recurring free periods live alongside recurring blocks. Edit apps on a recurring block keeps its identity and timing; the old selection stays active through the less-strict delay.": "ಮುಕ್ತ ಅವಧಿ ತನ್ನ ವ್ಯಾಪ್ತಿಯ ದೈನಂದಿನ ಮಿತಿಗಳನ್ನು ತಡೆಹಿಡಿಯುತ್ತದೆ, ಮತ್ತು ಅದರಲ್ಲಿನ ಬಳಕೆಯನ್ನು ನಿಖರ ಲೈವ್ ಸ್ಟಾಪ್‌ವಾಚ್ ಅಲ್ಲ, ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಚೆಕ್‌ಪಾಯಿಂಟ್‌ಗಳ ಮೂಲಕ ಹಿಂದಿರುಗಿಸಲಾಗುತ್ತದೆ. ಅನ್‌ಬ್ಲಾಕ್ ಆಯ್ದ ಆ್ಯಪ್‌ಗಳನ್ನು ಬಳಸಲು ಬಿಡುತ್ತದೆ, ಆದರೆ ಮುಕ್ತ ಬಳಕೆಗೆ ಸಮನಲ್ಲ. ಅತಿಕ್ರಮಿಸುವ ಇತರ ನಿಯಮಗಳು ಇನ್ನೂ ಅವನ್ನು ತಡೆಯಬಹುದು. ಪುನರಾವರ್ತಿತ ಮುಕ್ತ ಅವಧಿಗಳು ಪುನರಾವರ್ತಿತ ಬ್ಲಾಕ್‌ಗಳ ಜೊತೆಗೇ ಇರುತ್ತವೆ. ಪುನರಾವರ್ತಿತ ಬ್ಲಾಕ್‌ನ ಆ್ಯಪ್‌ಗಳನ್ನು ಬದಲಿಸಿದರೆ ಅದರ ಗುರುತು ಮತ್ತು ಸಮಯ ಹಾಗೇ ಉಳಿಯುತ್ತದೆ; ಹಳೆಯ ಆಯ್ಕೆ ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆ ಮುಗಿಯುವವರೆಗೆ ಜಾರಿಯಲ್ಲಿರುತ್ತದೆ.",
    "About how much time do you spend on your phone each week?": "ವಾರದಲ್ಲಿ ನಿಮ್ಮ ಫೋನ್‌ನಲ್ಲಿ ಸುಮಾರು ಎಷ್ಟು ಸಮಯ ಕಳೆಯುತ್ತೀರಿ?",
    "Add an optional weekly estimate": "ಐಚ್ಛಿಕ ವಾರದ ಅಂದಾಜನ್ನು ಸೇರಿಸಿ",
    "App choices and usage stay on-device. Demora has no accounts, advertising or analytics. Optional contact invitations and approval requests relay the names, descriptions and notes you send through CloudKit or Cloudflare and Resend; the email provider receives the readable message and code. Time checks contact Apple's website, and email requests use App Attest verification. Widgets use a small local summary, not app-selection tokens or raw usage.": "ಆ್ಯಪ್ ಆಯ್ಕೆಗಳು ಮತ್ತು ಬಳಕೆ ಸಾಧನದಲ್ಲೇ ಇರುತ್ತವೆ. Demora ದಲ್ಲಿ ಖಾತೆಗಳು, ಜಾಹೀರಾತು ಅಥವಾ ಅನಾಲಿಟಿಕ್ಸ್ ಇಲ್ಲ. ಐಚ್ಛಿಕ ಸಂಪರ್ಕ ಆಹ್ವಾನಗಳು ಮತ್ತು ಒಪ್ಪಿಗೆ ವಿನಂತಿಗಳು ನೀವು ಕಳುಹಿಸುವ ಹೆಸರುಗಳು, ವಿವರಣೆಗಳು ಮತ್ತು ಟಿಪ್ಪಣಿಗಳನ್ನು CloudKit ಅಥವಾ Cloudflare ಮತ್ತು Resend ಮೂಲಕ ರವಾನಿಸುತ್ತವೆ; ಇಮೇಲ್ ಒದಗಿಸುವವರು ಓದಬಹುದಾದ ಸಂದೇಶ ಮತ್ತು ಕೋಡ್ ಪಡೆಯುತ್ತಾರೆ. ಸಮಯ ಪರಿಶೀಲನೆಗಳು Apple ನ ವೆಬ್‌ಸೈಟ್ ಅನ್ನು ಸಂಪರ್ಕಿಸುತ್ತವೆ, ಮತ್ತು ಇಮೇಲ್ ವಿನಂತಿಗಳು App Attest ಪರಿಶೀಲನೆ ಬಳಸುತ್ತವೆ. ವಿಜೆಟ್‌ಗಳು ಸಣ್ಣ ಸ್ಥಳೀಯ ಸಾರಾಂಶ ಬಳಸುತ್ತವೆ, ಆ್ಯಪ್-ಆಯ್ಕೆ ಟೋಕನ್‌ಗಳು ಅಥವಾ ಕಚ್ಚಾ ಬಳಕೆಯನ್ನು ಅಲ್ಲ.",
    "Blocking needs Screen Time permission. You may finish setup after declining it; Demora respects denial and does not automatically redirect you to iOS Settings. If you want to enable access later, use Demora's permission prompt or open iOS Settings yourself. iOS controls authorization and background callbacks, so blocking is not an unbypassable guarantee.": "ಬ್ಲಾಕ್ ಮಾಡಲು ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಅನುಮತಿ ಬೇಕು. ಅದನ್ನು ನಿರಾಕರಿಸಿದ ನಂತರವೂ ಸೆಟಪ್ ಮುಗಿಸಬಹುದು; Demora ನಿರಾಕರಣೆಯನ್ನು ಗೌರವಿಸುತ್ತದೆ ಮತ್ತು ನಿಮ್ಮನ್ನು iOS ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ತಾನಾಗಿ ಕಳುಹಿಸುವುದಿಲ್ಲ. ನಂತರ ಪ್ರವೇಶ ಬೇಕಿದ್ದರೆ Demora ದ ಅನುಮತಿ ಪ್ರಾಂಪ್ಟ್ ಬಳಸಿ ಅಥವಾ iOS ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ನೀವೇ ತೆರೆಯಿರಿ. ಅಧಿಕಾರ ಮತ್ತು ಹಿನ್ನೆಲೆ ಕಾಲ್‌ಬ್ಯಾಕ್‌ಗಳನ್ನು iOS ನಿಯಂತ್ರಿಸುತ್ತದೆ, ಹಾಗಾಗಿ ಬ್ಲಾಕ್ ಮಾಡುವುದು ಮೀರಲಾಗದ ಖಾತರಿ ಅಲ್ಲ.",
    "Change: %@%%": "ಬದಲಾವಣೆ: %@%%",
    "Choose approval permissions separately for each contact. Extra-time permission is opt-in, including for existing contacts, and a limit's extra-time step must also require contact approval. Demora-user contacts accept an invitation before approving in their app. For email approval, enter the short code in your Demora. Permission edits are delay-gated; an approval skips only the eligible request's wait, not every rule.": "ಪ್ರತಿ ಸಂಪರ್ಕಕ್ಕೆ ಒಪ್ಪಿಗೆಯ ಅನುಮತಿಗಳನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಆರಿಸಿ. ಈಗಿರುವ ಸಂಪರ್ಕಗಳಿಗೂ ಹೆಚ್ಚುವರಿ ಸಮಯದ ಅನುಮತಿ ಐಚ್ಛಿಕ ಆಯ್ಕೆ, ಮತ್ತು ಮಿತಿಯ ಹೆಚ್ಚುವರಿ ಸಮಯದ ಹಂತಕ್ಕೂ ಸಂಪರ್ಕದ ಒಪ್ಪಿಗೆ ಅಗತ್ಯ. Demora ಬಳಕೆದಾರ ಸಂಪರ್ಕಗಳು ತಮ್ಮ ಆ್ಯಪ್‌ನಲ್ಲಿ ಒಪ್ಪುವ ಮೊದಲು ಆಹ್ವಾನ ಸ್ವೀಕರಿಸುತ್ತಾರೆ. ಇಮೇಲ್ ಒಪ್ಪಿಗೆಗೆ ನಿಮ್ಮ Demora ದಲ್ಲಿ ಚಿಕ್ಕ ಕೋಡ್ ನಮೂದಿಸಿ. ಅನುಮತಿ ಬದಲಾವಣೆಗಳು ಕಾಯುವಿಕೆಗೆ ಒಳಪಡುತ್ತವೆ; ಒಪ್ಪಿಗೆ ಅರ್ಹ ವಿನಂತಿಯ ಕಾಯುವಿಕೆಯನ್ನು ಮಾತ್ರ ಬಿಡಿಸುತ್ತದೆ, ಎಲ್ಲ ನಿಯಮಗಳನ್ನಲ್ಲ.",
    "Completed-day comparison": "ಪೂರ್ಣಗೊಂಡ ದಿನಗಳ ಹೋಲಿಕೆ",
    "Couldn't save your estimate. Try again.": "ನಿಮ್ಮ ಅಂದಾಜನ್ನು ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Delay policy": "ಕಾಯುವಿಕೆ ನೀತಿ",
    "Expand Split daily budget to divide the allowance into time-of-day portions, with optional carryover of unused early minutes. New limits can use three portions; existing two-portion limits remain editable. Spending an early portion blocks until its next boundary, even if later portions have minutes left. Editing a spent limit does not give it a fresh daily allowance. Selection edits follow the less-strict delay and can discard free-period credit tied to the old selection.": "ದೈನಂದಿನ ಮಿತಿಯನ್ನು ದಿನದ ಸಮಯದ ಭಾಗಗಳಾಗಿ ಹಂಚಲು ಹಂಚಿದ ದೈನಂದಿನ ಬಜೆಟ್ ಅನ್ನು ವಿಸ್ತರಿಸಿ; ಬಳಸದ ಆರಂಭಿಕ ನಿಮಿಷಗಳನ್ನು ಮುಂದೆ ಒಯ್ಯಬಹುದು. ಹೊಸ ಮಿತಿಗಳಿಗೆ ಮೂರು ಭಾಗಗಳನ್ನು ಬಳಸಬಹುದು; ಈಗಿರುವ ಎರಡು ಭಾಗಗಳ ಮಿತಿಗಳನ್ನು ಇನ್ನೂ ಬದಲಿಸಬಹುದು. ಆರಂಭಿಕ ಭಾಗ ಮುಗಿದರೆ, ನಂತರದ ಭಾಗಗಳಲ್ಲಿ ನಿಮಿಷಗಳು ಉಳಿದಿದ್ದರೂ ಮುಂದಿನ ಗಡಿಯವರೆಗೆ ಬ್ಲಾಕ್ ಆಗುತ್ತದೆ. ಮುಗಿದ ಮಿತಿಯನ್ನು ಬದಲಿಸಿದರೆ ಹೊಸ ದೈನಂದಿನ ಮಿತಿ ಸಿಗುವುದಿಲ್ಲ. ಆಯ್ಕೆ ಬದಲಾವಣೆಗಳು ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯನ್ನು ಅನುಸರಿಸುತ್ತವೆ ಮತ್ತು ಹಳೆಯ ಆಯ್ಕೆಗೆ ಸಂಬಂಧಿಸಿದ ಮುಕ್ತ-ಅವಧಿ ಕ್ರೆಡಿಟ್ ಅನ್ನು ಕೈಬಿಡಬಹುದು.",
    "Hours and minutes per week, not per day.": "ಗಂಟೆ ಮತ್ತು ನಿಮಿಷಗಳು ವಾರಕ್ಕೆ, ದಿನಕ್ಕೆ ಅಲ್ಲ.",
    "Notifications & widgets": "ಅಧಿಸೂಚನೆಗಳು ಮತ್ತು ವಿಜೆಟ್‌ಗಳು",
    "Partial source coverage": "ಭಾಗಶಃ ಮೂಲ ವ್ಯಾಪ್ತಿ",
    "Passwords & phrases": "ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಮತ್ತು ವಾಕ್ಯಗಳು",
    "Privacy": "ಗೌಪ್ಯತೆ",
    "Screen Time reports and a personal baseline": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ವರದಿಗಳು ಮತ್ತು ವೈಯಕ್ತಿಕ ಆರಂಭಿಕ ಬಿಂದು",
    "Self-reported weekly baseline": "ಸ್ವತಃ ವರದಿ ಮಾಡಿದ ವಾರದ ಆರಂಭಿಕ ಬಿಂದು",
    "Sleep starts on the selected evening and ends at the following morning's wake-up start, using that morning's custom time. Group edits follow your delay policy. Wake timing edits preserve spent usage, split accounting, extra-time grants and a running wait's deadline; a new wait applies to the next tap. A delayed latest-time change can end today's gate once it applies. Turning the gate off is delay-gated too.": "ನಿದ್ರೆ ಆಯ್ದ ಸಂಜೆ ಆರಂಭವಾಗಿ, ಮರುದಿನ ಬೆಳಗಿನ ಎಚ್ಚರದ ಆರಂಭದಲ್ಲಿ, ಆ ಬೆಳಗಿನ ಕಸ್ಟಮ್ ಸಮಯ ಬಳಸಿ ಮುಗಿಯುತ್ತದೆ. ಗುಂಪು ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ಕಾಯುವಿಕೆ ನೀತಿಯನ್ನು ಅನುಸರಿಸುತ್ತವೆ. ಎಚ್ಚರದ ಸಮಯ ಬದಲಾವಣೆಗಳು ಬಳಕೆಯಾದ ಸಮಯ, ಹಂಚಿದ ಲೆಕ್ಕ, ಹೆಚ್ಚುವರಿ ಸಮಯದ ಮಂಜೂರಾತಿ ಮತ್ತು ನಡೆಯುತ್ತಿರುವ ಕಾಯುವಿಕೆಯ ಗಡುವನ್ನು ಉಳಿಸುತ್ತವೆ; ಹೊಸ ಕಾಯುವಿಕೆ ಮುಂದಿನ ಟ್ಯಾಪ್‌ಗೆ ಅನ್ವಯಿಸುತ್ತದೆ. ವಿಳಂಬಗೊಂಡ ಕೊನೆಯ-ಸಮಯದ ಬದಲಾವಣೆ ಜಾರಿಗೆ ಬಂದ ನಂತರ ಇಂದಿನ ಗೇಟ್ ಅನ್ನು ಮುಗಿಸಬಹುದು. ಗೇಟ್ ಆಫ್ ಮಾಡುವುದೂ ಕಾಯುವಿಕೆಗೆ ಒಳಪಡುತ್ತದೆ.",
    "The app deletion lock asks iOS to prevent deleting apps, including Demora. Turning it off is a less-strict change. It discourages one bypass route but does not make Screen Time permissions or the device impossible to change. Notifications and widgets are optional aids, not the enforcement mechanism.": "ಆ್ಯಪ್ ಅಳಿಸುವಿಕೆ ಲಾಕ್, Demora ಸೇರಿದಂತೆ ಆ್ಯಪ್‌ಗಳನ್ನು ಅಳಿಸದಂತೆ ತಡೆಯಲು iOS ಅನ್ನು ಕೇಳುತ್ತದೆ. ಅದನ್ನು ಆಫ್ ಮಾಡುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ. ಇದು ಒಂದು ತಪ್ಪಿಸಿಕೊಳ್ಳುವ ದಾರಿಯನ್ನು ಕಷ್ಟಪಡಿಸುತ್ತದೆ, ಆದರೆ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಅನುಮತಿಗಳು ಅಥವಾ ಸಾಧನವನ್ನು ಬದಲಿಸಲಾಗದಂತೆ ಮಾಡುವುದಿಲ್ಲ. ಅಧಿಸೂಚನೆಗಳು ಮತ್ತು ವಿಜೆಟ್‌ಗಳು ಐಚ್ಛಿಕ ಸಹಾಯಕಗಳು, ಜಾರಿಯ ವ್ಯವಸ್ಥೆ ಅಲ್ಲ.",
    "Today is not included in this comparison.": "ಈ ಹೋಲಿಕೆಯಲ್ಲಿ ಇಂದು ಸೇರಿಲ್ಲ.",
    "Today so far": "ಇಂದಿನವರೆಗೆ",
    "Troubleshooting": "ದೋಷ ನಿವಾರಣೆ",
    "Usage reports": "ಬಳಕೆ ವರದಿಗಳು",
    "Most used apps": "ಹೆಚ್ಚು ಬಳಸಿದ ಆ್ಯಪ್‌ಗಳು",
    "All apps": "ಎಲ್ಲಾ ಆ್ಯಪ್‌ಗಳು",
    "Use Prioritize this to apply a rule after rules at default priority, or Restore default priority to undo that choice. Both actions always queue a less-strict change, even if you expect a stricter result. Among prioritized rules, the last one promoted applies last. Priority changes ordering, not a rule's app selection or your spent daily allowance.": "ಡೀಫಾಲ್ಟ್ ಆದ್ಯತೆಯ ನಿಯಮಗಳ ನಂತರ ನಿಯಮವನ್ನು ಅನ್ವಯಿಸಲು ಇದಕ್ಕೆ ಆದ್ಯತೆ ನೀಡಿ ಬಳಸಿ, ಅಥವಾ ಆ ಆಯ್ಕೆಯನ್ನು ರದ್ದುಗೊಳಿಸಲು ಡೀಫಾಲ್ಟ್ ಆದ್ಯತೆ ಮರುಸ್ಥಾಪಿಸಿ ಬಳಸಿ. ಎರಡೂ ಕ್ರಿಯೆಗಳು ಯಾವಾಗಲೂ ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆಯನ್ನು ಸರದಿಯಲ್ಲಿ ಇಡುತ್ತವೆ, ಫಲಿತಾಂಶ ಕಠಿಣವಾಗುತ್ತದೆ ಎಂದು ನೀವು ನಿರೀಕ್ಷಿಸಿದರೂ ಸಹ. ಆದ್ಯತೆ ಪಡೆದ ನಿಯಮಗಳಲ್ಲಿ, ಕೊನೆಯದಾಗಿ ಬಡ್ತಿ ಪಡೆದದ್ದು ಕೊನೆಯಲ್ಲಿ ಅನ್ವಯಿಸುತ್ತದೆ. ಆದ್ಯತೆ ಕ್ರಮವನ್ನು ಬದಲಿಸುತ್ತದೆ, ನಿಯಮದ ಆ್ಯಪ್ ಆಯ್ಕೆ ಅಥವಾ ಬಳಸಿದ ದೈನಂದಿನ ಮಿತಿಯನ್ನಲ್ಲ.",
    "Weekly baseline": "ವಾರದ ಆರಂಭಿಕ ಬಿಂದು",
    "Your starting point": "ನಿಮ್ಮ ಆರಂಭಿಕ ಬಿಂದು",
    "choose a policy, manage pending changes": "ನೀತಿ ಆರಿಸಿ, ಬಾಕಿ ಬದಲಾವಣೆಗಳನ್ನು ನಿರ್ವಹಿಸಿ",
    "optional reminders and privacy": "ಐಚ್ಛಿಕ ಜ್ಞಾಪನೆಗಳು ಮತ್ತು ಗೌಪ್ಯತೆ",
    "overlaps, scopes and priority": "ಅತಿಕ್ರಮಣಗಳು, ವ್ಯಾಪ್ತಿಗಳು ಮತ್ತು ಆದ್ಯತೆ",
    "permissions, blank reports and false blocks": "ಅನುಮತಿಗಳು, ಖಾಲಿ ವರದಿಗಳು ಮತ್ತು ತಪ್ಪು ಬ್ಲಾಕ್‌ಗಳು",
    "wake waits, latest times and sleep": "ಎಚ್ಚರದ ಕಾಯುವಿಕೆಗಳು, ಕೊನೆಯ ಸಮಯಗಳು ಮತ್ತು ನಿದ್ರೆ",
    "Latest wake-up: %@": "ಕೊನೆಯ ಎಚ್ಚರದ ಸಮಯ: %@",
    // Home report controls and default wake-up timing.
    "Expand": "ವಿಸ್ತರಿಸಿ",
    "Collapse": "ಮಡಿಸಿ",
    "Expanded": "ವಿಸ್ತರಿಸಲಾಗಿದೆ",
    "Compact": "ಸಂಕ್ಷಿಪ್ತ",
    "Start your morning": "ನಿಮ್ಮ ಬೆಳಗನ್ನು ಆರಂಭಿಸಿ",
    "Usage stays in the Screen Time report. Scroll to see more groups. If it looks empty, try Refresh; an empty report does not mean zero usage.": "ಬಳಕೆ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ವರದಿಯೊಳಗೇ ಇರುತ್ತದೆ. ಹೆಚ್ಚಿನ ಗುಂಪುಗಳನ್ನು ನೋಡಲು ಸ್ಕ್ರಾಲ್ ಮಾಡಿ. ಖಾಲಿ ಕಂಡರೆ ರಿಫ್ರೆಶ್ ಪ್ರಯತ್ನಿಸಿ; ಖಾಲಿ ವರದಿ ಎಂದರೆ ಶೂನ್ಯ ಬಳಕೆ ಅಲ್ಲ.",
    "Days without custom times use the default start, wait and latest time above.": "ಕಸ್ಟಮ್ ಸಮಯವಿಲ್ಲದ ದಿನಗಳು ಮೇಲಿನ ಡೀಫಾಲ್ಟ್ ಆರಂಭ, ಕಾಯುವಿಕೆ ಮತ್ತು ಕೊನೆಯ ಸಮಯವನ್ನು ಬಳಸುತ್ತವೆ.",
    "Wake-up overlaps are estimates until you tap Wake up. Allowlisted apps still obey other specific blocks and daily limits.": "ನೀವು ಎಚ್ಚರ ಟ್ಯಾಪ್ ಮಾಡುವವರೆಗೆ ಎಚ್ಚರದ ಅತಿಕ್ರಮಣಗಳು ಅಂದಾಜುಗಳು. ಅನುಮತಿಸಿದ ಆ್ಯಪ್‌ಗಳು ಇತರ ನಿರ್ದಿಷ್ಟ ಬ್ಲಾಕ್‌ಗಳು ಮತ್ತು ದೈನಂದಿನ ಮಿತಿಗಳನ್ನು ಇನ್ನೂ ಪಾಲಿಸುತ್ತವೆ.",
    "Restore default priority": "ಡೀಫಾಲ್ಟ್ ಆದ್ಯತೆ ಮರುಸ್ಥಾಪಿಸಿ",
    // Migration delay choices, wake-up ceilings, and schedule priority.
    "Optional. Keep separate waits, use one shared wait, or tighten immediately and wait only when loosening rules. If you skip this, your delay settings stay unchanged.": "ಐಚ್ಛಿಕ. ಪ್ರತ್ಯೇಕ ಕಾಯುವಿಕೆಗಳನ್ನು ಇಡಿ, ಒಂದೇ ಹಂಚಿದ ಕಾಯುವಿಕೆ ಬಳಸಿ, ಅಥವಾ ತಕ್ಷಣ ಬಿಗಿಗೊಳಿಸಿ ನಿಯಮ ಸಡಿಲಿಸುವಾಗ ಮಾತ್ರ ಕಾಯಿರಿ. ಇದನ್ನು ಬಿಟ್ಟರೆ ನಿಮ್ಮ ಕಾಯುವಿಕೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಹಾಗೇ ಇರುತ್ತವೆ.",
    "Your saved rules and pending changes are retained. Unless you queue a change, your existing delay settings stay unchanged.": "ನಿಮ್ಮ ಉಳಿಸಿದ ನಿಯಮಗಳು ಮತ್ತು ಬಾಕಿ ಬದಲಾವಣೆಗಳು ಉಳಿಯುತ್ತವೆ. ನೀವು ಬದಲಾವಣೆಯನ್ನು ಸರದಿಯಲ್ಲಿ ಇಡದ ಹೊರತು ನಿಮ್ಮ ಈಗಿನ ಕಾಯುವಿಕೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಹಾಗೇ ಇರುತ್ತವೆ.",
    "Demo only. Try the delay choices here; nothing is queued or saved. Go back to keep exploring the welcome.": "ಡೆಮೊ ಮಾತ್ರ. ಇಲ್ಲಿ ಕಾಯುವಿಕೆ ಆಯ್ಕೆಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ; ಯಾವುದೂ ಸರದಿಯಲ್ಲಿ ಹೋಗುವುದಿಲ್ಲ ಅಥವಾ ಉಳಿಯುವುದಿಲ್ಲ. ಸ್ವಾಗತವನ್ನು ಅನ್ವೇಷಿಸುತ್ತಿರಲು ಹಿಂದೆ ಹೋಗಿ.",
    "A new wait applies to the next tap. A latest wake-up time can end today's gate once this delayed change applies. Turning this off still follows your less-strict delay.": "ಹೊಸ ಕಾಯುವಿಕೆ ಮುಂದಿನ ಟ್ಯಾಪ್‌ಗೆ ಅನ್ವಯಿಸುತ್ತದೆ. ಈ ವಿಳಂಬಿತ ಬದಲಾವಣೆ ಜಾರಿಗೆ ಬಂದ ನಂತರ ಕೊನೆಯ ಎಚ್ಚರದ ಸಮಯ ಇಂದಿನ ಗೇಟ್ ಅನ್ನು ಮುಗಿಸಬಹುದು. ಇದನ್ನು ಆಫ್ ಮಾಡುವುದೂ ನಿಮ್ಮ ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯನ್ನು ಅನುಸರಿಸುತ್ತದೆ.",
    "A running wait keeps its deadline, but never extends past its configured latest wake-up time. Other blocks still apply.": "ನಡೆಯುತ್ತಿರುವ ಕಾಯುವಿಕೆ ತನ್ನ ಗಡುವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ, ಆದರೆ ಸೆಟ್ ಮಾಡಿದ ಕೊನೆಯ ಎಚ್ಚರದ ಸಮಯವನ್ನು ಎಂದೂ ಮೀರುವುದಿಲ್ಲ. ಇತರ ಬ್ಲಾಕ್‌ಗಳು ಇನ್ನೂ ಅನ್ವಯಿಸುತ್ತವೆ.",
    "Set a latest wake-up time": "ಕೊನೆಯ ಎಚ್ಚರದ ಸಮಯವನ್ನು ಹೊಂದಿಸಿ",
    "Wake blocking ends by": "ಎಚ್ಚರದ ಬ್ಲಾಕ್ ಮುಗಿಯುವ ಸಮಯ",
    "At this time, this wake-up block ends even if you haven't tapped Wake up or its wait is still running.": "ಈ ಸಮಯದಲ್ಲಿ, ನೀವು ಎಚ್ಚರ ಟ್ಯಾಪ್ ಮಾಡದಿದ್ದರೂ ಅಥವಾ ಕಾಯುವಿಕೆ ಇನ್ನೂ ನಡೆಯುತ್ತಿದ್ದರೂ ಈ ಎಚ್ಚರದ ಬ್ಲಾಕ್ ಮುಗಿಯುತ್ತದೆ.",
    "Choose a latest time after the wake-up day begins.": "ಎಚ್ಚರದ ದಿನ ಆರಂಭವಾದ ನಂತರದ ಕೊನೆಯ ಸಮಯವನ್ನು ಆರಿಸಿ.",
    "Prioritize %@": "%@ ಗೆ ಆದ್ಯತೆ ನೀಡಿ",
    "Restore default priority for %@": "%@ ಗೆ ಡೀಫಾಲ್ಟ್ ಆದ್ಯತೆ ಮರುಸ್ಥಾಪಿಸಿ",
    "Schedule conflicts": "ವೇಳಾಪಟ್ಟಿ ಸಂಘರ್ಷಗಳು",
    "Potential overlaps": "ಸಂಭಾವ್ಯ ಅತಿಕ್ರಮಣಗಳು",
    "No conflicting schedules found.": "ಸಂಘರ್ಷಿಸುವ ವೇಳಾಪಟ್ಟಿಗಳು ಕಂಡುಬಂದಿಲ್ಲ.",
    "Default order: wake-up → recurring → planned → sessions.": "ಡೀಫಾಲ್ಟ್ ಕ್ರಮ: ಎಚ್ಚರ → ಪುನರಾವರ್ತಿತ → ಯೋಜಿತ → ಸೆಷನ್‌ಗಳು.",
    "Prioritize this": "ಇದಕ್ಕೆ ಆದ್ಯತೆ ನೀಡಿ",
    "Default priority": "ಡೀಫಾಲ್ಟ್ ಆದ್ಯತೆ",
    "Prioritized": "ಆದ್ಯತೆ ನೀಡಲಾಗಿದೆ",
    "Priority changes follow your less-strict delay.": "ಆದ್ಯತೆ ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯನ್ನು ಅನುಸರಿಸುತ್ತವೆ.",
    "When several rules are prioritized, the last one promoted is applied last.": "ಹಲವು ನಿಯಮಗಳಿಗೆ ಆದ್ಯತೆ ನೀಡಿದರೆ, ಕೊನೆಯದಾಗಿ ಬಡ್ತಿ ಪಡೆದದ್ದು ಕೊನೆಯಲ್ಲಿ ಅನ್ವಯಿಸುತ್ತದೆ.",
    "These rules overlap in time. Apple hides category membership, so some app overlaps cannot be confirmed.": "ಈ ನಿಯಮಗಳು ಸಮಯದಲ್ಲಿ ಅತಿಕ್ರಮಿಸುತ್ತವೆ. Apple ವರ್ಗ ಸದಸ್ಯತ್ವವನ್ನು ಮರೆಮಾಡುತ್ತದೆ, ಹಾಗಾಗಿ ಕೆಲವು ಆ್ಯಪ್ ಅತಿಕ್ರಮಣಗಳನ್ನು ದೃಢೀಕರಿಸಲಾಗದು.",
    "Next occurrence": "ಮುಂದಿನ ಬಾರಿ",
    "Possible overlap": "ಸಂಭಾವ್ಯ ಅತಿಕ್ರಮಣ",
    "Applies last": "ಕೊನೆಯಲ್ಲಿ ಅನ್ವಯ",
    "Priority": "ಆದ್ಯತೆ",
    "See overlapping rules": "ಅತಿಕ್ರಮಿಸುವ ನಿಯಮಗಳನ್ನು ನೋಡಿ",
    "Change wake-up schedule for %@": "%@ ಗಾಗಿ ಎಚ್ಚರದ ವೇಳಾಪಟ್ಟಿ ಬದಲಿಸಿ",
    "Customize wake-up by day": "ದಿನದ ಪ್ರಕಾರ ಎಚ್ಚರವನ್ನು ಹೊಂದಿಸಿ",
    "Days without custom times use the default start and wait above.": "ಕಸ್ಟಮ್ ಸಮಯವಿಲ್ಲದ ದಿನಗಳು ಮೇಲಿನ ಡೀಫಾಲ್ಟ್ ಆರಂಭ ಮತ್ತು ಕಾಯುವಿಕೆಯನ್ನು ಬಳಸುತ್ತವೆ.",
    "A wake-up wait already in progress keeps its original deadline.": "ಈಗಾಗಲೇ ನಡೆಯುತ್ತಿರುವ ಎಚ್ಚರದ ಕಾಯುವಿಕೆ ತನ್ನ ಮೂಲ ಗಡುವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ.",
    "Give each limit or group its own wake-up start, wait and weekdays. One Wake up tap starts all eligible waits. Overlapping rules still apply.": "ಪ್ರತಿ ಮಿತಿ ಅಥವಾ ಗುಂಪಿಗೆ ತನ್ನದೇ ಎಚ್ಚರದ ಆರಂಭ, ಕಾಯುವಿಕೆ ಮತ್ತು ವಾರದ ದಿನಗಳನ್ನು ನೀಡಿ. ಒಂದು ಎಚ್ಚರ ಟ್ಯಾಪ್ ಎಲ್ಲ ಅರ್ಹ ಕಾಯುವಿಕೆಗಳನ್ನು ಆರಂಭಿಸುತ್ತದೆ. ಅತಿಕ್ರಮಿಸುವ ನಿಯಮಗಳು ಇನ್ನೂ ಅನ್ವಯಿಸುತ್ತವೆ.",
    "Sleep ends at the following wake-up start, using that day's custom time if set.": "ನಿದ್ರೆ ಮುಂದಿನ ಎಚ್ಚರದ ಆರಂಭದಲ್ಲಿ ಮುಗಿಯುತ್ತದೆ; ಆ ದಿನ ಕಸ್ಟಮ್ ಸಮಯ ಇದ್ದರೆ ಅದನ್ನು ಬಳಸುತ್ತದೆ.",
    "Custom wake-up times by day": "ದಿನದ ಪ್ರಕಾರ ಕಸ್ಟಮ್ ಎಚ್ಚರದ ಸಮಯಗಳು",
    "Discard day/night drafts": "ಹಗಲು/ರಾತ್ರಿ ಕರಡುಗಳನ್ನು ತಿರಸ್ಕರಿಸಿ",
    // Named day/night groups, shared wake-up, and additive setup.
    "%d apps, %d categories, %d websites": "%d ಆ್ಯಪ್‌ಗಳು, %d ವರ್ಗಗಳು, %d ವೆಬ್‌ಸೈಟ್‌ಗಳು",
    "%d day/night groups": "%d ಹಗಲು/ರಾತ್ರಿ ಗುಂಪುಗಳು",
    "%d limits · %d apps, %d categories, %d websites": "%d ಮಿತಿಗಳು · %d ಆ್ಯಪ್‌ಗಳು, %d ವರ್ಗಗಳು, %d ವೆಬ್‌ಸೈಟ್‌ಗಳು",
    "A change for this group is pending. Its current rules stay in place until that change applies.": "ಈ ಗುಂಪಿನ ಬದಲಾವಣೆ ಬಾಕಿ ಇದೆ. ಅದು ಜಾರಿಗೆ ಬರುವವರೆಗೆ ಈಗಿನ ನಿಯಮಗಳು ಹಾಗೇ ಇರುತ್ತವೆ.",
    "Add a group to give its apps their own wake-up wait and sleep time.": "ಗುಂಪಿನ ಆ್ಯಪ್‌ಗಳಿಗೆ ತಮ್ಮದೇ ಎಚ್ಚರದ ಕಾಯುವಿಕೆ ಮತ್ತು ನಿದ್ರೆ ಸಮಯ ನೀಡಲು ಗುಂಪನ್ನು ಸೇರಿಸಿ.",
    "Add day/night group": "ಹಗಲು/ರಾತ್ರಿ ಗುಂಪು ಸೇರಿಸಿ",
    "All other apps except…": "ಇತರ ಎಲ್ಲಾ ಆ್ಯಪ್‌ಗಳು, ಇವನ್ನು ಬಿಟ್ಟು…",
    "An all-other-apps fallback automatically excludes apps targeted by your named selected groups. Category-based groups cannot be combined with this fallback.": "ಇತರ-ಎಲ್ಲಾ-ಆ್ಯಪ್‌ಗಳ ಫಾಲ್‌ಬ್ಯಾಕ್, ನಿಮ್ಮ ಹೆಸರಿಸಿದ ಆಯ್ದ ಗುಂಪುಗಳು ಗುರಿಯಾಗಿಸಿದ ಆ್ಯಪ್‌ಗಳನ್ನು ತಾನಾಗಿ ಹೊರಗಿಡುತ್ತದೆ. ವರ್ಗ ಆಧಾರಿತ ಗುಂಪುಗಳನ್ನು ಈ ಫಾಲ್‌ಬ್ಯಾಕ್‌ನೊಂದಿಗೆ ಸೇರಿಸಲಾಗದು.",
    "App scope": "ಆ್ಯಪ್ ವ್ಯಾಪ್ತಿ",
    "App selection is unavailable until Screen Time access is allowed.": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪ್ರವೇಶ ಅನುಮತಿಸುವವರೆಗೆ ಆ್ಯಪ್ ಆಯ್ಕೆ ಲಭ್ಯವಿಲ್ಲ.",
    "Apps to exclude": "ಹೊರಗಿಡಬೇಕಾದ ಆ್ಯಪ್‌ಗಳು",
    "Category exceptions are not supported. Choose individual apps or limits without categories; choosing a category cannot allow all of its apps.": "ವರ್ಗ ವಿನಾಯಿತಿಗಳು ಬೆಂಬಲಿತವಲ್ಲ. ವರ್ಗಗಳಿಲ್ಲದ ಪ್ರತ್ಯೇಕ ಆ್ಯಪ್‌ಗಳು ಅಥವಾ ಮಿತಿಗಳನ್ನು ಆರಿಸಿ; ವರ್ಗವನ್ನು ಆರಿಸಿದರೆ ಅದರ ಎಲ್ಲ ಆ್ಯಪ್‌ಗಳನ್ನು ಅನುಮತಿಸಲಾಗದು.",
    "Check existing limits and choose extra apps for this group's boundaries.": "ಈಗಿರುವ ಮಿತಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಈ ಗುಂಪಿನ ಗಡಿಗಳಿಗೆ ಹೆಚ್ಚುವರಿ ಆ್ಯಪ್‌ಗಳನ್ನು ಆರಿಸಿ.",
    "Choose a name, at least one boundary, weekdays and a valid app scope. Sleep and wake-up times must differ.": "ಹೆಸರು, ಕನಿಷ್ಠ ಒಂದು ಗಡಿ, ವಾರದ ದಿನಗಳು ಮತ್ತು ಮಾನ್ಯ ಆ್ಯಪ್ ವ್ಯಾಪ್ತಿಯನ್ನು ಆರಿಸಿ. ನಿದ್ರೆ ಮತ್ತು ಎಚ್ಚರದ ಸಮಯ ಬೇರೆಬೇರೆ ಇರಬೇಕು.",
    "Contains categories — cannot be a fallback exception.": "ವರ್ಗಗಳಿವೆ — ಫಾಲ್‌ಬ್ಯಾಕ್ ವಿನಾಯಿತಿ ಆಗಲಾರದು.",
    "Day/night group": "ಹಗಲು/ರಾತ್ರಿ ಗುಂಪು",
    "Demo: select sample limits above. The real app picker is not opened.": "ಡೆಮೊ: ಮೇಲೆ ಮಾದರಿ ಮಿತಿಗಳನ್ನು ಆರಿಸಿ. ನಿಜವಾದ ಆ್ಯಪ್ ಪಿಕರ್ ತೆರೆಯುವುದಿಲ್ಲ.",
    "Existing limits": "ಈಗಿರುವ ಮಿತಿಗಳು",
    "Existing sleep settings": "ಈಗಿರುವ ನಿದ್ರೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
    "Existing wake-up settings": "ಈಗಿರುವ ಎಚ್ಚರದ ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
    "Existing wake/sleep settings": "ಈಗಿರುವ ಎಚ್ಚರ/ನಿದ್ರೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳು",
    "Extra apps": "ಹೆಚ್ಚುವರಿ ಆ್ಯಪ್‌ಗಳು",
    "Give each group its own wake-up wait and sleep time.": "ಪ್ರತಿ ಗುಂಪಿಗೆ ತನ್ನದೇ ಎಚ್ಚರದ ಕಾಯುವಿಕೆ ಮತ್ತು ನಿದ್ರೆ ಸಮಯ ನೀಡಿ.",
    "Limits to exclude": "ಹೊರಗಿಡಬೇಕಾದ ಮಿತಿಗಳು",
    "No existing limits. You can choose apps below.": "ಈಗಿರುವ ಮಿತಿಗಳಿಲ್ಲ. ಕೆಳಗೆ ಆ್ಯಪ್‌ಗಳನ್ನು ಆರಿಸಬಹುದು.",
    "Not selected": "ಆಯ್ಕೆ ಮಾಡಿಲ್ಲ",
    "One Wake up tap on Today starts every eligible group's wait together. Each group unlocks after its own wait; sleep blocking ends at its wake-up start time.": "ಇಂದು ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಒಂದು ಎಚ್ಚರ ಟ್ಯಾಪ್ ಪ್ರತಿ ಅರ್ಹ ಗುಂಪಿನ ಕಾಯುವಿಕೆಯನ್ನು ಒಟ್ಟಿಗೇ ಆರಂಭಿಸುತ್ತದೆ. ಪ್ರತಿ ಗುಂಪು ತನ್ನದೇ ಕಾಯುವಿಕೆಯ ನಂತರ ತೆರೆಯುತ್ತದೆ; ನಿದ್ರೆಯ ಬ್ಲಾಕ್ ತನ್ನ ಎಚ್ಚರದ ಆರಂಭ ಸಮಯದಲ್ಲಿ ಮುಗಿಯುತ್ತದೆ.",
    "Only one all-other-apps fallback is allowed.": "ಇತರ-ಎಲ್ಲಾ-ಆ್ಯಪ್‌ಗಳ ಒಂದು ಫಾಲ್‌ಬ್ಯಾಕ್ ಮಾತ್ರ ಅನುಮತಿ.",
    "Optional — add day/night groups now, or set them up later in Rules.": "ಐಚ್ಛಿಕ — ಈಗ ಹಗಲು/ರಾತ್ರಿ ಗುಂಪುಗಳನ್ನು ಸೇರಿಸಿ, ಅಥವಾ ನಂತರ ನಿಯಮಗಳಲ್ಲಿ ಹೊಂದಿಸಿ.",
    "Overlapping rules use the strictest boundary. An exception here does not bypass another group or limit.": "ಅತಿಕ್ರಮಿಸುವ ನಿಯಮಗಳು ಅತಿ ಕಠಿಣ ಗಡಿಯನ್ನು ಬಳಸುತ್ತವೆ. ಇಲ್ಲಿನ ವಿನಾಯಿತಿ ಇನ್ನೊಂದು ಗುಂಪು ಅಥವಾ ಮಿತಿಯನ್ನು ಮೀರುವುದಿಲ್ಲ.",
    "Remove category exceptions": "ವರ್ಗ ವಿನಾಯಿತಿಗಳನ್ನು ತೆಗೆಯಿರಿ",
    "Remove category exceptions before saving this fallback group.": "ಈ ಫಾಲ್‌ಬ್ಯಾಕ್ ಗುಂಪನ್ನು ಉಳಿಸುವ ಮೊದಲು ವರ್ಗ ವಿನಾಯಿತಿಗಳನ್ನು ತೆಗೆಯಿರಿ.",
    "Remove day/night group?": "ಹಗಲು/ರಾತ್ರಿ ಗುಂಪನ್ನು ತೆಗೆಯಬೇಕೇ?",
    "Remove group": "ಗುಂಪನ್ನು ತೆಗೆಯಿರಿ",
    "Remove missing limits": "ಕಾಣೆಯಾದ ಮಿತಿಗಳನ್ನು ತೆಗೆಯಿರಿ",
    "Review these groups: choose valid apps, timings and exceptions before continuing.": "ಈ ಗುಂಪುಗಳನ್ನು ಪರಿಶೀಲಿಸಿ: ಮುಂದುವರಿಯುವ ಮೊದಲು ಮಾನ್ಯ ಆ್ಯಪ್‌ಗಳು, ಸಮಯಗಳು ಮತ್ತು ವಿನಾಯಿತಿಗಳನ್ನು ಆರಿಸಿ.",
    "Selected": "ಆಯ್ಕೆ ಮಾಡಲಾಗಿದೆ",
    "Selected limits and extra apps": "ಆಯ್ದ ಮಿತಿಗಳು ಮತ್ತು ಹೆಚ್ಚುವರಿ ಆ್ಯಪ್‌ಗಳು",
    "Sleep %@–%@": "ನಿದ್ರೆ %@–%@",
    "Some selected limits no longer exist. Remove their references before saving.": "ಆಯ್ದ ಕೆಲವು ಮಿತಿಗಳು ಇನ್ನಿಲ್ಲ. ಉಳಿಸುವ ಮೊದಲು ಅವುಗಳ ಉಲ್ಲೇಖಗಳನ್ನು ತೆಗೆಯಿರಿ.",
    "The all-other-apps fallback cannot exclude whole categories used by these groups: %@. Choose individual apps instead, or remove the fallback.": "ಇತರ-ಎಲ್ಲಾ-ಆ್ಯಪ್‌ಗಳ ಫಾಲ್‌ಬ್ಯಾಕ್, ಈ ಗುಂಪುಗಳು ಬಳಸುವ ಸಂಪೂರ್ಣ ವರ್ಗಗಳನ್ನು ಹೊರಗಿಡಲಾಗದು: %@. ಬದಲಿಗೆ ಪ್ರತ್ಯೇಕ ಆ್ಯಪ್‌ಗಳನ್ನು ಆರಿಸಿ, ಅಥವಾ ಫಾಲ್‌ಬ್ಯಾಕ್ ಅನ್ನು ತೆಗೆಯಿರಿ.",
    "The fallback automatically excludes apps targeted by your other named day/night groups. Check limits and choose individual apps for additional exceptions. Other rules still apply.": "ಫಾಲ್‌ಬ್ಯಾಕ್ ನಿಮ್ಮ ಇತರ ಹೆಸರಿಸಿದ ಹಗಲು/ರಾತ್ರಿ ಗುಂಪುಗಳ ಗುರಿ ಆ್ಯಪ್‌ಗಳನ್ನು ತಾನಾಗಿ ಹೊರಗಿಡುತ್ತದೆ. ಮಿತಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಹೆಚ್ಚುವರಿ ವಿನಾಯಿತಿಗಳಿಗೆ ಪ್ರತ್ಯೇಕ ಆ್ಯಪ್‌ಗಳನ್ನು ಆರಿಸಿ. ಇತರ ನಿಯಮಗಳು ಇನ್ನೂ ಅನ್ವಯಿಸುತ್ತವೆ.",
    "These existing settings still apply alongside your day/night groups.": "ಈ ಈಗಿರುವ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ನಿಮ್ಮ ಹಗಲು/ರಾತ್ರಿ ಗುಂಪುಗಳ ಜೊತೆಗೇ ಅನ್ವಯಿಸುತ್ತವೆ.",
    "This group could not be saved. Review pending changes and your app selection, then try again.": "ಈ ಗುಂಪನ್ನು ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಬಾಕಿ ಬದಲಾವಣೆಗಳು ಮತ್ತು ನಿಮ್ಮ ಆ್ಯಪ್ ಆಯ್ಕೆಯನ್ನು ಪರಿಶೀಲಿಸಿ, ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Use a name of 80 characters or fewer.": "80 ಅಕ್ಷರಗಳು ಅಥವಾ ಕಡಿಮೆ ಇರುವ ಹೆಸರನ್ನು ಬಳಸಿ.",
    "Wait for the pending day/night change before adding, editing or removing another group.": "ಇನ್ನೊಂದು ಗುಂಪನ್ನು ಸೇರಿಸುವ, ಬದಲಿಸುವ ಅಥವಾ ತೆಗೆಯುವ ಮೊದಲು ಬಾಕಿ ಇರುವ ಹಗಲು/ರಾತ್ರಿ ಬದಲಾವಣೆಗಾಗಿ ಕಾಯಿರಿ.",
    "Wake from %@ · wait %d minutes after tap": "%@ ರಿಂದ ಎಚ್ಚರ · ಟ್ಯಾಪ್ ನಂತರ %d ನಿಮಿಷ ಕಾಯುವಿಕೆ",
    "Weekdays apply to the wake-up morning and the evening when sleep begins.": "ವಾರದ ದಿನಗಳು ಎಚ್ಚರದ ಬೆಳಗಿಗೆ ಮತ್ತು ನಿದ್ರೆ ಆರಂಭವಾಗುವ ಸಂಜೆಗೆ ಅನ್ವಯಿಸುತ್ತವೆ.",
    "You can create up to five day/night groups.": "ಐದು ಹಗಲು/ರಾತ್ರಿ ಗುಂಪುಗಳವರೆಗೆ ರಚಿಸಬಹುದು.",
    "e.g. Social apps at night": "ಉದಾ. ರಾತ್ರಿ ಸಾಮಾಜಿಕ ಆ್ಯಪ್‌ಗಳು",
    "Wake-up tap needed": "ಎಚ್ಚರ ಟ್ಯಾಪ್ ಬೇಕು",
    "Wake-up could not be saved. Try again.": "ಎಚ್ಚರವನ್ನು ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Make room for your mornings and nights.": "ನಿಮ್ಮ ಬೆಳಗುಗಳು ಮತ್ತು ರಾತ್ರಿಗಳಿಗೆ ಸ್ಥಳ ಮಾಡಿ.",
    "Optional: choose your limit groups and extra apps, then give each day/night group its own timing. One Wake up tap starts all eligible waits.": "ಐಚ್ಛಿಕ: ನಿಮ್ಮ ಮಿತಿ ಗುಂಪುಗಳು ಮತ್ತು ಹೆಚ್ಚುವರಿ ಆ್ಯಪ್‌ಗಳನ್ನು ಆರಿಸಿ, ನಂತರ ಪ್ರತಿ ಹಗಲು/ರಾತ್ರಿ ಗುಂಪಿಗೆ ತನ್ನದೇ ಸಮಯ ನೀಡಿ. ಒಂದು ಎಚ್ಚರ ಟ್ಯಾಪ್ ಎಲ್ಲ ಅರ್ಹ ಕಾಯುವಿಕೆಗಳನ್ನು ಆರಂಭಿಸುತ್ತದೆ.",
    "Review your day/night groups after changing your limits.": "ನಿಮ್ಮ ಮಿತಿಗಳನ್ನು ಬದಲಿಸಿದ ನಂತರ ಹಗಲು/ರಾತ್ರಿ ಗುಂಪುಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.",
    "You can change this later in Rules → Day & night. Later changes follow your delays.": "ಇದನ್ನು ನಂತರ ನಿಯಮಗಳು → ಹಗಲು ಮತ್ತು ರಾತ್ರಿ ಯಲ್ಲಿ ಬದಲಿಸಬಹುದು. ನಂತರದ ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತವೆ.",
    "One Wake up tap starts all eligible groups together. Give each group its own wait and sleep time.": "ಒಂದು ಎಚ್ಚರ ಟ್ಯಾಪ್ ಎಲ್ಲ ಅರ್ಹ ಗುಂಪುಗಳನ್ನು ಒಟ್ಟಿಗೇ ಆರಂಭಿಸುತ್ತದೆ. ಪ್ರತಿ ಗುಂಪಿಗೆ ತನ್ನದೇ ಕಾಯುವಿಕೆ ಮತ್ತು ನಿದ್ರೆ ಸಮಯ ನೀಡಿ.",
    "You can add your initial day/night groups now without waiting. Existing rules and wake-up countdowns stay unchanged. Later changes follow your delays.": "ನಿಮ್ಮ ಆರಂಭಿಕ ಹಗಲು/ರಾತ್ರಿ ಗುಂಪುಗಳನ್ನು ಈಗ ಕಾಯದೆ ಸೇರಿಸಬಹುದು. ಈಗಿರುವ ನಿಯಮಗಳು ಮತ್ತು ಎಚ್ಚರದ ಕೌಂಟ್‌ಡೌನ್‌ಗಳು ಬದಲಾಗುವುದಿಲ್ಲ. ನಂತರದ ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತವೆ.",
    "Your day/night groups are ready.": "ನಿಮ್ಮ ಹಗಲು/ರಾತ್ರಿ ಗುಂಪುಗಳು ಸಿದ್ಧ.",
    "Add or change day/night group: %@": "ಹಗಲು/ರಾತ್ರಿ ಗುಂಪನ್ನು ಸೇರಿಸಿ ಅಥವಾ ಬದಲಿಸಿ: %@",
    "Remove day/night group: %@": "ಹಗಲು/ರಾತ್ರಿ ಗುಂಪನ್ನು ತೆಗೆಯಿರಿ: %@",
    "more powerful, more intuitive": "ಹೆಚ್ಚು ಶಕ್ತಿಶಾಲಿ, ಹೆಚ್ಚು ಸಹಜ",
    // Wake/sleep schedules, group gates, and one-time math-to-phrase replacement.
    "Wake-up for %@: %d minutes": "%@ ಗಾಗಿ ಎಚ್ಚರ: %d ನಿಮಿಷ",
    "Turn off wake-up for %@": "%@ ಗಾಗಿ ಎಚ್ಚರ ಆಫ್ ಮಾಡಿ",
    "Review a limit when you're ready; edits still follow your delays.": "ಸಿದ್ಧರಾದಾಗ ಒಂದು ಮಿತಿಯನ್ನು ಪರಿಶೀಲಿಸಿ; ಬದಲಾವಣೆಗಳು ಇನ್ನೂ ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತವೆ.",
    "Add a limit group first.": "ಮೊದಲು ಒಂದು ಮಿತಿ ಗುಂಪು ಸೇರಿಸಿ.",
    "Add replacement phrases": "ಬದಲಿ ವಾಕ್ಯಗಳನ್ನು ಸೇರಿಸಿ",
    "An excluded group still keeps its normal daily limit.": "ಹೊರಗಿಟ್ಟ ಗುಂಪು ಇನ್ನೂ ತನ್ನ ಸಾಮಾನ್ಯ ದೈನಂದಿನ ಮಿತಿಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ.",
    "Blocking schedule": "ಬ್ಲಾಕ್ ವೇಳಾಪಟ್ಟಿ",
    "Choose what each phrase can approve. This one-time offer covers pending changes, not extra time. Later additions and edits follow your delays.": "ಪ್ರತಿ ವಾಕ್ಯ ಏನನ್ನು ಒಪ್ಪಬಹುದು ಎಂದು ಆರಿಸಿ. ಈ ಒಂದು ಬಾರಿಯ ಅವಕಾಶ ಬಾಕಿ ಬದಲಾವಣೆಗಳಿಗೆ, ಹೆಚ್ಚುವರಿ ಸಮಯಕ್ಕಲ್ಲ. ನಂತರದ ಸೇರ್ಪಡೆಗಳು ಮತ್ತು ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತವೆ.",
    "Create a group in Limits & blocks first.": "ಮೊದಲು ಮಿತಿಗಳು ಮತ್ತು ಬ್ಲಾಕ್‌ಗಳಲ್ಲಿ ಒಂದು ಗುಂಪನ್ನು ರಚಿಸಿ.",
    "Day & night": "ಹಗಲು ಮತ್ತು ರಾತ್ರಿ",
    "Days": "ದಿನಗಳು",
    "Enable sleep blocking": "ನಿದ್ರೆ ಬ್ಲಾಕ್ ಸಕ್ರಿಯಗೊಳಿಸಿ",
    "Enable wake-up blocking": "ಎಚ್ಚರದ ಬ್ಲಾಕ್ ಸಕ್ರಿಯಗೊಳಿಸಿ",
    "Ends at %02d:00, when the wake-up day begins.": "%02d:00 ಕ್ಕೆ ಮುಗಿಯುತ್ತದೆ, ಎಚ್ಚರದ ದಿನ ಆರಂಭವಾಗುವಾಗ.",
    "Exclude limit groups from this boundary": "ಈ ಗಡಿಯಿಂದ ಮಿತಿ ಗುಂಪುಗಳನ್ನು ಹೊರಗಿಡಿ",
    "From math to phrases": "ಗಣಿತದಿಂದ ವಾಕ್ಯಗಳಿಗೆ",
    "General blocks": "ಸಾಮಾನ್ಯ ಬ್ಲಾಕ್‌ಗಳು",
    "General wake-up schedule": "ಸಾಮಾನ್ಯ ಎಚ್ಚರದ ವೇಳಾಪಟ್ಟಿ",
    "Get extra time": "ಹೆಚ್ಚುವರಿ ಸಮಯ ಪಡೆಯಿರಿ",
    "Give each group its own daily wake-up tap and wait. These group gates begin at midnight; the general schedule has its own start time and weekdays. If both cover an app, both waits apply.": "ಪ್ರತಿ ಗುಂಪಿಗೆ ತನ್ನದೇ ದೈನಂದಿನ ಎಚ್ಚರ ಟ್ಯಾಪ್ ಮತ್ತು ಕಾಯುವಿಕೆ ನೀಡಿ. ಈ ಗುಂಪು ಗೇಟ್‌ಗಳು ಮಧ್ಯರಾತ್ರಿಯಿಂದ ಆರಂಭವಾಗುತ್ತವೆ; ಸಾಮಾನ್ಯ ವೇಳಾಪಟ್ಟಿಗೆ ತನ್ನದೇ ಆರಂಭ ಸಮಯ ಮತ್ತು ವಾರದ ದಿನಗಳಿವೆ. ಎರಡೂ ಒಂದು ಆ್ಯಪ್ ಅನ್ನು ಒಳಗೊಂಡರೆ, ಎರಡೂ ಕಾಯುವಿಕೆಗಳು ಅನ್ವಯಿಸುತ್ತವೆ.",
    "Group wake-up": "ಗುಂಪು ಎಚ್ಚರ",
    "Group wake-up waits": "ಗುಂಪು ಎಚ್ಚರದ ಕಾಯುವಿಕೆಗಳು",
    "Hour": "ಗಂಟೆ",
    "Math problems have been replaced with phrases. Since you used math overrides, you can add replacement phrases now without waiting.": "ಗಣಿತ ಸಮಸ್ಯೆಗಳನ್ನು ವಾಕ್ಯಗಳಿಂದ ಬದಲಿಸಲಾಗಿದೆ. ನೀವು ಗಣಿತ ಒಪ್ಪಿಗೆಗಳನ್ನು ಬಳಸಿದ್ದರಿಂದ, ಈಗ ಕಾಯದೆ ಬದಲಿ ವಾಕ್ಯಗಳನ್ನು ಸೇರಿಸಬಹುದು.",
    "Minute": "ನಿಮಿಷ",
    "Next use: %d usage minutes after entering %@": "ಮುಂದಿನ ಬಳಕೆ: %2$@ ಪ್ರವೇಶಿಸಿದ ನಂತರ %1$d ಬಳಕೆಯ ನಿಮಿಷಗಳು",
    "Optional. After this welcome, adding phrases follows your delay settings.": "ಐಚ್ಛಿಕ. ಈ ಸ್ವಾಗತದ ನಂತರ ವಾಕ್ಯಗಳನ್ನು ಸೇರಿಸುವುದು ನಿಮ್ಮ ಕಾಯುವಿಕೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಅನುಸರಿಸುತ್ತದೆ.",
    "Recurring session": "ಪುನರಾವರ್ತಿತ ಸೆಷನ್",
    "Refresh": "ರಿಫ್ರೆಶ್",
    "See all": "ಎಲ್ಲವನ್ನೂ ನೋಡಿ",
    "Selected apps stay usable; other apps are blocked.": "ಆಯ್ದ ಆ್ಯಪ್‌ಗಳು ಬಳಸಬಹುದಾಗಿರುತ್ತವೆ; ಇತರ ಆ್ಯಪ್‌ಗಳು ಬ್ಲಾಕ್ ಆಗುತ್ತವೆ.",
    "Set the usage minutes and gate for each use. Extra time is available only after the full daily limit is spent, and resets at midnight.": "ಪ್ರತಿ ಬಳಕೆಗೆ ಬಳಕೆಯ ನಿಮಿಷಗಳು ಮತ್ತು ಗೇಟ್ ಹೊಂದಿಸಿ. ಹೆಚ್ಚುವರಿ ಸಮಯ ಪೂರ್ಣ ದೈನಂದಿನ ಮಿತಿ ಮುಗಿದ ನಂತರವೇ ಲಭ್ಯ, ಮತ್ತು ಮಧ್ಯರಾತ್ರಿ ರೀಸೆಟ್ ಆಗುತ್ತದೆ.",
    "Set weekday allowances. Manage wake-up and sleep in Schedules → Day & night.": "ವಾರದ ದಿನಗಳ ಮಿತಿಗಳನ್ನು ಹೊಂದಿಸಿ. ಎಚ್ಚರ ಮತ್ತು ನಿದ್ರೆಯನ್ನು ವೇಳಾಪಟ್ಟಿಗಳು → ಹಗಲು ಮತ್ತು ರಾತ್ರಿ ಯಲ್ಲಿ ನಿರ್ವಹಿಸಿ.",
    "Sleep": "ನಿದ್ರೆ",
    "Sleep begins": "ನಿದ್ರೆ ಆರಂಭ",
    "Sleep blocking ends at this time, even if the wake-up tap is off.": "ಎಚ್ಚರ ಟ್ಯಾಪ್ ಆಫ್ ಆಗಿದ್ದರೂ ನಿದ್ರೆ ಬ್ಲಾಕ್ ಈ ಸಮಯದಲ್ಲಿ ಮುಗಿಯುತ್ತದೆ.",
    "The current day's wake-up countdown stays unchanged. A new wait applies to the next tap. Turning this off still waits through your less-strict delay.": "ಇಂದಿನ ಎಚ್ಚರದ ಕೌಂಟ್‌ಡೌನ್ ಹಾಗೇ ಇರುತ್ತದೆ. ಹೊಸ ಕಾಯುವಿಕೆ ಮುಂದಿನ ಟ್ಯಾಪ್‌ಗೆ ಅನ್ವಯಿಸುತ್ತದೆ. ಇದನ್ನು ಆಫ್ ಮಾಡುವುದೂ ನಿಮ್ಮ ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯ ಮೂಲಕ ಹೋಗುತ್ತದೆ.",
    "This week": "ಈ ವಾರ",
    "Unavailable password": "ಲಭ್ಯವಿಲ್ಲದ ಪಾಸ್‌ವರ್ಡ್",
    "Usage already spent, split budgets and extra-time grants are not reset by this change.": "ಈ ಬದಲಾವಣೆಯಿಂದ ಈಗಾಗಲೇ ಬಳಸಿದ ಸಮಯ, ಹಂಚಿದ ಬಜೆಟ್‌ಗಳು ಮತ್ತು ಹೆಚ್ಚುವರಿ ಸಮಯದ ಮಂಜೂರಾತಿಗಳು ರೀಸೆಟ್ ಆಗುವುದಿಲ್ಲ.",
    "Use these phrases now": "ಈ ವಾಕ್ಯಗಳನ್ನು ಈಗ ಬಳಸಿ",
    "Wait": "ಕಾಯುವಿಕೆ",
    "Wait after tapping Wake up": "ಎಚ್ಚರ ಟ್ಯಾಪ್ ಮಾಡಿದ ನಂತರದ ಕಾಯುವಿಕೆ",
    "Wait for the pending wake/sleep change before editing another.": "ಇನ್ನೊಂದನ್ನು ಬದಲಿಸುವ ಮೊದಲು ಬಾಕಿ ಇರುವ ಎಚ್ಚರ/ನಿದ್ರೆ ಬದಲಾವಣೆಗಾಗಿ ಕಾಯಿರಿ.",
    "Wait for this group's pending change before editing its wake-up wait.": "ಈ ಗುಂಪಿನ ಎಚ್ಚರದ ಕಾಯುವಿಕೆಯನ್ನು ಬದಲಿಸುವ ಮೊದಲು ಅದರ ಬಾಕಿ ಬದಲಾವಣೆಗಾಗಿ ಕಾಯಿರಿ.",
    "Wake-up day begins": "ಎಚ್ಚರದ ದಿನ ಆರಂಭ",
    "Wake-up time must differ from when sleep begins.": "ಎಚ್ಚರದ ಸಮಯ ನಿದ್ರೆ ಆರಂಭವಾಗುವ ಸಮಯಕ್ಕಿಂತ ಬೇರೆ ಇರಬೇಕು.",
    "Wake-up wait": "ಎಚ್ಚರದ ಕಾಯುವಿಕೆ",
    "What to block": "ಏನನ್ನು ಬ್ಲಾಕ್ ಮಾಡಬೇಕು",
    "Wrong password or this extra-time use is no longer available.": "ಪಾಸ್‌ವರ್ಡ್ ತಪ್ಪು, ಅಥವಾ ಈ ಹೆಚ್ಚುವರಿ ಸಮಯದ ಬಳಕೆ ಇನ್ನು ಲಭ್ಯವಿಲ್ಲ.",
    "Your replacement phrases are ready.": "ನಿಮ್ಮ ಬದಲಿ ವಾಕ್ಯಗಳು ಸಿದ್ಧ.",
    "block only or block except": "ಬ್ಲಾಕ್ ಮಾತ್ರ ಅಥವಾ ಇವನ್ನು ಬಿಟ್ಟು ಬ್ಲಾಕ್",
    "iOS cannot exempt an entire app category from 'block except'; category-based groups cannot be excluded here.": "iOS ಇಡೀ ಆ್ಯಪ್ ವರ್ಗವನ್ನು \"ಇವನ್ನು ಬಿಟ್ಟು ಬ್ಲಾಕ್\" ನಿಂದ ಹೊರಗಿಡಲಾಗದು; ವರ್ಗ ಆಧಾರಿತ ಗುಂಪುಗಳನ್ನು ಇಲ್ಲಿ ಹೊರಗಿಡಲಾಗದು.",
    "repeat a break from limits": "ಮಿತಿಗಳಿಂದ ವಿರಾಮವನ್ನು ಪುನರಾವರ್ತಿಸಿ",
    "start time, weekdays, apps and default wait": "ಆರಂಭ ಸಮಯ, ವಾರದ ದಿನಗಳು, ಆ್ಯಪ್‌ಗಳು ಮತ್ತು ಡೀಫಾಲ್ಟ್ ಕಾಯುವಿಕೆ",
    // Demora 2.0: delay modes, setup, welcome, and safe recovery.
    "%d of %d": "%d ರಲ್ಲಿ %d",
    "A change can wait without taking away your ability to choose.": "ನಿಮ್ಮ ಆಯ್ಕೆಯ ಸ್ವಾತಂತ್ರ್ಯ ಕಳೆಯದೆ ಒಂದು ಬದಲಾವಣೆ ಕಾಯಬಹುದು.",
    "A clearer place for your intentions.": "ನಿಮ್ಮ ಉದ್ದೇಶಗಳಿಗೆ ಹೆಚ್ಚು ಸ್ಪಷ್ಟ ಸ್ಥಳ.",
    "A new layout. The same idea: your considered choices deserve time to hold.": "ಹೊಸ ವಿನ್ಯಾಸ. ಅದೇ ಆಲೋಚನೆ: ನಿಮ್ಮ ಯೋಚಿಸಿದ ಆಯ್ಕೆಗಳಿಗೆ ಉಳಿಯಲು ಸಮಯ ಸಿಗಬೇಕು.",
    "A note about older features": "ಹಳೆಯ ಸೌಲಭ್ಯಗಳ ಬಗ್ಗೆ ಒಂದು ಟಿಪ್ಪಣಿ",
    "A pause, on your terms.": "ವಿರಾಮ, ನಿಮ್ಮ ಷರತ್ತುಗಳಲ್ಲಿ.",
    "App color": "ಆ್ಯಪ್ ಬಣ್ಣ",
    "Blue": "ನೀಲಿ",
    "Carried with you": "ನಿಮ್ಮೊಂದಿಗೆ ಬರುತ್ತದೆ",
    "Change delays: %@": "ಕಾಯುವಿಕೆಗಳನ್ನು ಬದಲಿಸಿ: %@",
    "Changes still wait": "ಬದಲಾವಣೆಗಳು ಇನ್ನೂ ಕಾಯುತ್ತವೆ",
    "Changing your delay mode follows your current delays. Countdowns already running keep their original deadline.": "ನಿಮ್ಮ ಕಾಯುವಿಕೆ ಮೋಡ್ ಬದಲಿಸುವುದು ನಿಮ್ಮ ಈಗಿನ ಕಾಯುವಿಕೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತದೆ. ಈಗಾಗಲೇ ನಡೆಯುತ್ತಿರುವ ಕೌಂಟ್‌ಡೌನ್‌ಗಳು ತಮ್ಮ ಮೂಲ ಗಡುವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
    "Choose a delay of at least one minute.": "ಕನಿಷ್ಠ ಒಂದು ನಿಮಿಷದ ಕಾಯುವಿಕೆ ಆರಿಸಿ.",
    "Choose a different wait for tightening and loosening your rules.": "ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ಬಿಗಿಗೊಳಿಸಲು ಮತ್ತು ಸಡಿಲಿಸಲು ಬೇರೆಬೇರೆ ಕಾಯುವಿಕೆ ಆರಿಸಿ.",
    "Choose separate waits, one shared wait, or a wait only when loosening rules.": "ಪ್ರತ್ಯೇಕ ಕಾಯುವಿಕೆಗಳು, ಒಂದೇ ಹಂಚಿದ ಕಾಯುವಿಕೆ, ಅಥವಾ ನಿಯಮ ಸಡಿಲಿಸುವಾಗ ಮಾತ್ರ ಕಾಯುವಿಕೆ ಆರಿಸಿ.",
    "Choose what each trusted contact can approve, instead of giving everyone the same permissions.": "ಎಲ್ಲರಿಗೂ ಒಂದೇ ಅನುಮತಿ ಕೊಡುವ ಬದಲು, ಪ್ರತಿ ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ ಏನನ್ನು ಒಪ್ಪಬಹುದು ಎಂದು ಆರಿಸಿ.",
    "Choose your boundaries now. Give yourself time before changing them later.": "ನಿಮ್ಮ ಗಡಿಗಳನ್ನು ಈಗ ಆರಿಸಿ. ನಂತರ ಅವನ್ನು ಬದಲಿಸುವ ಮೊದಲು ನಿಮಗೇ ಸಮಯ ಕೊಡಿ.",
    "Daily allowance": "ದೈನಂದಿನ ಮಿತಿ",
    "Daily allowance: %d min": "ದೈನಂದಿನ ಮಿತಿ: %d ನಿಮಿ",
    "Daily boundaries in Limits. Recurring and planned time in Schedules.": "ದೈನಂದಿನ ಗಡಿಗಳು ಮಿತಿಗಳಲ್ಲಿ. ಪುನರಾವರ್ತಿತ ಮತ್ತು ಯೋಜಿತ ಸಮಯ ವೇಳಾಪಟ್ಟಿಗಳಲ್ಲಿ.",
    "Decide with a clear head": "ಸ್ಪಷ್ಟ ಮನಸ್ಸಿನಿಂದ ನಿರ್ಧರಿಸಿ",
    "Delay for every change": "ಪ್ರತಿ ಬದಲಾವಣೆಗೆ ಕಾಯುವಿಕೆ",
    "Demora 2.0": "Demora 2.0",
    "Demora could not finish reading or backing up your saved setup. Nothing has been reset. Try again, or contact hello@getdemora.app before reinstalling.": "Demora ನಿಮ್ಮ ಉಳಿಸಿದ ಸೆಟಪ್ ಅನ್ನು ಓದುವುದನ್ನು ಅಥವಾ ಬ್ಯಾಕಪ್ ಮಾಡುವುದನ್ನು ಮುಗಿಸಲಾಗಲಿಲ್ಲ. ಏನನ್ನೂ ರೀಸೆಟ್ ಮಾಡಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ, ಅಥವಾ ಮರುಸ್ಥಾಪನೆಗೆ ಮೊದಲು hello@getdemora.app ಅನ್ನು ಸಂಪರ್ಕಿಸಿ.",
    "Different days, different budgets": "ಬೇರೆಬೇರೆ ದಿನಗಳಿಗೆ ಬೇರೆಬೇರೆ ಬಜೆಟ್‌ಗಳು",
    "Edit your selection": "ನಿಮ್ಮ ಆಯ್ಕೆಯನ್ನು ಬದಲಿಸಿ",
    "Editing override permissions follows your delays. This welcome doesn't change them.": "ಒಪ್ಪಿಗೆಯ ಅನುಮತಿಗಳನ್ನು ಬದಲಿಸುವುದು ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತದೆ. ಈ ಸ್ವಾಗತ ಅವನ್ನು ಬದಲಿಸುವುದಿಲ್ಲ.",
    "Every change": "ಪ್ರತಿ ಬದಲಾವಣೆ",
    "Existing contacts keep their pending-change permissions. They don't automatically gain extra-time access.": "ಈಗಿರುವ ಸಂಪರ್ಕಗಳು ತಮ್ಮ ಬಾಕಿ-ಬದಲಾವಣೆ ಅನುಮತಿಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತಾರೆ. ಅವರಿಗೆ ಹೆಚ್ಚುವರಿ ಸಮಯದ ಪ್ರವೇಶ ತಾನಾಗಿ ಸಿಗುವುದಿಲ್ಲ.",
    "Extra time with intention": "ಉದ್ದೇಶದೊಂದಿಗೆ ಹೆಚ್ಚುವರಿ ಸಮಯ",
    "Free. No account, ads, or analytics. Your app choices and usage stay on your device.": "ಉಚಿತ. ಖಾತೆ, ಜಾಹೀರಾತು ಅಥವಾ ಅನಾಲಿಟಿಕ್ಸ್ ಇಲ್ಲ. ನಿಮ್ಮ ಆ್ಯಪ್ ಆಯ್ಕೆಗಳು ಮತ್ತು ಬಳಕೆ ನಿಮ್ಮ ಸಾಧನದಲ್ಲೇ ಇರುತ್ತವೆ.",
    "Give your day a little shape.": "ನಿಮ್ಮ ದಿನಕ್ಕೆ ಸ್ವಲ್ಪ ರೂಪ ಕೊಡಿ.",
    "How changes wait": "ಬದಲಾವಣೆಗಳು ಹೇಗೆ ಕಾಯುತ್ತವೆ",
    "Immediately": "ತಕ್ಷಣ",
    "Keep a simple daily allowance, or make a limit fit the way your day unfolds.": "ಸರಳ ದೈನಂದಿನ ಮಿತಿ ಇಡಿ, ಅಥವಾ ನಿಮ್ಮ ದಿನ ಸಾಗುವ ರೀತಿಗೆ ಮಿತಿಯನ್ನು ಹೊಂದಿಸಿ.",
    "Keep separate waits, use one shared wait, or wait only when loosening rules. Your current delay mode and durations stay unchanged.": "ಪ್ರತ್ಯೇಕ ಕಾಯುವಿಕೆಗಳು, ಒಂದೇ ಹಂಚಿದ ಕಾಯುವಿಕೆ, ಅಥವಾ ನಿಯಮ ಸಡಿಲಿಸುವಾಗ ಮಾತ್ರ ಕಾಯುವಿಕೆ ಇಡಿ. ನಿಮ್ಮ ಈಗಿನ ಕಾಯುವಿಕೆ ಮೋಡ್ ಮತ್ತು ಅವಧಿಗಳು ಹಾಗೇ ಇರುತ್ತವೆ.",
    "Language & appearance": "ಭಾಷೆ ಮತ್ತು ರೂಪ",
    "Legacy usage-burst pacing and math overrides have been removed. Daily limits remain. Split budgets and extra-time steps are optional alternatives, not automatic replacements.": "ಹಳೆಯ ಬಳಕೆ-ಗತಿ ಮತ್ತು ಗಣಿತ ಒಪ್ಪಿಗೆಗಳನ್ನು ತೆಗೆಯಲಾಗಿದೆ. ದೈನಂದಿನ ಮಿತಿಗಳು ಉಳಿಯುತ್ತವೆ. ಹಂಚಿದ ಬಜೆಟ್‌ಗಳು ಮತ್ತು ಹೆಚ್ಚುವರಿ ಸಮಯದ ಹಂತಗಳು ಐಚ್ಛಿಕ ಪರ್ಯಾಯಗಳು, ತಾನಾಗಿ ಬದಲಿಗಳಲ್ಲ.",
    "Let the impulse pass": "ಆವೇಗ ಹಾದುಹೋಗಲಿ",
    "Limit name": "ಮಿತಿಯ ಹೆಸರು",
    "Limits & schedules": "ಮಿತಿಗಳು ಮತ್ತು ವೇಳಾಪಟ್ಟಿಗಳು",
    "Make room for what matters.": "ಮುಖ್ಯವಾದುದಕ್ಕೆ ಸ್ಥಳ ಮಾಡಿ.",
    "More-strict changes apply immediately.": "ಹೆಚ್ಚು-ಕಠಿಣ ಬದಲಾವಣೆಗಳು ತಕ್ಷಣ ಜಾರಿಗೆ ಬರುತ್ತವೆ.",
    "My first limit": "ನನ್ನ ಮೊದಲ ಮಿತಿ",
    "No limit yet. Add one whenever you're ready in Limits & blocks.": "ಇನ್ನೂ ಮಿತಿ ಇಲ್ಲ. ಸಿದ್ಧರಾದಾಗ ಮಿತಿಗಳು ಮತ್ತು ಬ್ಲಾಕ್‌ಗಳಲ್ಲಿ ಸೇರಿಸಿ.",
    "No silent new permissions": "ಮೌನವಾಗಿ ಹೊಸ ಅನುಮತಿಗಳಿಲ್ಲ",
    "Nothing to configure here. Review a limit when you're ready; edits still follow your delays.": "ಇಲ್ಲಿ ಹೊಂದಿಸಲು ಏನೂ ಇಲ್ಲ. ಸಿದ್ಧರಾದಾಗ ಒಂದು ಮಿತಿಯನ್ನು ಪರಿಶೀಲಿಸಿ; ಬದಲಾವಣೆಗಳು ಇನ್ನೂ ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತವೆ.",
    "One app or a shared group": "ಒಂದು ಆ್ಯಪ್ ಅಥವಾ ಹಂಚಿದ ಗುಂಪು",
    "One budget, three portions": "ಒಂದು ಬಜೆಟ್, ಮೂರು ಭಾಗಗಳು",
    "One delay for all changes": "ಎಲ್ಲ ಬದಲಾವಣೆಗಳಿಗೆ ಒಂದೇ ಕಾಯುವಿಕೆ",
    "One wait for all changes: %@": "ಎಲ್ಲ ಬದಲಾವಣೆಗಳಿಗೆ ಒಂದೇ ಕಾಯುವಿಕೆ: %@",
    "Only less-strict changes wait": "ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆಗಳು ಮಾತ್ರ ಕಾಯುತ್ತವೆ",
    "Open my limits": "ನನ್ನ ಮಿತಿಗಳನ್ನು ತೆರೆಯಿರಿ",
    "Optional: choose an app or a group and a daily allowance. This will be a real limit, not a demo.": "ಐಚ್ಛಿಕ: ಒಂದು ಆ್ಯಪ್ ಅಥವಾ ಗುಂಪು ಮತ್ತು ದೈನಂದಿನ ಮಿತಿ ಆರಿಸಿ. ಇದು ನಿಜವಾದ ಮಿತಿ ಆಗಿರುತ್ತದೆ, ಡೆಮೊ ಅಲ್ಲ.",
    "Permission by person": "ವ್ಯಕ್ತಿಯ ಪ್ರಕಾರ ಅನುಮತಿ",
    "Plan ordered extra-time steps, each with its own wait or approval method.": "ಕ್ರಮಬದ್ಧ ಹೆಚ್ಚುವರಿ ಸಮಯದ ಹಂತಗಳನ್ನು ಯೋಜಿಸಿ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ತನ್ನದೇ ಕಾಯುವಿಕೆ ಅಥವಾ ಒಪ್ಪಿಗೆ ವಿಧಾನ.",
    "Planned windows": "ಯೋಜಿತ ಅವಧಿಗಳು",
    "Red": "ಕೆಂಪು",
    "Scope approvals to the pending changes you choose. Extra-time approval is a separate opt-in.": "ನೀವು ಆರಿಸುವ ಬಾಕಿ ಬದಲಾವಣೆಗಳಿಗೆ ಮಾತ್ರ ಒಪ್ಪಿಗೆಗಳನ್ನು ಸೀಮಿತಗೊಳಿಸಿ. ಹೆಚ್ಚುವರಿ ಸಮಯದ ಒಪ್ಪಿಗೆ ಪ್ರತ್ಯೇಕ ಐಚ್ಛಿಕ ಆಯ್ಕೆ.",
    "See what's active, what's next, and which changes are waiting.": "ಏನು ಸಕ್ರಿಯ, ಮುಂದೆ ಏನು, ಯಾವ ಬದಲಾವಣೆಗಳು ಕಾಯುತ್ತಿವೆ ಎಂದು ನೋಡಿ.",
    "Set a limit later": "ಮಿತಿಯನ್ನು ನಂತರ ಹೊಂದಿಸಿ",
    "Set limits for an app or a group, and plan time away.": "ಆ್ಯಪ್ ಅಥವಾ ಗುಂಪಿಗೆ ಮಿತಿಗಳನ್ನು ಹೊಂದಿಸಿ, ಮತ್ತು ದೂರದ ಸಮಯವನ್ನು ಯೋಜಿಸಿ.",
    "Set weekday allowances and an optional wake-up wait.": "ವಾರದ ದಿನಗಳ ಮಿತಿಗಳು ಮತ್ತು ಐಚ್ಛಿಕ ಎಚ್ಚರದ ಕಾಯುವಿಕೆ ಹೊಂದಿಸಿ.",
    "Setup couldn't be saved": "ಸೆಟಪ್ ಉಳಿಸಲಾಗಲಿಲ್ಲ",
    "Split an allowance across your day, with optional carryover.": "ಮಿತಿಯನ್ನು ನಿಮ್ಮ ದಿನದಾದ್ಯಂತ ಹಂಚಿ, ಐಚ್ಛಿಕ ಮುಂದೊಯ್ಯುವಿಕೆಯೊಂದಿಗೆ.",
    "Start with one boundary.": "ಒಂದು ಗಡಿಯಿಂದ ಆರಂಭಿಸಿ.",
    "Step %d of %d": "ಹಂತ %d / %d",
    "The same wait applies whether you tighten or loosen a rule.": "ನೀವು ನಿಯಮವನ್ನು ಬಿಗಿಗೊಳಿಸಿದರೂ ಸಡಿಲಿಸಿದರೂ ಅದೇ ಕಾಯುವಿಕೆ ಅನ್ವಯಿಸುತ್ತದೆ.",
    "The selected apps share this allowance. You can fine-tune it later in Limits & blocks.": "ಆಯ್ದ ಆ್ಯಪ್‌ಗಳು ಈ ಮಿತಿಯನ್ನು ಹಂಚಿಕೊಳ್ಳುತ್ತವೆ. ನಂತರ ಮಿತಿಗಳು ಮತ್ತು ಬ್ಲಾಕ್‌ಗಳಲ್ಲಿ ಇದನ್ನು ಸರಿಹೊಂದಿಸಬಹುದು.",
    "These are your starting settings. Later changes to rules and delay settings follow your delay policy.": "ಇವು ನಿಮ್ಮ ಆರಂಭಿಕ ಸೆಟ್ಟಿಂಗ್‌ಗಳು. ನಿಯಮಗಳು ಮತ್ತು ಕಾಯುವಿಕೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ನಂತರದ ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ಕಾಯುವಿಕೆ ನೀತಿಯನ್ನು ಅನುಸರಿಸುತ್ತವೆ.",
    "This limit will be saved when you start. Your initial setup doesn't need to wait.": "ನೀವು ಆರಂಭಿಸಿದಾಗ ಈ ಮಿತಿ ಉಳಿಯುತ್ತದೆ. ನಿಮ್ಮ ಆರಂಭಿಕ ಸೆಟಪ್ ಕಾಯಬೇಕಿಲ್ಲ.",
    "Three ways to wait": "ಕಾಯಲು ಮೂರು ಮಾರ್ಗಗಳು",
    "Tighten a rule immediately. Loosening it still waits.": "ನಿಯಮವನ್ನು ತಕ್ಷಣ ಬಿಗಿಗೊಳಿಸಿ. ಸಡಿಲಿಸುವುದು ಇನ್ನೂ ಕಾಯುತ್ತದೆ.",
    "Tightening is immediate · Loosening: %@": "ಬಿಗಿಗೊಳಿಸುವುದು ತಕ್ಷಣ · ಸಡಿಲಿಸುವುದು: %@",
    "Tightening: %@ · Loosening: %@": "ಬಿಗಿಗೊಳಿಸುವುದು: %@ · ಸಡಿಲಿಸುವುದು: %@",
    "Trust, with clear boundaries.": "ಸ್ಪಷ್ಟ ಗಡಿಗಳೊಂದಿಗೆ ನಂಬಿಕೆ.",
    "Try again": "ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ",
    "Two delays": "ಎರಡು ಕಾಯುವಿಕೆಗಳು",
    "Want a practice run? The optional walkthrough and extra safeguards are in Settings → Help.": "ಅಭ್ಯಾಸ ಬೇಕೇ? ಐಚ್ಛಿಕ ವಾಕ್‌ಥ್ರೂ ಮತ್ತು ಹೆಚ್ಚುವರಿ ಸುರಕ್ಷತೆಗಳು ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಸಹಾಯದಲ್ಲಿವೆ.",
    "Welcome back": "ಮರಳಿ ಸ್ವಾಗತ",
    "You can add a limit after enabling Screen Time access. For now, continue without one.": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪ್ರವೇಶ ಸಕ್ರಿಯಗೊಳಿಸಿದ ನಂತರ ಮಿತಿ ಸೇರಿಸಬಹುದು. ಈಗ ಅದಿಲ್ಲದೆ ಮುಂದುವರಿಯಿರಿ.",
    "You're ready. Your rules are still yours.": "ನೀವು ಸಿದ್ಧ. ನಿಮ್ಮ ನಿಯಮಗಳು ಇನ್ನೂ ನಿಮ್ಮವೇ.",
    "Your choices are still here. Please try again.": "ನಿಮ್ಮ ಆಯ್ಕೆಗಳು ಇಲ್ಲೇ ಇವೆ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Your delay policy": "ನಿಮ್ಮ ಕಾಯುವಿಕೆ ನೀತಿ",
    "Your next chapter.": "ನಿಮ್ಮ ಮುಂದಿನ ಅಧ್ಯಾಯ.",
    "Your saved rules and pending changes are retained. Your existing delay settings are unchanged.": "ನಿಮ್ಮ ಉಳಿಸಿದ ನಿಯಮಗಳು ಮತ್ತು ಬಾಕಿ ಬದಲಾವಣೆಗಳು ಉಳಿಯುತ್ತವೆ. ನಿಮ್ಮ ಈಗಿನ ಕಾಯುವಿಕೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಬದಲಾಗುವುದಿಲ್ಲ.",
    "Your setup is safe": "ನಿಮ್ಮ ಸೆಟಪ್ ಸುರಕ್ಷಿತ",
    "Your waits and trusted contacts now have their own place.": "ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳು ಮತ್ತು ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕಗಳಿಗೆ ಈಗ ತಮ್ಮದೇ ಸ್ಥಳ ಇದೆ.",
    // End Demora 2.0 copy.
    // Per-contact approval permissions and schedule app editing.
    "All pending changes": "ಎಲ್ಲ ಬಾಕಿ ಬದಲಾವಣೆಗಳು",
    "None": "ಯಾವುದೂ ಇಲ್ಲ",
    "Edit": "ಬದಲಿಸಿ",
    "This contact must confirm before they can approve.": "ಈ ಸಂಪರ್ಕ ಒಪ್ಪುವ ಮೊದಲು ದೃಢೀಕರಿಸಬೇಕು.",
    "Queued": "ಸರದಿಯಲ್ಲಿದೆ",
    "Changing apps, categories, or websites always uses the less-strict delay. The current schedule stays in effect until the change applies.": "ಆ್ಯಪ್‌ಗಳು, ವರ್ಗಗಳು ಅಥವಾ ವೆಬ್‌ಸೈಟ್‌ಗಳನ್ನು ಬದಲಿಸುವುದು ಯಾವಾಗಲೂ ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯನ್ನು ಬಳಸುತ್ತದೆ. ಬದಲಾವಣೆ ಜಾರಿಗೆ ಬರುವವರೆಗೆ ಈಗಿನ ವೇಳಾಪಟ್ಟಿ ಹಾಗೇ ಇರುತ್ತದೆ.",
    "Limit changes": "ಮಿತಿ ಬದಲಾವಣೆಗಳು",
    "Schedule changes": "ವೇಳಾಪಟ್ಟಿ ಬದಲಾವಣೆಗಳು",
    "Session changes": "ಸೆಷನ್ ಬದಲಾವಣೆಗಳು",
    "Delay changes": "ಕಾಯುವಿಕೆ ಬದಲಾವಣೆಗಳು",
    "Protection changes": "ರಕ್ಷಣೆ ಬದಲಾವಣೆಗಳು",
    "Contact changes": "ಸಂಪರ್ಕ ಬದಲಾವಣೆಗಳು",
    "Waiting for a trusted contact": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕಕ್ಕಾಗಿ ಕಾಯುತ್ತಿದೆ",
    "Trusted-contact approvals are turned off.": "ನಂಬಿಕಸ್ಥ-ಸಂಪರ್ಕ ಒಪ್ಪಿಗೆಗಳು ಆಫ್ ಆಗಿವೆ.",
    "Next use: %d usage minutes after contact approval": "ಮುಂದಿನ ಬಳಕೆ: ಸಂಪರ್ಕದ ಒಪ್ಪಿಗೆಯ ನಂತರ %d ಬಳಕೆಯ ನಿಮಿಷಗಳು",
    "Extra time for %@: %d usage minutes": "%@ ಗಾಗಿ ಹೆಚ್ಚುವರಿ ಸಮಯ: %d ಬಳಕೆಯ ನಿಮಿಷಗಳು",
    "Cancel and start again": "ರದ್ದುಮಾಡಿ ಮತ್ತೆ ಆರಂಭಿಸಿ",
    "Cancel this request, then reopen extra time to choose contacts again.": "ಈ ವಿನಂತಿಯನ್ನು ರದ್ದುಮಾಡಿ, ನಂತರ ಸಂಪರ್ಕಗಳನ್ನು ಮತ್ತೆ ಆರಿಸಲು ಹೆಚ್ಚುವರಿ ಸಮಯವನ್ನು ಮರುತೆರೆಯಿರಿ.",
    "This contact approval could not grant extra time. Cancel and try again.": "ಈ ಸಂಪರ್ಕದ ಒಪ್ಪಿಗೆ ಹೆಚ್ಚುವರಿ ಸಮಯ ನೀಡಲಾಗಲಿಲ್ಲ. ರದ್ದುಮಾಡಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Phrases": "ವಾಕ್ಯಗಳು",
    "Phrase type": "ವಾಕ್ಯದ ಪ್ರಕಾರ",
    "Random words": "ಯಾದೃಚ್ಛಿಕ ಪದಗಳು",
    "Custom phrase": "ಕಸ್ಟಮ್ ವಾಕ್ಯ",
    "Words": "ಪದಗಳು",
    "%d words": "%d ಪದಗಳು",
    "Wrong words before reset": "ರೀಸೆಟ್‌ಗೆ ಮೊದಲು ತಪ್ಪು ಪದಗಳು",
    "Unlimited": "ಮಿತಿಯಿಲ್ಲ",
    "Add phrase": "ವಾಕ್ಯ ಸೇರಿಸಿ",
    "Edit phrase": "ವಾಕ್ಯ ಬದಲಿಸಿ",
    "Remove phrase": "ವಾಕ್ಯ ತೆಗೆಯಿರಿ",
    "Add or change phrase: %@": "ವಾಕ್ಯವನ್ನು ಸೇರಿಸಿ ಅಥವಾ ಬದಲಿಸಿ: %@",
    "Remove phrase: %@": "ವಾಕ್ಯವನ್ನು ತೆಗೆಯಿರಿ: %@",
    "phrase": "ವಾಕ್ಯ",
    "The exact custom phrase is saved on this device. Choose something you would not type impulsively.": "ನಿಖರವಾದ ಕಸ್ಟಮ್ ವಾಕ್ಯ ಈ ಸಾಧನದಲ್ಲಿ ಉಳಿಯುತ್ತದೆ. ಆವೇಗದಲ್ಲಿ ಟೈಪ್ ಮಾಡದಂಥದನ್ನು ಆರಿಸಿ.",
    "Word %d of %d": "ಪದ %d / %d",
    "Mistakes: %d": "ತಪ್ಪುಗಳು: %d",
    "Type the highlighted word": "ಹೈಲೈಟ್ ಮಾಡಿದ ಪದವನ್ನು ಟೈಪ್ ಮಾಡಿ",
    "Check word": "ಪದ ಪರಿಶೀಲಿಸಿ",
    "That word was incorrect. Try again.": "ಆ ಪದ ತಪ್ಪಾಗಿತ್ತು. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Too many mistakes. Start again.": "ತುಂಬಾ ತಪ್ಪುಗಳು. ಮತ್ತೆ ಆರಂಭಿಸಿ.",
    "Phrase unavailable. Close this screen and try again.": "ವಾಕ್ಯ ಲಭ್ಯವಿಲ್ಲ. ಈ ಪರದೆಯನ್ನು ಮುಚ್ಚಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "This change is no longer available. Please try again.": "ಈ ಬದಲಾವಣೆ ಇನ್ನು ಲಭ್ಯವಿಲ್ಲ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Type every word to receive this use of extra time.": "ಈ ಹೆಚ್ಚುವರಿ ಸಮಯದ ಬಳಕೆ ಪಡೆಯಲು ಪ್ರತಿ ಪದವನ್ನು ಟೈಪ್ ಮಾಡಿ.",
    "This extra-time use is no longer available.": "ಈ ಹೆಚ್ಚುವರಿ ಸಮಯದ ಬಳಕೆ ಇನ್ನು ಲಭ್ಯವಿಲ್ಲ.",
    "Unavailable phrase": "ಲಭ್ಯವಿಲ್ಲದ ವಾಕ್ಯ",
    "Next use: %d usage minutes after typing %@": "ಮುಂದಿನ ಬಳಕೆ: %2$@ ಟೈಪ್ ಮಾಡಿದ ನಂತರ %1$d ಬಳಕೆಯ ನಿಮಿಷಗಳು",
    "Approval permissions": "ಒಪ್ಪಿಗೆಯ ಅನುಮತಿಗಳು",
    "Change trusted-contact permissions: %@": "ನಂಬಿಕಸ್ಥ-ಸಂಪರ್ಕ ಅನುಮತಿಗಳನ್ನು ಬದಲಿಸಿ: %@",
    "This contact can no longer approve these changes. Send a new request.": "ಈ ಸಂಪರ್ಕ ಇನ್ನು ಈ ಬದಲಾವಣೆಗಳನ್ನು ಒಪ್ಪಲಾಗದು. ಹೊಸ ವಿನಂತಿ ಕಳುಹಿಸಿ.",
    "Today's limits": "ಇಂದಿನ ಮಿತಿಗಳು",
    "View usage": "ಬಳಕೆ ನೋಡಿ",
    "Active sessions": "ಸಕ್ರಿಯ ಸೆಷನ್‌ಗಳು",
    "Limits & blocks": "ಮಿತಿಗಳು ಮತ್ತು ಬ್ಲಾಕ್‌ಗಳು",
    "Your limits": "ನಿಮ್ಮ ಮಿತಿಗಳು",
    "More blocking tools": "ಇನ್ನಷ್ಟು ಬ್ಲಾಕ್ ಸಾಧನಗಳು",
    "App & website blocking": "ಆ್ಯಪ್ ಮತ್ತು ವೆಬ್‌ಸೈಟ್ ಬ್ಲಾಕ್",
    "deletion, adult sites, custom domains": "ಅಳಿಸುವಿಕೆ, ವಯಸ್ಕ ಸೈಟ್‌ಗಳು, ಕಸ್ಟಮ್ ಡೊಮೇನ್‌ಗಳು",
    "Delays & overrides": "ಕಾಯುವಿಕೆಗಳು ಮತ್ತು ಒಪ್ಪಿಗೆಗಳು",
    "Your rules can change—just not in the moment.": "ನಿಮ್ಮ ನಿಯಮಗಳು ಬದಲಾಗಬಹುದು — ಆ ಕ್ಷಣದಲ್ಲಿ ಅಲ್ಲ.",
    "Only someone you trust can approve skipping a pending change's wait.": "ನಂಬಿಕೆಯ ವ್ಯಕ್ತಿ ಮಾತ್ರ ಬಾಕಿ ಬದಲಾವಣೆಯ ಕಾಯುವಿಕೆ ಬಿಟ್ಟುಬಿಡಲು ಒಪ್ಪಬಹುದು.",
    "Three time portions": "ಮೂರು ಸಮಯ ಭಾಗಗಳು",
    "First cutoff": "ಮೊದಲ ಕಟ್‌ಆಫ್",
    "Second cutoff": "ಎರಡನೇ ಕಟ್‌ಆಫ್",
    "First portion: %d minutes": "ಮೊದಲ ಭಾಗ: %d ನಿಮಿಷ",
    "Middle portion: %d minutes": "ಮಧ್ಯ ಭಾಗ: %d ನಿಮಿಷ",
    "Final portion: %d minutes": "ಕೊನೆಯ ಭಾಗ: %d ನಿಮಿಷ",
    "Divide today's usage into time-of-day portions. Unused minutes can carry into later portions if you choose.": "ಇಂದಿನ ಬಳಕೆಯನ್ನು ದಿನದ ಸಮಯದ ಭಾಗಗಳಾಗಿ ಹಂಚಿ. ನೀವು ಬಯಸಿದರೆ ಬಳಸದ ನಿಮಿಷಗಳು ನಂತರದ ಭಾಗಗಳಿಗೆ ಹೋಗಬಹುದು.",
    "Manual extra time": "ಕೈಯಾರೆ ಹೆಚ್ಚುವರಿ ಸಮಯ",
    "A limit is a daily usage budget for selected apps or categories. When it runs out, those apps are blocked until midnight.": "ಮಿತಿ ಎಂದರೆ ಆಯ್ದ ಆ್ಯಪ್‌ಗಳು ಅಥವಾ ವರ್ಗಗಳ ದೈನಂದಿನ ಬಳಕೆಯ ಬಜೆಟ್. ಅದು ಮುಗಿದಾಗ, ಮಧ್ಯರಾತ್ರಿಯವರೆಗೆ ಆ ಆ್ಯಪ್‌ಗಳು ಬ್ಲಾಕ್ ಆಗುತ್ತವೆ.",
    "Home shows today's Screen Time usage. Limits & Blocks lists your configured limits; tap one to see its apps and categories. Usage from before you created a limit still counts that day. Raising or removing a limit is less strict; adding one or lowering its minutes is stricter.": "ಮುಖಪುಟ ಇಂದಿನ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಬಳಕೆಯನ್ನು ತೋರಿಸುತ್ತದೆ. ಮಿತಿಗಳು ಮತ್ತು ಬ್ಲಾಕ್‌ಗಳು ನಿಮ್ಮ ಮಿತಿಗಳ ಪಟ್ಟಿ; ಒಂದನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ ಅದರ ಆ್ಯಪ್‌ಗಳು ಮತ್ತು ವರ್ಗಗಳನ್ನು ನೋಡಿ. ಮಿತಿ ರಚಿಸುವ ಮೊದಲಿನ ಬಳಕೆಯೂ ಆ ದಿನ ಎಣಿಕೆಯಾಗುತ್ತದೆ. ಮಿತಿ ಹೆಚ್ಚಿಸುವುದು ಅಥವಾ ತೆಗೆಯುವುದು ಕಡಿಮೆ-ಕಠಿಣ; ಒಂದನ್ನು ಸೇರಿಸುವುದು ಅಥವಾ ನಿಮಿಷ ಕಡಿಮೆ ಮಾಡುವುದು ಹೆಚ್ಚು ಕಠಿಣ.",
    "Use %d": "%d ಬಳಸಿ",
    "Extra usage: %d minutes": "ಹೆಚ್ಚುವರಿ ಬಳಕೆ: %d ನಿಮಿಷ",
    "Wait: %d minutes": "ಕಾಯುವಿಕೆ: %d ನಿಮಿಷ",
    "Add another use": "ಇನ್ನೊಂದು ಬಳಕೆ ಸೇರಿಸಿ",
    "Set the usage minutes and wait for each use. Extra time is available only after the full daily limit is spent, and resets at midnight.": "ಪ್ರತಿ ಬಳಕೆಗೆ ಬಳಕೆಯ ನಿಮಿಷಗಳು ಮತ್ತು ಕಾಯುವಿಕೆ ಹೊಂದಿಸಿ. ಹೆಚ್ಚುವರಿ ಸಮಯ ಪೂರ್ಣ ದೈನಂದಿನ ಮಿತಿ ಮುಗಿದ ನಂತರವೇ ಲಭ್ಯ, ಮತ್ತು ಮಧ್ಯರಾತ್ರಿ ರೀಸೆಟ್ ಆಗುತ್ತದೆ.",
    "Next use: %d usage minutes after a %d-minute wait": "ಮುಂದಿನ ಬಳಕೆ: %d ನಿಮಿಷ ಕಾಯುವಿಕೆಯ ನಂತರ %d ಬಳಕೆಯ ನಿಮಿಷಗಳು",
    "Extra usage per request: %d minutes": "ಪ್ರತಿ ವಿನಂತಿಗೆ ಹೆಚ್ಚುವರಿ ಬಳಕೆ: %d ನಿಮಿಷ",
    "Requests per day: %d": "ದಿನಕ್ಕೆ ವಿನಂತಿಗಳು: %d",
    "Wait after request: %d minutes": "ವಿನಂತಿಯ ನಂತರದ ಕಾಯುವಿಕೆ: %d ನಿಮಿಷ",
    "After the full daily limit is spent, request more actual usage minutes. The apps remain blocked until the wait ends. The daily request count resets at midnight.": "ಪೂರ್ಣ ದೈನಂದಿನ ಮಿತಿ ಮುಗಿದ ನಂತರ, ಇನ್ನಷ್ಟು ನಿಜವಾದ ಬಳಕೆಯ ನಿಮಿಷಗಳನ್ನು ಕೇಳಿ. ಕಾಯುವಿಕೆ ಮುಗಿಯುವವರೆಗೆ ಆ್ಯಪ್‌ಗಳು ಬ್ಲಾಕ್ ಆಗಿರುತ್ತವೆ. ದೈನಂದಿನ ವಿನಂತಿ ಎಣಿಕೆ ಮಧ್ಯರಾತ್ರಿ ರೀಸೆಟ್ ಆಗುತ್ತದೆ.",
    "iOS Screen Time callbacks can arrive late. Wake-up, split, and extra-time boundaries may not switch at the exact minute.": "iOS ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಕಾಲ್‌ಬ್ಯಾಕ್‌ಗಳು ತಡವಾಗಿ ಬರಬಹುದು. ಎಚ್ಚರ, ಹಂಚಿಕೆ ಮತ್ತು ಹೆಚ್ಚುವರಿ ಸಮಯದ ಗಡಿಗಳು ನಿಖರ ನಿಮಿಷದಲ್ಲಿ ಬದಲಾಗದಿರಬಹುದು.",
    "Extra-time requests left today: %d": "ಇಂದು ಉಳಿದ ಹೆಚ್ಚುವರಿ ಸಮಯದ ವಿನಂತಿಗಳು: %d",
    "Request extra time (%d left)": "ಹೆಚ್ಚುವರಿ ಸಮಯ ಕೇಳಿ (%d ಉಳಿದಿವೆ)",
    "Extra time available in": "ಹೆಚ್ಚುವರಿ ಸಮಯ ಲಭ್ಯವಾಗುವುದು",
    "(%d requests left)": "(%d ವಿನಂತಿಗಳು ಉಳಿದಿವೆ)",
    "Extra usage active · %d requests left": "ಹೆಚ್ಚುವರಿ ಬಳಕೆ ಸಕ್ರಿಯ · %d ವಿನಂತಿಗಳು ಉಳಿದಿವೆ",
    "No extra-time requests left today": "ಇಂದು ಹೆಚ್ಚುವರಿ ಸಮಯದ ವಿನಂತಿಗಳು ಉಳಿದಿಲ್ಲ",
    "Extra time": "ಹೆಚ್ಚುವರಿ ಸಮಯ",
    "Extra time could not be started safely. Your limit is still in place; try again later.": "ಹೆಚ್ಚುವರಿ ಸಮಯವನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಆರಂಭಿಸಲಾಗಲಿಲ್ಲ. ನಿಮ್ಮ ಮಿತಿ ಇನ್ನೂ ಜಾರಿಯಲ್ಲಿದೆ; ನಂತರ ಪ್ರಯತ್ನಿಸಿ.",
    "Split-budget blocks cannot be manually rechecked. They remain until their scheduled boundary.": "ಹಂಚಿದ-ಬಜೆಟ್ ಬ್ಲಾಕ್‌ಗಳನ್ನು ಕೈಯಾರೆ ಮರುಪರಿಶೀಲಿಸಲಾಗದು. ಅವು ತಮ್ಮ ನಿಗದಿತ ಗಡಿಯವರೆಗೆ ಉಳಿಯುತ್ತವೆ.",
    "Change limit: %@": "ಮಿತಿ ಬದಲಿಸಿ: %@",
    "Unlock immediately after tap": "ಟ್ಯಾಪ್ ನಂತರ ತಕ್ಷಣ ತೆರೆಯಿರಿ",
    "Wake up": "ಎಚ್ಚರ",
    "Available after %@": "%@ ನಂತರ ಲಭ್ಯ",
    "Awake for today": "ಇಂದಿಗೆ ಎಚ್ಚರವಾಗಿದೆ",
    "Different limits by weekday": "ವಾರದ ದಿನಕ್ಕೆ ಬೇರೆಬೇರೆ ಮಿತಿಗಳು",
    "Each weekday's budget replaces the daily limit for that day.": "ಪ್ರತಿ ವಾರದ ದಿನದ ಬಜೆಟ್ ಆ ದಿನದ ದೈನಂದಿನ ಮಿತಿಯನ್ನು ಬದಲಿಸುತ್ತದೆ.",
    "Require wake-up tap": "ಎಚ್ಚರ ಟ್ಯಾಪ್ ಅಗತ್ಯ",
    "Wait %d minutes after tap": "ಟ್ಯಾಪ್ ನಂತರ %d ನಿಮಿಷ ಕಾಯಿರಿ",
    "After your first tap each day, wait before this limit becomes available.": "ಪ್ರತಿ ದಿನದ ಮೊದಲ ಟ್ಯಾಪ್ ನಂತರ, ಈ ಮಿತಿ ಲಭ್ಯವಾಗುವ ಮೊದಲು ಕಾಯಿರಿ.",
    "Split daily budget": "ದೈನಂದಿನ ಬಜೆಟ್ ಹಂಚಿ",
    "Cutoff time": "ಕಟ್‌ಆಫ್ ಸಮಯ",
    "%d minutes before cutoff": "ಕಟ್‌ಆಫ್‌ಗೆ %d ನಿಮಿಷ ಮೊದಲು",
    "Carry unused early minutes forward": "ಬಳಸದ ಆರಂಭಿಕ ನಿಮಿಷಗಳನ್ನು ಮುಂದೆ ಒಯ್ಯಿರಿ",
    "Reserve part of today's budget before the cutoff. The rest is available afterward.": "ಕಟ್‌ಆಫ್‌ಗೆ ಮೊದಲು ಇಂದಿನ ಬಜೆಟ್‌ನ ಒಂದು ಭಾಗವನ್ನು ಕಾಯ್ದಿರಿಸಿ. ಉಳಿದದ್ದು ಅದರ ನಂತರ ಲಭ್ಯ.",
    "Usage bursts and breaks": "ಬಳಕೆಯ ಸ್ಫೋಟಗಳು ಮತ್ತು ವಿರಾಮಗಳು",
    "Burst quota: %d minutes": "ಸ್ಫೋಟದ ಕೋಟಾ: %d ನಿಮಿಷ",
    "Fresh allowance interval: %d minutes": "ಹೊಸ ಮಿತಿಯ ಅಂತರ: %d ನಿಮಿಷ",
    "Cooldown / break: %d minutes": "ತಣಿಯುವಿಕೆ / ವಿರಾಮ: %d ನಿಮಿಷ",
    "Practical approximation, not an exact rolling window: a usage burst, a minimum interval before a fresh allowance, then a break. iOS may deliver usage callbacks late.": "ಪ್ರಾಯೋಗಿಕ ಅಂದಾಜು, ನಿಖರ ಚಲಿಸುವ ಕಿಟಕಿ ಅಲ್ಲ: ಒಂದು ಬಳಕೆಯ ಸ್ಫೋಟ, ಹೊಸ ಮಿತಿಗೆ ಮೊದಲು ಕನಿಷ್ಠ ಅಂತರ, ನಂತರ ವಿರಾಮ. iOS ಬಳಕೆಯ ಕಾಲ್‌ಬ್ಯಾಕ್‌ಗಳನ್ನು ತಡವಾಗಿ ನೀಡಬಹುದು.",
    "iOS Screen Time callbacks can arrive late. Wake-up, split, and pacing boundaries may not switch at the exact minute.": "iOS ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಕಾಲ್‌ಬ್ಯಾಕ್‌ಗಳು ತಡವಾಗಿ ಬರಬಹುದು. ಎಚ್ಚರ, ಹಂಚಿಕೆ ಮತ್ತು ಗತಿಯ ಗಡಿಗಳು ನಿಖರ ನಿಮಿಷದಲ್ಲಿ ಬದಲಾಗದಿರಬಹುದು.",
    "Edit apps": "ಆ್ಯಪ್‌ಗಳನ್ನು ಬದಲಿಸಿ",
    "Change apps in %@": "%@ ನಲ್ಲಿ ಆ್ಯಪ್‌ಗಳನ್ನು ಬದಲಿಸಿ",
    "Change apps and daily limit for %@ to %d min/day": "%@ ಗಾಗಿ ಆ್ಯಪ್‌ಗಳು ಮತ್ತು ದೈನಂದಿನ ಮಿತಿಯನ್ನು ದಿನಕ್ಕೆ %d ನಿಮಿಷಕ್ಕೆ ಬದಲಿಸಿ",
    "Change limit": "ಮಿತಿ ಬದಲಿಸಿ",
    "Notifications": "ಅಧಿಸೂಚನೆಗಳು",
    "5 minutes left for a limit": "ಮಿತಿಗೆ 5 ನಿಮಿಷ ಉಳಿದಿದೆ",
    "Only for limits longer than 5 minutes. No alert is sent during a free period.": "5 ನಿಮಿಷಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಮಿತಿಗಳಿಗೆ ಮಾತ್ರ. ಮುಕ್ತ ಅವಧಿಯಲ್ಲಿ ಎಚ್ಚರಿಕೆ ಕಳುಹಿಸುವುದಿಲ್ಲ.",
    "Free period starts or ends in 5 minutes": "ಮುಕ್ತ ಅವಧಿ 5 ನಿಮಿಷದಲ್ಲಿ ಆರಂಭ ಅಥವಾ ಅಂತ್ಯ",
    "Optional reminders for scheduled free periods and free-session endings.": "ನಿಗದಿತ ಮುಕ್ತ ಅವಧಿಗಳು ಮತ್ತು ಮುಕ್ತ ಸೆಷನ್ ಅಂತ್ಯಗಳ ಐಚ್ಛಿಕ ಜ್ಞಾಪನೆಗಳು.",
    "5 minutes left": "5 ನಿಮಿಷ ಉಳಿದಿದೆ",
    "About 5 minutes remain for %@ today.": "ಇಂದು %@ ಗೆ ಸುಮಾರು 5 ನಿಮಿಷ ಉಳಿದಿದೆ.",
    "Free period starts in 5 minutes": "ಮುಕ್ತ ಅವಧಿ 5 ನಿಮಿಷದಲ್ಲಿ ಆರಂಭ",
    "Free period ends in 5 minutes": "ಮುಕ್ತ ಅವಧಿ 5 ನಿಮಿಷದಲ್ಲಿ ಮುಗಿಯುತ್ತದೆ",
    "Now": "ಈಗ",
    "Next": "ಮುಂದೆ",
    "No timed rule active": "ಸಮಯದ ನಿಯಮ ಸಕ್ರಿಯವಿಲ್ಲ",
    "Nothing coming up": "ಮುಂದೆ ಏನೂ ಇಲ್ಲ",
    "Limit reached": "ಮಿತಿ ತಲುಪಿದೆ",
    "Demora now speaks more languages": "Demora ಈಗ ಇನ್ನಷ್ಟು ಭಾಷೆಗಳಲ್ಲಿ",
    "We've added support for German, French, Portuguese, Polish, Turkish, and Hindi.": "ಜರ್ಮನ್, ಫ್ರೆಂಚ್, ಪೋರ್ಚುಗೀಸ್, ಪೋಲಿಷ್, ಟರ್ಕಿಶ್ ಮತ್ತು ಹಿಂದಿ ಬೆಂಬಲ ಸೇರಿಸಿದ್ದೇವೆ.",
    "Apply language": "ಭಾಷೆ ಅನ್ವಯಿಸಿ",
    "Translation in beta": "ಬೀಟಾ ಅನುವಾದ",
    "This language is in beta. Please report any mistranslations or unclear phrasing to hello@getdemora.app.": "ಈ ಭಾಷೆ ಬೀಟಾದಲ್ಲಿದೆ. ತಪ್ಪು ಅನುವಾದ ಅಥವಾ ಅಸ್ಪಷ್ಟ ಪದಪ್ರಯೋಗಗಳನ್ನು hello@getdemora.app ಗೆ ತಿಳಿಸಿ.",
    "Dismiss": "ಮುಚ್ಚಿ",
    "Recheck blocked limits": "ಬ್ಲಾಕ್ ಆದ ಮಿತಿಗಳನ್ನು ಮರುಪರಿಶೀಲಿಸಿ",
    "Takes around 30 seconds": "ಸುಮಾರು 30 ಸೆಕೆಂಡ್ ಬೇಕು",
    "Recheck keeps current blocks in place while iOS verifies today's usage. Limits iOS confirms stay blocked.": "iOS ಇಂದಿನ ಬಳಕೆಯನ್ನು ಪರಿಶೀಲಿಸುವಾಗ ಮರುಪರಿಶೀಲನೆ ಈಗಿನ ಬ್ಲಾಕ್‌ಗಳನ್ನು ಹಾಗೇ ಇಡುತ್ತದೆ. iOS ದೃಢೀಕರಿಸುವ ಮಿತಿಗಳು ಬ್ಲಾಕ್ ಆಗಿಯೇ ಉಳಿಯುತ್ತವೆ.",
    "Limit recheck": "ಮಿತಿ ಮರುಪರಿಶೀಲನೆ",
    "Released %d stale limit blocks. %d limits were freshly confirmed by iOS.": "%d ಹಳೆಯ ಮಿತಿ ಬ್ಲಾಕ್‌ಗಳನ್ನು ಬಿಡುಗಡೆ ಮಾಡಲಾಗಿದೆ. %d ಮಿತಿಗಳನ್ನು iOS ಹೊಸದಾಗಿ ದೃಢೀಕರಿಸಿದೆ.",
    "iOS freshly confirmed all current limit blocks.": "iOS ಎಲ್ಲ ಈಗಿನ ಮಿತಿ ಬ್ಲಾಕ್‌ಗಳನ್ನು ಹೊಸದಾಗಿ ದೃಢೀಕರಿಸಿದೆ.",
    "No blocked limits need to be rechecked.": "ಮರುಪರಿಶೀಲಿಸಬೇಕಾದ ಬ್ಲಾಕ್ ಆದ ಮಿತಿಗಳಿಲ್ಲ.",
    "Wait until the active free period ends, then recheck again.": "ಸಕ್ರಿಯ ಮುಕ್ತ ಅವಧಿ ಮುಗಿಯುವವರೆಗೆ ಕಾಯಿರಿ, ನಂತರ ಮತ್ತೆ ಮರುಪರಿಶೀಲಿಸಿ.",
    "You can recheck again in %@.": "%@ ನಲ್ಲಿ ಮತ್ತೆ ಮರುಪರಿಶೀಲಿಸಬಹುದು.",
    "The recheck was interrupted. No blocks were changed.": "ಮರುಪರಿಶೀಲನೆ ಅಡಚಣೆಯಾಯಿತು. ಯಾವ ಬ್ಲಾಕ್ ಕೂಡ ಬದಲಾಗಿಲ್ಲ.",
    "iOS couldn't complete the verification safely. No blocks were changed. Try again later.": "iOS ಪರಿಶೀಲನೆಯನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಮುಗಿಸಲಾಗಲಿಲ್ಲ. ಯಾವ ಬ್ಲಾಕ್ ಕೂಡ ಬದಲಾಗಿಲ್ಲ. ನಂತರ ಪ್ರಯತ್ನಿಸಿ.",
    "Safe limit rechecking requires iOS 17.4 or later. No blocks were changed.": "ಸುರಕ್ಷಿತ ಮಿತಿ ಮರುಪರಿಶೀಲನೆಗೆ iOS 17.4 ಅಥವಾ ನಂತರದ ಆವೃತ್ತಿ ಬೇಕು. ಯಾವ ಬ್ಲಾಕ್ ಕೂಡ ಬದಲಾಗಿಲ್ಲ.",
    "This is a demo — nothing you do here is saved or actually blocked.": "ಇದು ಡೆಮೊ — ಇಲ್ಲಿ ನೀವು ಮಾಡುವುದು ಯಾವುದೂ ಉಳಿಯುವುದಿಲ್ಲ ಅಥವಾ ನಿಜವಾಗಿ ಬ್ಲಾಕ್ ಆಗುವುದಿಲ್ಲ.",
    "Limitations": "ಮಿತಿಗಳು",
