    "Calendar": "ಕ್ಯಾಲೆಂಡರ್",
    "week / month": "ವಾರ / ತಿಂಗಳು",
    "month": "ತಿಂಗಳು",
    "Solve math problems to skip a countdown.": "ಕಾಯುವಿಕೆ ಬಿಟ್ಟುಬಿಡಲು ಗಣಿತ ಸಮಸ್ಯೆಗಳನ್ನು ಬಿಡಿಸಿ.",
    "Enter a password to skip a countdown.": "ಕಾಯುವಿಕೆ ಬಿಟ್ಟುಬಿಡಲು ಪಾಸ್‌ವರ್ಡ್ ನಮೂದಿಸಿ.",
    "How schedules work": "ವೇಳಾಪಟ್ಟಿಗಳು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತವೆ",
    "Help": "ಸಹಾಯ",
    "thank you": "ಧನ್ಯವಾದಗಳು",
    "Guide": "ಮಾರ್ಗದರ್ಶಿ",
    "Contact": "ಸಂಪರ್ಕ",
    "About": "ಬಗ್ಗೆ",
    "how each part works": "ಪ್ರತಿ ಭಾಗ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ",
    "links": "ಲಿಂಕ್‌ಗಳು",
    "Report a bug": "ದೋಷ ವರದಿ ಮಾಡಿ",
    "Request a feature": "ಸೌಲಭ್ಯ ವಿನಂತಿಸಿ",
    "General help": "ಸಾಮಾನ್ಯ ಸಹಾಯ",
    "Website": "ವೆಬ್‌ಸೈಟ್",
    "Instagram": "Instagram",
    "What Demora is": "Demora ಎಂದರೆ ಏನು",
    "Demora protects your screen-time rules with a delay instead of a password. Every change you make waits out a countdown before it takes effect, so you can always change your mind — just not instantly, in a moment of weakness. Blocking itself is enforced by iOS through Screen Time.": "Demora ನಿಮ್ಮ ಸ್ಕ್ರೀನ್-ಟೈಮ್ ನಿಯಮಗಳನ್ನು ಪಾಸ್‌ವರ್ಡ್ ಬದಲು ಕಾಯುವಿಕೆಯಿಂದ ರಕ್ಷಿಸುತ್ತದೆ. ನೀವು ಮಾಡುವ ಪ್ರತಿ ಬದಲಾವಣೆ ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ಕೌಂಟ್‌ಡೌನ್ ಮುಗಿಯಬೇಕು, ಹಾಗಾಗಿ ಮನಸ್ಸು ಬದಲಿಸುವ ಸ್ವಾತಂತ್ರ್ಯ ಯಾವಾಗಲೂ ಇರುತ್ತದೆ — ಆದರೆ ದುರ್ಬಲ ಕ್ಷಣದಲ್ಲಿ ತಕ್ಷಣ ಅಲ್ಲ. ಬ್ಲಾಕ್ ಮಾಡುವುದನ್ನು iOS ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಮೂಲಕ ಜಾರಿಗೊಳಿಸುತ್ತದೆ.",
    "There are two delays. The more-strict delay gates changes that tighten your rules (adding a limit, lowering minutes, adding a schedule). The less-strict delay gates changes that loosen them (raising a limit, removing a block, adding a free period) — usually set longer. Pending changes show on the Home tab with a live countdown and can be cancelled before they apply.": "ಎರಡು ಕಾಯುವಿಕೆಗಳಿವೆ. ಹೆಚ್ಚು-ಕಠಿಣ ಕಾಯುವಿಕೆ ನಿಯಮಗಳನ್ನು ಬಿಗಿಗೊಳಿಸುವ ಬದಲಾವಣೆಗಳನ್ನು (ಮಿತಿ ಸೇರಿಸುವುದು, ನಿಮಿಷ ಕಡಿಮೆ ಮಾಡುವುದು, ವೇಳಾಪಟ್ಟಿ ಸೇರಿಸುವುದು) ತಡೆಹಿಡಿಯುತ್ತದೆ. ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆ ಅವನ್ನು ಸಡಿಲಿಸುವ ಬದಲಾವಣೆಗಳನ್ನು (ಮಿತಿ ಹೆಚ್ಚಿಸುವುದು, ಬ್ಲಾಕ್ ತೆಗೆಯುವುದು, ಮುಕ್ತ ಅವಧಿ ಸೇರಿಸುವುದು) ತಡೆಹಿಡಿಯುತ್ತದೆ — ಸಾಮಾನ್ಯವಾಗಿ ಹೆಚ್ಚು ಉದ್ದ ಇಡಲಾಗುತ್ತದೆ. ಬಾಕಿ ಬದಲಾವಣೆಗಳು ಮುಖಪುಟ ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಲೈವ್ ಕೌಂಟ್‌ಡೌನ್‌ನೊಂದಿಗೆ ಕಾಣುತ್ತವೆ ಮತ್ತು ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ರದ್ದುಮಾಡಬಹುದು.",
    "A limit is a daily time budget for the apps or categories you choose. When the minutes run out, those apps are blocked until midnight. The Limits tab shows today's usage per limit, and tapping a limit shows exactly which apps it covers.": "ಮಿತಿ ಎಂದರೆ ನೀವು ಆರಿಸುವ ಆ್ಯಪ್‌ಗಳು ಅಥವಾ ವರ್ಗಗಳ ದೈನಂದಿನ ಸಮಯ ಬಜೆಟ್. ನಿಮಿಷಗಳು ಮುಗಿದಾಗ, ಮಧ್ಯರಾತ್ರಿಯವರೆಗೆ ಆ ಆ್ಯಪ್‌ಗಳು ಬ್ಲಾಕ್ ಆಗುತ್ತವೆ. ಮಿತಿಗಳ ಟ್ಯಾಬ್ ಪ್ರತಿ ಮಿತಿಯ ಇಂದಿನ ಬಳಕೆಯನ್ನು ತೋರಿಸುತ್ತದೆ, ಮತ್ತು ಮಿತಿಯನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿದರೆ ಅದು ಯಾವ ಆ್ಯಪ್‌ಗಳನ್ನು ಒಳಗೊಂಡಿದೆ ಎಂದು ನಿಖರವಾಗಿ ಕಾಣುತ್ತದೆ.",
    "Schedules block apps on a repeating or one-off basis. Recurring schedules repeat daily, on chosen weekdays, or monthly. Planned windows are one-offs for specific dates. Sessions are immediate timed blocks or unblocks. Free periods are windows where limits don't block and usage doesn't count.": "ವೇಳಾಪಟ್ಟಿಗಳು ಪುನರಾವರ್ತಿತ ಅಥವಾ ಒಂದು ಬಾರಿಯ ರೀತಿಯಲ್ಲಿ ಆ್ಯಪ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡುತ್ತವೆ. ಪುನರಾವರ್ತಿತ ವೇಳಾಪಟ್ಟಿಗಳು ಪ್ರತಿದಿನ, ಆಯ್ದ ವಾರದ ದಿನಗಳಲ್ಲಿ ಅಥವಾ ಮಾಸಿಕ ಪುನರಾವರ್ತಿಸುತ್ತವೆ. ಯೋಜಿತ ಅವಧಿಗಳು ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕಗಳ ಒಂದು ಬಾರಿಯವು. ಸೆಷನ್‌ಗಳು ತಕ್ಷಣದ ಸಮಯದ ಬ್ಲಾಕ್ ಅಥವಾ ಅನ್‌ಬ್ಲಾಕ್. ಮುಕ್ತ ಅವಧಿಗಳಲ್ಲಿ ಮಿತಿಗಳು ಬ್ಲಾಕ್ ಮಾಡುವುದಿಲ್ಲ ಮತ್ತು ಬಳಕೆ ಎಣಿಕೆಯಾಗುವುದಿಲ್ಲ.",
    "A trusted contact can approve skipping a countdown — by email code or from their own Demora app. People you add must accept before they can approve, and you can revoke them at any time.": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ ಕಾಯುವಿಕೆ ಬಿಡಲು ಒಪ್ಪಬಹುದು — ಇಮೇಲ್ ಕೋಡ್ ಮೂಲಕ ಅಥವಾ ಅವರ ಸ್ವಂತ Demora ಆ್ಯಪ್‌ನಿಂದ. ನೀವು ಸೇರಿಸುವ ವ್ಯಕ್ತಿಗಳು ಒಪ್ಪುವ ಮೊದಲು ಆಹ್ವಾನ ಸ್ವೀಕರಿಸಬೇಕು, ಮತ್ತು ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ ಅವರನ್ನು ತೆಗೆಯಬಹುದು.",
    "App deletion lock": "ಆ್ಯಪ್ ಅಳಿಸುವಿಕೆ ಲಾಕ್",
    "the core idea": "ಮೂಲ ಆಲೋಚನೆ",
    "the two countdowns": "ಎರಡು ಕಾಯುವಿಕೆಗಳು",
    "daily app budgets": "ದೈನಂದಿನ ಆ್ಯಪ್ ಬಜೆಟ್‌ಗಳು",
    "recurring, planned, sessions": "ಪುನರಾವರ್ತಿತ, ಯೋಜಿತ, ಸೆಷನ್‌ಗಳು",
    "escape hatches": "ತಪ್ಪಿಸಿಕೊಳ್ಳುವ ದಾರಿಗಳು",
    "approval by a person": "ವ್ಯಕ್ತಿಯ ಒಪ್ಪಿಗೆ",
    "can't uninstall to bypass": "ಅಳಿಸಿ ತಪ್ಪಿಸಿಕೊಳ್ಳಲಾಗದು",
    "Most screen-time apps lock your rules behind a password. Because you know the password, you can undo your own rules the moment you feel the urge — so they rarely stick.\n\nDemora protects your rules with time instead. Every change waits out a countdown you set in advance before it takes effect. You stay in full control of your rules, but you can't change them in a single impulsive moment. The blocking itself is enforced by iOS through Screen Time — the same system parental controls use — so it can't be quietly bypassed.": "ಹೆಚ್ಚಿನ ಸ್ಕ್ರೀನ್-ಟೈಮ್ ಆ್ಯಪ್‌ಗಳು ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ಪಾಸ್‌ವರ್ಡ್ ಹಿಂದೆ ಲಾಕ್ ಮಾಡುತ್ತವೆ. ಪಾಸ್‌ವರ್ಡ್ ನಿಮಗೇ ಗೊತ್ತಿರುವುದರಿಂದ, ಆವೇಗ ಬಂದ ಕ್ಷಣದಲ್ಲೇ ನಿಮ್ಮದೇ ನಿಯಮಗಳನ್ನು ರದ್ದುಮಾಡಬಹುದು — ಹಾಗಾಗಿ ಅವು ಅಪರೂಪಕ್ಕೆ ಉಳಿಯುತ್ತವೆ.\n\nDemora ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ಸಮಯದಿಂದ ರಕ್ಷಿಸುತ್ತದೆ. ಪ್ರತಿ ಬದಲಾವಣೆ ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ನೀವು ಮೊದಲೇ ಹೊಂದಿಸಿದ ಕೌಂಟ್‌ಡೌನ್ ಮುಗಿಯಬೇಕು. ನಿಮ್ಮ ನಿಯಮಗಳ ಮೇಲೆ ನಿಮಗೇ ಪೂರ್ಣ ನಿಯಂತ್ರಣ ಇರುತ್ತದೆ, ಆದರೆ ಒಂದೇ ಆವೇಗದ ಕ್ಷಣದಲ್ಲಿ ಅವನ್ನು ಬದಲಿಸಲಾಗದು. ಬ್ಲಾಕ್ ಮಾಡುವುದನ್ನು iOS ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಮೂಲಕ ಜಾರಿಗೊಳಿಸುತ್ತದೆ — ಪೋಷಕ ನಿಯಂತ್ರಣಗಳು ಬಳಸುವ ಅದೇ ವ್ಯವಸ್ಥೆ — ಹಾಗಾಗಿ ಅದನ್ನು ಮೌನವಾಗಿ ತಪ್ಪಿಸಲಾಗದು.",
    "Demora has two delays. The more-strict delay covers any change that tightens your rules: adding a limit, lowering its minutes, adding a schedule, or turning on the deletion lock. The less-strict delay covers changes that loosen them: raising a limit, removing a block, adding a free period, or disabling an override. The less-strict delay is usually set longer, since loosening is where temptation lives.\n\nA change doesn't apply right away — it becomes a pending change with a live countdown on the Home tab. You can cancel it any time before it lands, and when the countdown reaches zero it applies on its own, even if the app is closed.": "Demora ದಲ್ಲಿ ಎರಡು ಕಾಯುವಿಕೆಗಳಿವೆ. ಹೆಚ್ಚು-ಕಠಿಣ ಕಾಯುವಿಕೆ ನಿಯಮಗಳನ್ನು ಬಿಗಿಗೊಳಿಸುವ ಯಾವುದೇ ಬದಲಾವಣೆಗೆ ಅನ್ವಯಿಸುತ್ತದೆ: ಮಿತಿ ಸೇರಿಸುವುದು, ನಿಮಿಷ ಕಡಿಮೆ ಮಾಡುವುದು, ವೇಳಾಪಟ್ಟಿ ಸೇರಿಸುವುದು, ಅಥವಾ ಅಳಿಸುವಿಕೆ ಲಾಕ್ ಆನ್ ಮಾಡುವುದು. ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆ ಅವನ್ನು ಸಡಿಲಿಸುವ ಬದಲಾವಣೆಗಳಿಗೆ: ಮಿತಿ ಹೆಚ್ಚಿಸುವುದು, ಬ್ಲಾಕ್ ತೆಗೆಯುವುದು, ಮುಕ್ತ ಅವಧಿ ಸೇರಿಸುವುದು, ಅಥವಾ ಒಪ್ಪಿಗೆಯ ವಿಧಾನ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದು. ಸಡಿಲಿಸುವುದರಲ್ಲೇ ಪ್ರಲೋಭನೆ ಇರುತ್ತದೆ, ಹಾಗಾಗಿ ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಹೆಚ್ಚು ಉದ್ದ ಇಡಲಾಗುತ್ತದೆ.\n\nಬದಲಾವಣೆ ತಕ್ಷಣ ಜಾರಿಯಾಗುವುದಿಲ್ಲ — ಮುಖಪುಟ ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಲೈವ್ ಕೌಂಟ್‌ಡೌನ್‌ನೊಂದಿಗೆ ಬಾಕಿ ಬದಲಾವಣೆಯಾಗುತ್ತದೆ. ಅದು ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ಯಾವಾಗ ಬೇಕಾದರೂ ರದ್ದುಮಾಡಬಹುದು, ಮತ್ತು ಕೌಂಟ್‌ಡೌನ್ ಶೂನ್ಯ ತಲುಪಿದಾಗ ಆ್ಯಪ್ ಮುಚ್ಚಿದ್ದರೂ ಅದು ತಾನಾಗಿ ಜಾರಿಯಾಗುತ್ತದೆ.",
    "A limit is a daily time budget for a set of apps or whole categories. When the minutes run out, those apps are blocked for the rest of the day and unlock again at midnight.\n\nThe Limits tab shows today's real usage for each limit, read straight from Screen Time, and tapping a limit reveals exactly which apps and categories it covers. Because usage is measured by iOS, time spent before you created the limit still counts toward it that day. Raising or removing a limit is a less-strict change; adding one or lowering its minutes is stricter.": "ಮಿತಿ ಎಂದರೆ ಒಂದು ಗುಂಪಿನ ಆ್ಯಪ್‌ಗಳು ಅಥವಾ ಇಡೀ ವರ್ಗಗಳ ದೈನಂದಿನ ಸಮಯ ಬಜೆಟ್. ನಿಮಿಷಗಳು ಮುಗಿದಾಗ, ದಿನದ ಉಳಿದ ಭಾಗ ಆ ಆ್ಯಪ್‌ಗಳು ಬ್ಲಾಕ್ ಆಗಿ ಮಧ್ಯರಾತ್ರಿ ಮತ್ತೆ ತೆರೆಯುತ್ತವೆ.\n\nಮಿತಿಗಳ ಟ್ಯಾಬ್ ಪ್ರತಿ ಮಿತಿಯ ಇಂದಿನ ನಿಜವಾದ ಬಳಕೆಯನ್ನು ಸ್ಕ್ರೀನ್ ಟೈಮ್‌ನಿಂದ ನೇರವಾಗಿ ತೋರಿಸುತ್ತದೆ; ಮಿತಿಯನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿದರೆ ಯಾವ ಆ್ಯಪ್‌ಗಳು ಮತ್ತು ವರ್ಗಗಳು ಒಳಗೊಂಡಿವೆ ಎಂದು ಕಾಣುತ್ತದೆ. ಬಳಕೆಯನ್ನು iOS ಅಳೆಯುವುದರಿಂದ, ಮಿತಿ ರಚಿಸುವ ಮೊದಲು ಕಳೆದ ಸಮಯವೂ ಆ ದಿನ ಅದಕ್ಕೆ ಎಣಿಕೆಯಾಗುತ್ತದೆ. ಮಿತಿ ಹೆಚ್ಚಿಸುವುದು ಅಥವಾ ತೆಗೆಯುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ; ಒಂದನ್ನು ಸೇರಿಸುವುದು ಅಥವಾ ನಿಮಿಷ ಕಡಿಮೆ ಮಾಡುವುದು ಹೆಚ್ಚು ಕಠಿಣ.",
    "Schedules block apps by time rather than by budget, in a few shapes. Recurring schedules repeat — every day, on chosen weekdays, or on a monthly pattern. Planned windows are one-offs for a specific date, like a trip or an exam. Sessions are immediate, timed blocks or unblocks you start right now. Free periods are windows where limits don't block and usage doesn't count toward them.\n\nEach blocking schedule either blocks the apps you pick, or blocks everything except the apps you pick. When rules overlap, the most specific one wins: a session beats a planned window, which beats a recurring schedule, and within the same kind the one added most recently takes priority.": "ವೇಳಾಪಟ್ಟಿಗಳು ಬಜೆಟ್ ಬದಲು ಸಮಯದ ಆಧಾರದ ಮೇಲೆ ಬ್ಲಾಕ್ ಮಾಡುತ್ತವೆ, ಹಲವು ರೂಪಗಳಲ್ಲಿ. ಪುನರಾವರ್ತಿತ ವೇಳಾಪಟ್ಟಿಗಳು — ಪ್ರತಿದಿನ, ಆಯ್ದ ವಾರದ ದಿನಗಳಲ್ಲಿ ಅಥವಾ ಮಾಸಿಕ ಮಾದರಿಯಲ್ಲಿ — ಪುನರಾವರ್ತಿಸುತ್ತವೆ. ಯೋಜಿತ ಅವಧಿಗಳು ಪ್ರವಾಸ ಅಥವಾ ಪರೀಕ್ಷೆಯಂತಹ ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕದ ಒಂದು ಬಾರಿಯವು. ಸೆಷನ್‌ಗಳು ನೀವು ಈಗಲೇ ಆರಂಭಿಸುವ ತಕ್ಷಣದ ಸಮಯದ ಬ್ಲಾಕ್ ಅಥವಾ ಅನ್‌ಬ್ಲಾಕ್. ಮುಕ್ತ ಅವಧಿಗಳಲ್ಲಿ ಮಿತಿಗಳು ಬ್ಲಾಕ್ ಮಾಡುವುದಿಲ್ಲ ಮತ್ತು ಬಳಕೆ ಅವುಗಳಿಗೆ ಎಣಿಕೆಯಾಗುವುದಿಲ್ಲ.\n\nಪ್ರತಿ ಬ್ಲಾಕ್ ವೇಳಾಪಟ್ಟಿ ನೀವು ಆರಿಸಿದ ಆ್ಯಪ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡುತ್ತದೆ, ಅಥವಾ ನೀವು ಆರಿಸಿದವನ್ನು ಬಿಟ್ಟು ಎಲ್ಲವನ್ನೂ ಬ್ಲಾಕ್ ಮಾಡುತ್ತದೆ. ನಿಯಮಗಳು ಅತಿಕ್ರಮಿಸಿದಾಗ ಅತಿ ನಿರ್ದಿಷ್ಟವಾದದ್ದು ಗೆಲ್ಲುತ್ತದೆ: ಸೆಷನ್ ಯೋಜಿತ ಅವಧಿಯನ್ನು ಮೀರಿಸುತ್ತದೆ, ಅದು ಪುನರಾವರ್ತಿತ ವೇಳಾಪಟ್ಟಿಯನ್ನು ಮೀರಿಸುತ್ತದೆ, ಮತ್ತು ಒಂದೇ ರೀತಿಯಲ್ಲಿ ಇತ್ತೀಚೆಗೆ ಸೇರಿಸಿದ್ದಕ್ಕೆ ಆದ್ಯತೆ.",
    "Overrides are optional escape hatches that let you skip a pending change's countdown. There are three: solve a set of math problems, enter a password, or ask a trusted contact to approve. They're all off by default, so out of the box your delays are absolute.\n\nTurning an override on, or making it easier, counts as a less-strict change and waits out that delay. Turning one off, or making it harder, is stricter — so you can't instantly weaken your own safety net.": "ಒಪ್ಪಿಗೆಗಳು ಬಾಕಿ ಬದಲಾವಣೆಯ ಕೌಂಟ್‌ಡೌನ್ ಬಿಟ್ಟುಬಿಡಲು ಐಚ್ಛಿಕ ತಪ್ಪಿಸಿಕೊಳ್ಳುವ ದಾರಿಗಳು. ಮೂರಿವೆ: ಗಣಿತ ಸಮಸ್ಯೆಗಳನ್ನು ಬಿಡಿಸಿ, ಪಾಸ್‌ವರ್ಡ್ ನಮೂದಿಸಿ, ಅಥವಾ ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕದಿಂದ ಒಪ್ಪಿಗೆ ಕೇಳಿ. ಎಲ್ಲವೂ ಡೀಫಾಲ್ಟ್ ಆಗಿ ಆಫ್, ಹಾಗಾಗಿ ಆರಂಭದಲ್ಲಿ ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳು ಸಂಪೂರ್ಣ.\n\nಒಪ್ಪಿಗೆಯನ್ನು ಆನ್ ಮಾಡುವುದು ಅಥವಾ ಸುಲಭಗೊಳಿಸುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ ಮತ್ತು ಆ ಕಾಯುವಿಕೆಯನ್ನು ಅನುಸರಿಸುತ್ತದೆ. ಒಂದನ್ನು ಆಫ್ ಮಾಡುವುದು ಅಥವಾ ಕಠಿಣಗೊಳಿಸುವುದು ಹೆಚ್ಚು ಕಠಿಣ — ಹಾಗಾಗಿ ನಿಮ್ಮ ಸುರಕ್ಷತಾ ಬಲೆಯನ್ನು ತಕ್ಷಣ ದುರ್ಬಲಗೊಳಿಸಲಾಗದು.",
    "A trusted contact is a person who can approve skipping a countdown for you. They can approve by entering a short code sent to their email, or directly from their own copy of Demora.\n\nAnyone you add has to accept the request before they can approve anything, so no one is involved without their knowledge. You can revoke a contact at any time, and they can step down on their side too. Adding the override is a less-strict change; removing it is stricter.": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ ಎಂದರೆ ನಿಮ್ಮ ಪರವಾಗಿ ಕೌಂಟ್‌ಡೌನ್ ಬಿಡಲು ಒಪ್ಪಬಹುದಾದ ವ್ಯಕ್ತಿ. ಅವರು ತಮ್ಮ ಇಮೇಲ್‌ಗೆ ಕಳುಹಿಸಿದ ಚಿಕ್ಕ ಕೋಡ್ ನಮೂದಿಸಿ, ಅಥವಾ ತಮ್ಮದೇ Demora ನಿಂದ ನೇರವಾಗಿ ಒಪ್ಪಬಹುದು.\n\nನೀವು ಸೇರಿಸುವ ಯಾರಾದರೂ ಏನನ್ನಾದರೂ ಒಪ್ಪುವ ಮೊದಲು ವಿನಂತಿ ಸ್ವೀಕರಿಸಬೇಕು, ಹಾಗಾಗಿ ಯಾರೂ ತಿಳಿಯದೆ ತೊಡಗುವುದಿಲ್ಲ. ಸಂಪರ್ಕವನ್ನು ಯಾವಾಗ ಬೇಕಾದರೂ ತೆಗೆಯಬಹುದು, ಅವರೂ ತಮ್ಮ ಕಡೆಯಿಂದ ಹಿಂದೆ ಸರಿಯಬಹುದು. ಒಪ್ಪಿಗೆ ಸೇರಿಸುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ; ತೆಗೆಯುವುದು ಹೆಚ್ಚು ಕಠಿಣ.",
    "When the deletion lock is on, deleting any app from this iPhone is blocked — including Demora itself. That closes the most obvious loophole: uninstalling the app to wipe your rules.\n\nBecause turning the lock off makes things easier to bypass, it counts as a less-strict change and waits out that delay before it takes effect.": "ಅಳಿಸುವಿಕೆ ಲಾಕ್ ಆನ್ ಇದ್ದಾಗ, ಈ iPhone ನಿಂದ ಯಾವುದೇ ಆ್ಯಪ್ ಅಳಿಸುವುದು ತಡೆಯಲಾಗುತ್ತದೆ — Demora ಸೇರಿದಂತೆ. ಅದು ಅತ್ಯಂತ ಸ್ಪಷ್ಟ ಲೋಪವನ್ನು ಮುಚ್ಚುತ್ತದೆ: ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ಅಳಿಸಿಹಾಕಲು ಆ್ಯಪ್ ಅನ್ನು ಅಳಿಸುವುದು.\n\nಲಾಕ್ ಆಫ್ ಮಾಡುವುದು ತಪ್ಪಿಸಿಕೊಳ್ಳುವುದನ್ನು ಸುಲಭ ಮಾಡುವುದರಿಂದ, ಅದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ ಮತ್ತು ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ಆ ಕಾಯುವಿಕೆ ಮುಗಿಯಬೇಕು.",
    "When on, deleting any app from this iPhone is blocked — including Demora itself — so your rules can't be bypassed by uninstalling. Turning it off goes through the less-strict delay.": "ಆನ್ ಇದ್ದಾಗ, ಈ iPhone ನಿಂದ ಯಾವುದೇ ಆ್ಯಪ್ ಅಳಿಸುವುದು ತಡೆಯಲಾಗುತ್ತದೆ — Demora ಸೇರಿದಂತೆ — ಹಾಗಾಗಿ ಅಳಿಸಿ ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ತಪ್ಪಿಸಲಾಗದು. ಆಫ್ ಮಾಡುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯ ಮೂಲಕ ಹೋಗುತ್ತದೆ.",
    "Blocks": "ಬ್ಲಾಕ್‌ಗಳು",
    "New recurring": "ಹೊಸ ಪುನರಾವರ್ತಿತ",
    "Week": "ವಾರ",
    "Month": "ತಿಂಗಳು",
    "Nothing on this day.": "ಈ ದಿನ ಏನೂ ಇಲ್ಲ.",
    "When things overlap": "ಅತಿಕ್ರಮಣವಾದಾಗ",
    "One-off, right now: block or unblock chosen apps for a set number of minutes. Still delay-gated to start; ending early flips the rule.": "ಒಂದು ಬಾರಿ, ಈಗಲೇ: ಆಯ್ದ ಆ್ಯಪ್‌ಗಳನ್ನು ಕೆಲವು ನಿಮಿಷ ಬ್ಲಾಕ್ ಅಥವಾ ಅನ್‌ಬ್ಲಾಕ್ ಮಾಡಿ. ಆರಂಭಿಸಲು ಇನ್ನೂ ಕಾಯುವಿಕೆ ಇದೆ; ಬೇಗ ಮುಗಿಸುವುದು ನಿಯಮವನ್ನು ತಿರುಗಿಸುತ್ತದೆ.",
    "One-off windows for specific dates — a trip, an exam. Block, allow-all-except, or a free period. Doesn't repeat.": "ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕಗಳ ಒಂದು ಬಾರಿಯ ಅವಧಿಗಳು — ಪ್ರವಾಸ, ಪರೀಕ್ಷೆ. ಬ್ಲಾಕ್, ಇವನ್ನು ಬಿಟ್ಟು ಎಲ್ಲವನ್ನೂ ಅನುಮತಿಸಿ, ಅಥವಾ ಮುಕ್ತ ಅವಧಿ. ಪುನರಾವರ್ತಿಸುವುದಿಲ್ಲ.",
    "Windows that repeat — daily, by weekday, or monthly. Each is either a block or a free period.": "ಪುನರಾವರ್ತಿಸುವ ಅವಧಿಗಳು — ದೈನಂದಿನ, ವಾರದ ದಿನಗಳ ಪ್ರಕಾರ, ಅಥವಾ ಮಾಸಿಕ. ಪ್ರತಿಯೊಂದೂ ಬ್ಲಾಕ್ ಅಥವಾ ಮುಕ್ತ ಅವಧಿ.",
    "Limits don't block during the window, and time used inside it doesn't count against your daily budgets.": "ಅವಧಿಯಲ್ಲಿ ಮಿತಿಗಳು ಬ್ಲಾಕ್ ಮಾಡುವುದಿಲ್ಲ, ಮತ್ತು ಅದರೊಳಗೆ ಬಳಸಿದ ಸಮಯ ನಿಮ್ಮ ದೈನಂದಿನ ಬಜೆಟ್‌ಗಳಿಗೆ ಎಣಿಕೆಯಾಗುವುದಿಲ್ಲ.",
    "Priority: a session beats a planned window, which beats a recurring schedule. Within the same kind, the one you added most recently wins.": "ಆದ್ಯತೆ: ಸೆಷನ್ ಯೋಜಿತ ಅವಧಿಯನ್ನು ಮೀರಿಸುತ್ತದೆ, ಅದು ಪುನರಾವರ್ತಿತ ವೇಳಾಪಟ್ಟಿಯನ್ನು ಮೀರಿಸುತ್ತದೆ. ಒಂದೇ ರೀತಿಯಲ್ಲಿ ನೀವು ಇತ್ತೀಚೆಗೆ ಸೇರಿಸಿದ್ದು ಗೆಲ್ಲುತ್ತದೆ.",
