    "People you approve for": "ನೀವು ಯಾರಿಗಾಗಿ ಒಪ್ಪುತ್ತೀರಿ",
    "These people have you as a trusted contact. Removing yourself tells them and stops their requests.": "ಈ ಜನರು ನಿಮ್ಮನ್ನು ತಮ್ಮ ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವಾಗಿ ಹೊಂದಿದ್ದಾರೆ. ನಿಮ್ಮನ್ನು ತೆಗೆದುಕೊಂಡರೆ ಅವರಿಗೆ ತಿಳಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಅವರ ವಿನಂತಿಗಳು ನಿಲ್ಲುತ್ತವೆ.",
