    "You already have this person as a contact.": "ಈ ವ್ಯಕ್ತಿ ಈಗಾಗಲೇ ನಿಮ್ಮ ಸಂಪರ್ಕದಲ್ಲಿದ್ದಾರೆ.",
    "Blocked users": "ಬ್ಲಾಕ್ ಮಾಡಿದ ಬಳಕೆದಾರರು",
    "No requests yet.": "ಇನ್ನೂ ವಿನಂತಿಗಳಿಲ್ಲ.",
    "No blocked users.": "ಬ್ಲಾಕ್ ಮಾಡಿದ ಬಳಕೆದಾರರಿಲ್ಲ.",
    "Blocked": "ಬ್ಲಾಕ್ ಆಗಿದೆ",
    "Accepted": "ಸ್ವೀಕರಿಸಲಾಗಿದೆ",
    "Declined": "ನಿರಾಕರಿಸಲಾಗಿದೆ",
    "Requested": "ವಿನಂತಿಸಲಾಗಿದೆ",
    "Accept": "ಸ್ವೀಕರಿಸಿ",
    "Decline": "ನಿರಾಕರಿಸಿ",
    "Pending": "ಬಾಕಿ",
    "Waiting for them to accept in their Demora app.": "ಅವರು ತಮ್ಮ Demora ಆ್ಯಪ್‌ನಲ್ಲಿ ಸ್ವೀಕರಿಸಲು ಕಾಯಲಾಗುತ್ತಿದೆ.",
    "A trusted contact can let you skip a pending change's countdown — by emailing you a one-time code, or, if they use Demora, by approving from their own app.": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ ಬಾಕಿ ಬದಲಾವಣೆಯ ಕೌಂಟ್‌ಡೌನ್ ಬಿಡಲು ನಿಮಗೆ ಅವಕಾಶ ನೀಡಬಹುದು — ಒಂದು ಬಾರಿಯ ಕೋಡ್ ಇಮೇಲ್ ಮಾಡುವ ಮೂಲಕ, ಅಥವಾ ಅವರು Demora ಬಳಸಿದರೆ ತಮ್ಮ ಆ್ಯಪ್‌ನಿಂದ ಒಪ್ಪುವ ಮೂಲಕ.",
    "Share this code so another Demora user can add you. You get a request to accept before it's active.": "ಇನ್ನೊಬ್ಬ Demora ಬಳಕೆದಾರ ನಿಮ್ಮನ್ನು ಸೇರಿಸಲು ಈ ಕೋಡ್ ಹಂಚಿಕೊಳ್ಳಿ. ಅದು ಸಕ್ರಿಯವಾಗುವ ಮೊದಲು ಸ್ವೀಕರಿಸಲು ನಿಮಗೆ ವಿನಂತಿ ಬರುತ್ತದೆ.",
    "A Demora user (code %@) wants to add you as their trusted contact.": "ಒಬ್ಬ Demora ಬಳಕೆದಾರ (ಕೋಡ್ %@) ನಿಮ್ಮನ್ನು ತಮ್ಮ ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವಾಗಿ ಸೇರಿಸಲು ಬಯಸುತ್ತಾರೆ.",
    "%@ (code %@) wants to add you as their trusted contact.": "%@ (ಕೋಡ್ %@) ನಿಮ್ಮನ್ನು ತಮ್ಮ ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವಾಗಿ ಸೇರಿಸಲು ಬಯಸುತ್ತಾರೆ.",
    "If you accept, they can ask you to approve skipping their delays.": "ನೀವು ಸ್ವೀಕರಿಸಿದರೆ, ಅವರ ಕಾಯುವಿಕೆಗಳನ್ನು ಬಿಟ್ಟುಬಿಡಲು ಒಪ್ಪುವಂತೆ ಅವರು ನಿಮ್ಮನ್ನು ಕೇಳಬಹುದು.",
    "Email contacts work as soon as you add them. Demora-user contacts must accept first. Adding a contact is a less-strict change; removing one is stricter — both go through delays.": "ಇಮೇಲ್ ಸಂಪರ್ಕಗಳು ಸೇರಿಸಿದ ತಕ್ಷಣ ಕೆಲಸ ಮಾಡುತ್ತವೆ. Demora ಬಳಕೆದಾರ ಸಂಪರ್ಕಗಳು ಮೊದಲು ಸ್ವೀಕರಿಸಬೇಕು. ಸಂಪರ್ಕ ಸೇರಿಸುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ; ತೆಗೆಯುವುದು ಹೆಚ್ಚು ಕಠಿಣ — ಎರಡೂ ಕಾಯುವಿಕೆಗಳ ಮೂಲಕ ಹೋಗುತ್ತವೆ.",
    "change": "ಬದಲಿಸಿ",
    "Text case": "ಅಕ್ಷರ ರೂಪ",
    "lowercase": "ಚಿಕ್ಕ ಅಕ್ಷರ",
    "Regular": "ಸಾಮಾನ್ಯ",
    "6-digit code": "6 ಅಂಕಿಯ ಕೋಡ್",
    "Add contact": "ಸಂಪರ್ಕ ಸೇರಿಸಿ",
    "Add contact…": "ಸಂಪರ್ಕ ಸೇರಿಸಿ…",
    "Add trusted contact: %@": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ ಸೇರಿಸಿ: %@",
    "Adding a contact is a less-strict change; removing one is stricter — both go through delays.": "ಸಂಪರ್ಕ ಸೇರಿಸುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ; ತೆಗೆಯುವುದು ಹೆಚ್ಚು ಕಠಿಣ — ಎರಡೂ ಕಾಯುವಿಕೆಗಳ ಮೂಲಕ ಹೋಗುತ್ತವೆ.",
    "Approval requests": "ಒಪ್ಪಿಗೆ ವಿನಂತಿಗಳು",
    "Approve": "ಒಪ್ಪಿ",
    "Ask a trusted contact": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವನ್ನು ಕೇಳಿ",
    "Ask them for the code shown in their Demora settings.": "ಅವರ Demora ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ತೋರಿಸಿರುವ ಕೋಡ್ ಅವರನ್ನು ಕೇಳಿ.",
    "Checking…": "ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
    "Checks automatically every few seconds. The request expires after 1 hour.": "ಪ್ರತಿ ಕೆಲವು ಸೆಕೆಂಡ್‌ಗೆ ತಾನಾಗಿ ಪರಿಶೀಲಿಸುತ್ತದೆ. ವಿನಂತಿ 1 ಗಂಟೆಯ ನಂತರ ಮುಗಿಯುತ್ತದೆ.",
    "approvers, blocked": "ಒಪ್ಪುವವರು, ಬ್ಲಾಕ್ ಆದವರು",
    "Couldn't send the request — check your connection and try again.": "ವಿನಂತಿ ಕಳುಹಿಸಲಾಗಲಿಲ್ಲ — ನಿಮ್ಮ ಸಂಪರ್ಕ ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
