    "Block adult websites": "ವಯಸ್ಕ ವೆಬ್‌ಸೈಟ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡಿ",
    "Allow adult websites": "ವಯಸ್ಕ ವೆಬ್‌ಸೈಟ್‌ಗಳನ್ನು ಅನುಮತಿಸಿ",
    "Uses Apple's built-in filter to limit adult websites in Safari and other apps.": "Safari ಮತ್ತು ಇತರ ಆ್ಯಪ್‌ಗಳಲ್ಲಿ ವಯಸ್ಕ ವೆಬ್‌ಸೈಟ್‌ಗಳನ್ನು ಮಿತಿಗೊಳಿಸಲು Apple ನ ಒಳಗಿನ ಫಿಲ್ಟರ್ ಬಳಸುತ್ತದೆ.",
    "Website blocker": "ವೆಬ್‌ಸೈಟ್ ಬ್ಲಾಕರ್",
    "Block website: %@": "ವೆಬ್‌ಸೈಟ್ ಬ್ಲಾಕ್ ಮಾಡಿ: %@",
