    "e.g. reddit.com": "ಉದಾ. reddit.com",
    "Queue: remove": "ಸರದಿ: ತೆಗೆಯಿರಿ",
    "Block specific websites by typing their domain — no need for Apple's site picker, which often comes up empty. Note: blocking sites also turns on Apple's adult-content filter. Adding a site is gated by your delays; removing one waits the longer delay.": "ಡೊಮೇನ್ ಟೈಪ್ ಮಾಡಿ ನಿರ್ದಿಷ್ಟ ವೆಬ್‌ಸೈಟ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡಿ — ಆಗಾಗ ಖಾಲಿ ಬರುವ Apple ನ ಸೈಟ್ ಪಿಕರ್ ಬೇಕಿಲ್ಲ. ಗಮನಿಸಿ: ಸೈಟ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡಿದರೆ Apple ನ ವಯಸ್ಕ-ವಿಷಯ ಫಿಲ್ಟರ್ ಕೂಡ ಆನ್ ಆಗುತ್ತದೆ. ಸೈಟ್ ಸೇರಿಸುವುದು ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳಿಗೆ ಒಳಪಡುತ್ತದೆ; ತೆಗೆಯುವುದು ಉದ್ದ ಕಾಯುವಿಕೆಗೆ ಒಳಪಡುತ್ತದೆ.",
    "Blocked all day": "ದಿನವಿಡೀ ಬ್ಲಾಕ್",
    "Adult websites": "ವಯಸ್ಕ ವೆಬ್‌ಸೈಟ್‌ಗಳು",
    "%d sites": "%d ಸೈಟ್‌ಗಳು",
    "Blocked sites": "ಬ್ಲಾಕ್ ಆದ ಸೈಟ್‌ಗಳು",
    "Stop apps from being deleted, limit adult websites, or block specific sites by domain. Every change here goes through your delays.": "ಆ್ಯಪ್‌ಗಳ ಅಳಿಸುವಿಕೆ ತಡೆಯಿರಿ, ವಯಸ್ಕ ವೆಬ್‌ಸೈಟ್‌ಗಳನ್ನು ಮಿತಿಗೊಳಿಸಿ, ಅಥವಾ ಡೊಮೇನ್ ಮೂಲಕ ನಿರ್ದಿಷ್ಟ ಸೈಟ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡಿ. ಇಲ್ಲಿನ ಪ್ರತಿ ಬದಲಾವಣೆ ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳ ಮೂಲಕ ಹೋಗುತ್ತದೆ.",
