    "Approval emails are at capacity right now. Try again later, or use a Demora contact.": "ಒಪ್ಪಿಗೆ ಇಮೇಲ್‌ಗಳು ಈಗ ಸಾಮರ್ಥ್ಯ ಮೀರಿವೆ. ನಂತರ ಪ್ರಯತ್ನಿಸಿ, ಅಥವಾ Demora ಸಂಪರ್ಕ ಬಳಸಿ.",
    "You've sent today": "ನೀವು ಇಂದು ಕಳುಹಿಸಿದ್ದು",
