    "All users · this month": "ಎಲ್ಲ ಬಳಕೆದಾರರು · ಈ ತಿಂಗಳು",
    "Email approvals": "ಇಮೇಲ್ ಒಪ್ಪಿಗೆಗಳು",
    "Email contacts have a daily send limit; Demora-user contacts don't.": "ಇಮೇಲ್ ಸಂಪರ್ಕಗಳಿಗೆ ದೈನಂದಿನ ಕಳುಹಿಸುವ ಮಿತಿ ಇದೆ; Demora ಬಳಕೆದಾರ ಸಂಪರ್ಕಗಳಿಗೆ ಇಲ್ಲ.",
    "one-time, forever": "ಒಂದು ಬಾರಿ, ಶಾಶ್ವತ",
    "active": "ಸಕ್ರಿಯ",
    "Deny": "ನಿರಾಕರಿಸಿ",
    "Disable trusted-contact override": "ನಂಬಿಕಸ್ಥ-ಸಂಪರ್ಕ ಒಪ್ಪಿಗೆ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ",
    "Email": "ಇಮೇಲ್",
    "Email address": "ಇಮೇಲ್ ವಿಳಾಸ",
    "Email contacts aren't available yet in this build.": "ಈ ಬಿಲ್ಡ್‌ನಲ್ಲಿ ಇಮೇಲ್ ಸಂಪರ್ಕಗಳು ಇನ್ನೂ ಲಭ್ಯವಿಲ್ಲ.",
    "Enable trusted-contact override": "ನಂಬಿಕಸ್ಥ-ಸಂಪರ್ಕ ಒಪ್ಪಿಗೆ ಸಕ್ರಿಯಗೊಳಿಸಿ",
    "Friends who use Demora can add you as their trusted contact with this code.": "Demora ಬಳಸುವ ಸ್ನೇಹಿತರು ಈ ಕೋಡ್‌ನಿಂದ ನಿಮ್ಮನ್ನು ತಮ್ಮ ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವಾಗಿ ಸೇರಿಸಬಹುದು.",
    "Demora user": "Demora ಬಳಕೆದಾರ",
    "My code": "ನನ್ನ ಕೋಡ್",
    "No Demora user found with that code.": "ಆ ಕೋಡ್‌ನ Demora ಬಳಕೆದಾರ ಸಿಗಲಿಲ್ಲ.",
    "Remove trusted contact: %@": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ ತೆಗೆಯಿರಿ: %@",
    "Send request": "ವಿನಂತಿ ಕಳುಹಿಸಿ",
    "Sending…": "ಕಳುಹಿಸಲಾಗುತ್ತಿದೆ…",
    "Someone set you as their trusted contact and wants to skip a waiting period.": "ಯಾರೋ ನಿಮ್ಮನ್ನು ತಮ್ಮ ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವಾಗಿ ಹೊಂದಿಸಿದ್ದಾರೆ ಮತ್ತು ಕಾಯುವ ಅವಧಿ ಬಿಟ್ಟುಬಿಡಲು ಬಯಸುತ್ತಾರೆ.",
    "Their Demora code": "ಅವರ Demora ಕೋಡ್",
    "Trusted contacts": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕಗಳು",
    "Verify code": "ಕೋಡ್ ಪರಿಶೀಲಿಸಿ",
    "When enabled, a trusted contact can let you skip a pending change's countdown — by emailing you a code, or by approving from their own Demora app.": "ಆನ್ ಇದ್ದಾಗ, ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ ನಿಮಗೆ ಕೋಡ್ ಇಮೇಲ್ ಮಾಡಿ ಅಥವಾ ತಮ್ಮ ಸ್ವಂತ Demora ಆ್ಯಪ್‌ನಿಂದ ಒಪ್ಪಿ, ಬಾಕಿ ಬದಲಾವಣೆಯ ಕೌಂಟ್‌ಡೌನ್ ಬಿಡಲು ನಿಮಗೆ ಅವಕಾಶ ನೀಡಬಹುದು.",
    "Wrong or expired code.": "ಕೋಡ್ ತಪ್ಪು ಅಥವಾ ಅವಧಿ ಮುಗಿದಿದೆ.",
    "Your contact received a code by email. Enter it here. It expires in 15 minutes.": "ನಿಮ್ಮ ಸಂಪರ್ಕಕ್ಕೆ ಇಮೇಲ್‌ನಲ್ಲಿ ಕೋಡ್ ಬಂದಿದೆ. ಅದನ್ನು ಇಲ್ಲಿ ನಮೂದಿಸಿ. ಇದು 15 ನಿಮಿಷಗಳಲ್ಲಿ ಮುಗಿಯುತ್ತದೆ.",
    "contact": "ಸಂಪರ್ಕ",
    "e.g. Mom, Alex": "ಉದಾ. ಅಮ್ಮ, ಅಲೆಕ್ಸ್",
    "%@ (%d problems)": "%@ (%d ಸಮಸ್ಯೆಗಳು)",
    "%@ session: %@ (%d min)": "%@ ಸೆಷನ್: %@ (%d ನಿಮಿ)",
    "%@ — session starts in %@, then runs %d min": "%@ — ಸೆಷನ್ %@ ನಲ್ಲಿ ಆರಂಭ, ನಂತರ %d ನಿಮಿಷ ನಡೆಯುತ್ತದೆ",
    "%@ — takes effect in %@": "%@ — %@ ನಲ್ಲಿ ಜಾರಿಗೆ ಬರುತ್ತದೆ",
    "%d apps, %d categories": "%d ಆ್ಯಪ್‌ಗಳು, %d ವರ್ಗಗಳು",
    "%d hr": "%d ಗಂ",
    "%d min": "%d ನಿಮಿ",
    "%d min/day": "%d ನಿಮಿ/ದಿನ",
    "%d minutes": "%d ನಿಮಿಷ",
    "%d minutes/day": "%d ನಿಮಿಷ/ದಿನ",
    "%d selected": "%d ಆಯ್ಕೆ",
    "ACTIVE": "ಸಕ್ರಿಯ",
    "Add a daily time limit. It activates after your 'more strict' delay (%@).": "ದೈನಂದಿನ ಸಮಯ ಮಿತಿ ಸೇರಿಸಿ. ನಿಮ್ಮ \"ಹೆಚ್ಚು ಕಠಿಣ\" ಕಾಯುವಿಕೆಯ ನಂತರ (%@) ಅದು ಸಕ್ರಿಯವಾಗುತ್ತದೆ.",
    "Add free period: %@ (%@)": "ಮುಕ್ತ ಅವಧಿ ಸೇರಿಸಿ: %@ (%@)",
    "Add free period…": "ಮುಕ್ತ ಅವಧಿ ಸೇರಿಸಿ…",
    "Add limit: %@ — %d min/day": "ಮಿತಿ ಸೇರಿಸಿ: %@ — %d ನಿಮಿ/ದಿನ",
    "Add me": "ನನ್ನನ್ನು ಸೇರಿಸಿ",
    "Add my name…": "ನನ್ನ ಹೆಸರು ಸೇರಿಸಿ…",
    "Add schedule: %@ (%@ %@)": "ವೇಳಾಪಟ್ಟಿ ಸೇರಿಸಿ: %@ (%@ %@)",
    "Add schedule…": "ವೇಳಾಪಟ್ಟಿ ಸೇರಿಸಿ…",
    "Adding…": "ಸೇರಿಸಲಾಗುತ್ತಿದೆ…",
    "Allow app deletion": "ಆ್ಯಪ್ ಅಳಿಸುವಿಕೆ ಅನುಮತಿಸಿ",
    "App deletion": "ಆ್ಯಪ್ ಅಳಿಸುವಿಕೆ",
    "Apply now…": "ಈಗ ಅನ್ವಯಿಸಿ…",
    "Permissions": "ಅನುಮತಿಗಳು",
    "Demora needs Screen Time access to set limits and block apps, and notifications to tell you when a pending change is ready. iOS will ask for each.": "ಮಿತಿ ಹೊಂದಿಸಲು ಮತ್ತು ಆ್ಯಪ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡಲು Demora ಗೆ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪ್ರವೇಶ ಬೇಕು, ಮತ್ತು ಬಾಕಿ ಬದಲಾವಣೆ ಸಿದ್ಧವಾದಾಗ ತಿಳಿಸಲು ಅಧಿಸೂಚನೆಗಳು ಬೇಕು. iOS ಪ್ರತಿಯೊಂದಕ್ಕೂ ಕೇಳುತ್ತದೆ.",
    "Grant access": "ಪ್ರವೇಶ ನೀಡಿ",
    "Welcome to Demora": "Demora ಗೆ ಸ್ವಾಗತ",
    "Demora can be a lot at first, so let's set up your first limit together — a quick, hands-on walkthrough of how delays and overrides actually feel. It takes about a minute.": "Demora ಮೊದಲಿಗೆ ಸ್ವಲ್ಪ ಹೆಚ್ಚು ಅನಿಸಬಹುದು, ಹಾಗಾಗಿ ನಿಮ್ಮ ಮೊದಲ ಮಿತಿಯನ್ನು ಒಟ್ಟಿಗೇ ಹೊಂದಿಸೋಣ — ಕಾಯುವಿಕೆಗಳು ಮತ್ತು ಒಪ್ಪಿಗೆಗಳು ನಿಜವಾಗಿ ಹೇಗಿರುತ್ತವೆ ಎಂದು ಕೈಯಾರೆ ನೋಡುವ ಚಿಕ್ಕ ವಾಕ್‌ಥ್ರೂ. ಸುಮಾರು ಒಂದು ನಿಮಿಷ ಸಾಕು.",
    "Add my first limit": "ನನ್ನ ಮೊದಲ ಮಿತಿ ಸೇರಿಸಿ",
    "Add your first limit": "ನಿಮ್ಮ ಮೊದಲ ಮಿತಿ ಸೇರಿಸಿ",
    "Add a recurring schedule": "ಪುನರಾವರ್ತಿತ ವೇಳಾಪಟ್ಟಿ ಸೇರಿಸಿ",
    "Add a sample contact": "ಮಾದರಿ ಸಂಪರ್ಕ ಸೇರಿಸಿ",
    "Adding a trusted contact normally waits out a delay. In this tutorial it's instant.": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ ಸೇರಿಸುವುದು ಸಾಮಾನ್ಯವಾಗಿ ಕಾಯುವಿಕೆ ಮುಗಿಯಬೇಕು. ಈ ಟ್ಯುಟೋರಿಯಲ್‌ನಲ್ಲಿ ಅದು ತಕ್ಷಣ.",
    "Alex (sample)": "ಅಲೆಕ್ಸ್ (ಮಾದರಿ)",
    "Now a schedule. Tap ‘Add a recurring schedule’, pick a time window and some apps, then queue it.": "ಈಗ ವೇಳಾಪಟ್ಟಿ. \"ಪುನರಾವರ್ತಿತ ವೇಳಾಪಟ್ಟಿ ಸೇರಿಸಿ\" ಟ್ಯಾಪ್ ಮಾಡಿ, ಸಮಯದ ಅವಧಿ ಮತ್ತು ಕೆಲವು ಆ್ಯಪ್‌ಗಳನ್ನು ಆರಿಸಿ, ನಂತರ ಸರದಿಯಲ್ಲಿಡಿ.",
    "Two changes are waiting, and you can't wait them out. Tap Select, choose both, Apply — then use the password override. The password is: test": "ಎರಡು ಬದಲಾವಣೆಗಳು ಕಾಯುತ್ತಿವೆ, ಮತ್ತು ನೀವು ಕಾಯಲಾಗದು. ಆರಿಸಿ ಟ್ಯಾಪ್ ಮಾಡಿ, ಎರಡನ್ನೂ ಆರಿಸಿ, ಅನ್ವಯಿಸಿ — ನಂತರ ಪಾಸ್‌ವರ್ಡ್ ಒಪ್ಪಿಗೆ ಬಳಸಿ. ಪಾಸ್‌ವರ್ಡ್: test",
    "Open Calendar to see everything laid out by day.": "ದಿನದ ಪ್ರಕಾರ ಎಲ್ಲವನ್ನೂ ನೋಡಲು ಕ್ಯಾಲೆಂಡರ್ ತೆರೆಯಿರಿ.",
    "Now tidy up: remove the recurring schedule here, and the limit over in Limits.": "ಈಗ ಸ್ವಚ್ಛಗೊಳಿಸಿ: ಇಲ್ಲಿ ಪುನರಾವರ್ತಿತ ವೇಳಾಪಟ್ಟಿ ತೆಗೆಯಿರಿ, ಮತ್ತು ಮಿತಿ ಅಲ್ಲಿ ಮಿತಿಗಳಲ್ಲಿ.",
    "Now tidy up: open Recurring and remove the schedule you made.": "ಈಗ ಸ್ವಚ್ಛಗೊಳಿಸಿ: ಪುನರಾವರ್ತಿತ ತೆರೆದು ನೀವು ಮಾಡಿದ ವೇಳಾಪಟ್ಟಿ ತೆಗೆಯಿರಿ.",
    "And the limit: tap it, then Remove this limit.": "ಮತ್ತು ಮಿತಿ: ಅದನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ, ನಂತರ ಈ ಮಿತಿ ತೆಗೆಯಿರಿ.",
    "Let's add a backup approver. Open Rules → Overrides → Trusted contacts and add a sample contact.": "ಬ್ಯಾಕಪ್ ಒಪ್ಪುವವರನ್ನು ಸೇರಿಸೋಣ. ನಿಯಮಗಳು → ಒಪ್ಪಿಗೆಗಳು → ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕಗಳು ತೆರೆದು ಮಾದರಿ ಸಂಪರ್ಕ ಸೇರಿಸಿ.",
    "Home delays": "ಮುಖಪುಟ ಕಾಯುವಿಕೆಗಳು",
    "Home overrides": "ಮುಖಪುಟ ಒಪ್ಪಿಗೆಗಳು",
    "shown": "ತೋರಿಸಲಾಗಿದೆ",
    "hidden": "ಮರೆಮಾಡಲಾಗಿದೆ",
    "Rules": "ನಿಯಮಗಳು",
    "Current overrides": "ಈಗಿನ ಒಪ್ಪಿಗೆಗಳು",
    "No overrides on": "ಯಾವ ಒಪ್ಪಿಗೆಯೂ ಆನ್ ಇಲ್ಲ",
    "Code": "ಕೋಡ್",
    "Name (optional)": "ಹೆಸರು (ಐಚ್ಛಿಕ)",
    "Unnamed": "ಹೆಸರಿಲ್ಲದ",
    "Waiting for them to enter their code.": "ಅವರು ತಮ್ಮ ಕೋಡ್ ನಮೂದಿಸಲು ಕಾಯಲಾಗುತ್ತಿದೆ.",
    "Added as a trusted contact": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವಾಗಿ ಸೇರಿಸಲಾಗಿದೆ",
    "Add as trusted contact": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವಾಗಿ ಸೇರಿಸಿ",
    "They get a request to accept right away. They can approve for you once the wait ends.": "ಅವರಿಗೆ ತಕ್ಷಣ ಸ್ವೀಕರಿಸಲು ವಿನಂತಿ ಹೋಗುತ್ತದೆ. ಕಾಯುವಿಕೆ ಮುಗಿದ ನಂತರ ಅವರು ನಿಮಗಾಗಿ ಒಪ್ಪಬಹುದು.",
    "Removing yourself tells them and stops their requests.": "ನಿಮ್ಮನ್ನು ತೆಗೆದುಕೊಂಡರೆ ಅವರಿಗೆ ತಿಳಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಅವರ ವಿನಂತಿಗಳು ನಿಲ್ಲುತ್ತವೆ.",
    "That's your own code.": "ಅದು ನಿಮ್ಮದೇ ಕೋಡ್.",
    "These people have you as a trusted contact. Tap one to see their details or add them back. Removing yourself tells them and stops their requests.": "ಈ ಜನರು ನಿಮ್ಮನ್ನು ತಮ್ಮ ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕವಾಗಿ ಹೊಂದಿದ್ದಾರೆ. ವಿವರ ನೋಡಲು ಅಥವಾ ಮತ್ತೆ ಸೇರಿಸಲು ಒಬ್ಬರನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ. ನಿಮ್ಮನ್ನು ತೆಗೆದುಕೊಂಡರೆ ಅವರಿಗೆ ತಿಳಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಅವರ ವಿನಂತಿಗಳು ನಿಲ್ಲುತ್ತವೆ.",
    "Confirmed": "ದೃಢೀಕರಿಸಲಾಗಿದೆ",
    "Send confirmation code": "ದೃಢೀಕರಣ ಕೋಡ್ ಕಳುಹಿಸಿ",
    "Resend code": "ಕೋಡ್ ಮತ್ತೆ ಕಳುಹಿಸಿ",
    "Confirm contact": "ಸಂಪರ್ಕ ದೃಢೀಕರಿಸಿ",
    "We email a code to this address. Your contact gives you the code, you enter it here, and then they can approve for you. Until then they can't.": "ಈ ವಿಳಾಸಕ್ಕೆ ನಾವು ಕೋಡ್ ಇಮೇಲ್ ಮಾಡುತ್ತೇವೆ. ನಿಮ್ಮ ಸಂಪರ್ಕ ನಿಮಗೆ ಕೋಡ್ ಕೊಡುತ್ತಾರೆ, ನೀವು ಇಲ್ಲಿ ನಮೂದಿಸುತ್ತೀರಿ, ನಂತರ ಅವರು ನಿಮಗಾಗಿ ಒಪ್ಪಬಹುದು. ಅಲ್ಲಿಯವರೆಗೆ ಸಾಧ್ಯವಿಲ್ಲ.",
    "Code sent. Ask your contact for it.": "ಕೋಡ್ ಕಳುಹಿಸಲಾಗಿದೆ. ನಿಮ್ಮ ಸಂಪರ್ಕದಿಂದ ಕೇಳಿ.",
    "Daily email limit reached. Try again later.": "ದೈನಂದಿನ ಇಮೇಲ್ ಮಿತಿ ತಲುಪಿದೆ. ನಂತರ ಪ್ರಯತ್ನಿಸಿ.",
    "You've sent too many codes today. Try again tomorrow.": "ಇಂದು ತುಂಬಾ ಕೋಡ್‌ಗಳನ್ನು ಕಳುಹಿಸಿದ್ದೀರಿ. ನಾಳೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Couldn't send the code. Check your connection and try again.": "ಕೋಡ್ ಕಳುಹಿಸಲಾಗಲಿಲ್ಲ. ನಿಮ್ಮ ಸಂಪರ್ಕ ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "That code didn't match. Double-check and try again.": "ಆ ಕೋಡ್ ಹೊಂದಿಕೆಯಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪರಿಶೀಲಿಸಿ ಪ್ರಯತ್ನಿಸಿ.",
    "Elementary": "ಪ್ರಾಥಮಿಕ",
    "Middle school": "ಮಾಧ್ಯಮಿಕ",
    "High school": "ಪ್ರೌಢ",
    "Very easy": "ತುಂಬಾ ಸುಲಭ",
    "Your change is ready": "ನಿಮ್ಮ ಬದಲಾವಣೆ ಸಿದ್ಧ",
    "Your limits have reset": "ನಿಮ್ಮ ಮಿತಿಗಳು ರೀಸೆಟ್ ಆಗಿವೆ",
    "If any apps still look blocked, open Demora to refresh them.": "ಯಾವುದಾದರೂ ಆ್ಯಪ್ ಇನ್ನೂ ಬ್ಲಾಕ್ ಆಗಿ ಕಂಡರೆ, ಅವನ್ನು ರಿಫ್ರೆಶ್ ಮಾಡಲು Demora ತೆರೆಯಿರಿ.",
    "If you denied access, turn on Screen Time for Demora in Settings, then come back.": "ನೀವು ಪ್ರವೇಶ ನಿರಾಕರಿಸಿದ್ದರೆ, ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ Demora ಗೆ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಆನ್ ಮಾಡಿ, ನಂತರ ಹಿಂದಿರುಗಿ.",
    "Open Settings": "ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ತೆರೆಯಿರಿ",
    "Couldn't check the code — check your connection and try again.": "ಕೋಡ್ ಪರಿಶೀಲಿಸಲಾಗಲಿಲ್ಲ — ನಿಮ್ಮ ಸಂಪರ್ಕ ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Couldn't send your response — check your connection and try again.": "ನಿಮ್ಮ ಪ್ರತಿಕ್ರಿಯೆ ಕಳುಹಿಸಲಾಗಲಿಲ್ಲ — ನಿಮ್ಮ ಸಂಪರ್ಕ ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Those changes are still counting down. Wait them out, or turn on an override in Settings → Rules → Overrides to skip the wait.": "ಆ ಬದಲಾವಣೆಗಳು ಇನ್ನೂ ಕೌಂಟ್‌ಡೌನ್‌ನಲ್ಲಿವೆ. ಕಾಯಿರಿ, ಅಥವಾ ಕಾಯುವಿಕೆ ಬಿಡಲು ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ನಿಯಮಗಳು → ಒಪ್ಪಿಗೆಗಳಲ್ಲಿ ಒಪ್ಪಿಗೆ ಆನ್ ಮಾಡಿ.",
    "Heads up": "ಗಮನಿಸಿ",
    "Feature roadmap": "ಸೌಲಭ್ಯ ಮಾರ್ಗಸೂಚಿ",
    "links to Trello": "Trello ಗೆ ಲಿಂಕ್‌ಗಳು",
    "Safety code": "ಸುರಕ್ಷತಾ ಕೋಡ್",
    "Mark as verified": "ದೃಢೀಕೃತ ಎಂದು ಗುರುತಿಸಿ",
    "Verified": "ದೃಢೀಕೃತ",
    "Security": "ಭದ್ರತೆ",
    "Available once you've both added each other.": "ನೀವಿಬ್ಬರೂ ಪರಸ್ಪರ ಸೇರಿಸಿದ ನಂತರ ಲಭ್ಯ.",
    "Compare this code with your contact in person or on a call. If it matches on both phones, no one has tampered with the connection.": "ಈ ಕೋಡ್ ಅನ್ನು ನಿಮ್ಮ ಸಂಪರ್ಕದೊಂದಿಗೆ ಮುಖತಃ ಅಥವಾ ಕರೆಯಲ್ಲಿ ಹೋಲಿಸಿ. ಎರಡೂ ಫೋನ್‌ಗಳಲ್ಲಿ ಹೊಂದಿದರೆ, ಸಂಪರ್ಕದಲ್ಲಿ ಯಾರೂ ಕೈಹಾಕಿಲ್ಲ.",
    "Background blocking may be incomplete": "ಹಿನ್ನೆಲೆ ಬ್ಲಾಕ್ ಅಪೂರ್ಣವಾಗಿರಬಹುದು",
    "iOS limits how many limits and schedules can run in the background at once. Removing a few restores full enforcement.": "ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಒಂದೇ ಸಮಯದಲ್ಲಿ ಎಷ್ಟು ಮಿತಿಗಳು ಮತ್ತು ವೇಳಾಪಟ್ಟಿಗಳು ನಡೆಯಬಹುದು ಎಂಬುದನ್ನು iOS ಮಿತಿಗೊಳಿಸುತ್ತದೆ. ಕೆಲವನ್ನು ತೆಗೆದರೆ ಪೂರ್ಣ ಜಾರಿ ಮರಳುತ್ತದೆ.",
    "College": "ಕಾಲೇಜು",
    "Nothing — just a new problem": "ಏನೂ ಇಲ್ಲ — ಹೊಸ ಸಮಸ್ಯೆ ಮಾತ್ರ",
    "Lose one correct answer": "ಒಂದು ಸರಿ ಉತ್ತರ ಕಳೆದುಕೊಳ್ಳಿ",
    "Restart from zero": "ಶೂನ್ಯದಿಂದ ಮತ್ತೆ ಆರಂಭಿಸಿ",
    "Enable math override (%@, %d problems)": "ಗಣಿತ ಒಪ್ಪಿಗೆ ಸಕ್ರಿಯಗೊಳಿಸಿ (%@, %d ಸಮಸ್ಯೆಗಳು)",
    "Solve for x:  (x − %d) × %d = %d": "x ಗೆ ಬಿಡಿಸಿ:  (x − %d) × %d = %d",
    "Avatar": "ಅವತಾರ್",
    "Icon": "ಐಕಾನ್",
    "Photo": "ಫೋಟೋ",
    "Type one emoji": "ಒಂದು ಎಮೋಜಿ ಟೈಪ್ ಮಾಡಿ",
    "Choose a photo": "ಫೋಟೋ ಆರಿಸಿ",
    "Change photo": "ಫೋಟೋ ಬದಲಿಸಿ",
    "Remove photo": "ಫೋಟೋ ತೆಗೆಯಿರಿ",
    "Demora %@": "Demora %@",
    "Blocked user": "ಬ್ಲಾಕ್ ಮಾಡಿದ ಬಳಕೆದಾರ",
    "Two removals are pending. Tap Select, choose both, Apply — then approve with your trusted contact instead of the password.": "ಎರಡು ತೆಗೆಯುವಿಕೆಗಳು ಬಾಕಿ ಇವೆ. ಆರಿಸಿ ಟ್ಯಾಪ್ ಮಾಡಿ, ಎರಡನ್ನೂ ಆರಿಸಿ, ಅನ್ವಯಿಸಿ — ನಂತರ ಪಾಸ್‌ವರ್ಡ್ ಬದಲು ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕದಿಂದ ಒಪ್ಪಿಸಿ.",
    "Waiting for approval…": "ಒಪ್ಪಿಗೆಗಾಗಿ ಕಾಯಲಾಗುತ್ತಿದೆ…",
    "%d changes: %@": "%d ಬದಲಾವಣೆಗಳು: %@",
    "Awaiting approval": "ಒಪ್ಪಿಗೆಗಾಗಿ ಕಾಯುತ್ತಿದೆ",
    "Tap to enter the email code": "ಇಮೇಲ್ ಕೋಡ್ ನಮೂದಿಸಲು ಟ್ಯಾಪ್ ಮಾಡಿ",
    "Encrypted request — re-add this contact to read it.": "ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ ವಿನಂತಿ — ಓದಲು ಈ ಸಂಪರ್ಕವನ್ನು ಮತ್ತೆ ಸೇರಿಸಿ.",
    "Privacy Policy": "ಗೌಪ್ಯತಾ ನೀತಿ",
    "Terms of Use": "ಬಳಕೆಯ ನಿಯಮಗಳು",
    "Almost done": "ಬಹುತೇಕ ಮುಗಿಯಿತು",
    "Nice work — that's the whole loop. Now set the delays and overrides that will actually protect you.": "ಚೆನ್ನಾಗಿದೆ — ಇದೇ ಇಡೀ ಚಕ್ರ. ಈಗ ನಿಜವಾಗಿ ನಿಮ್ಮನ್ನು ರಕ್ಷಿಸುವ ಕಾಯುವಿಕೆಗಳು ಮತ್ತು ಒಪ್ಪಿಗೆಗಳನ್ನು ಹೊಂದಿಸಿ.",
    "Finish setup": "ಸೆಟಪ್ ಮುಗಿಸಿ",
    "Tap ‘Add your first limit’, choose an app or two and a daily budget, then queue the change.": "\"ನಿಮ್ಮ ಮೊದಲ ಮಿತಿ ಸೇರಿಸಿ\" ಟ್ಯಾಪ್ ಮಾಡಿ, ಒಂದೆರಡು ಆ್ಯಪ್‌ಗಳು ಮತ್ತು ದೈನಂದಿನ ಬಜೆಟ್ ಆರಿಸಿ, ನಂತರ ಬದಲಾವಣೆಯನ್ನು ಸರದಿಯಲ್ಲಿಡಿ.",
    "Your change is waiting out its delay — and you can't wait this one out. Tap ‘Apply now…’ and use the password override. The password is: test": "ನಿಮ್ಮ ಬದಲಾವಣೆ ಕಾಯುವಿಕೆಯಲ್ಲಿದೆ — ಇದನ್ನು ನೀವು ಕಾಯಲಾಗದು. \"ಈಗ ಅನ್ವಯಿಸಿ…\" ಟ್ಯಾಪ್ ಮಾಡಿ ಪಾಸ್‌ವರ್ಡ್ ಒಪ್ಪಿಗೆ ಬಳಸಿ. ಪಾಸ್‌ವರ್ಡ್: test",
    "Now remove it: tap the limit, then ‘Remove this limit’.": "ಈಗ ಅದನ್ನು ತೆಗೆಯಿರಿ: ಮಿತಿಯನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ, ನಂತರ \"ಈ ಮಿತಿ ತೆಗೆಯಿರಿ\".",
    "Same again — tap ‘Apply now…’ and enter the password (test).": "ಮತ್ತೊಮ್ಮೆ ಹಾಗೇ — \"ಈಗ ಅನ್ವಯಿಸಿ…\" ಟ್ಯಾಪ್ ಮಾಡಿ ಪಾಸ್‌ವರ್ಡ್ (test) ನಮೂದಿಸಿ.",
    "For this tutorial, only the password works. The password is: test": "ಈ ಟ್ಯುಟೋರಿಯಲ್‌ನಲ್ಲಿ ಪಾಸ್‌ವರ್ಡ್ ಮಾತ್ರ ಕೆಲಸ ಮಾಡುತ್ತದೆ. ಪಾಸ್‌ವರ್ಡ್: test",
    "Everything here is just a sample — nothing is saved and nothing is actually blocked. It's only to show how the app works.": "ಇಲ್ಲಿರುವುದೆಲ್ಲ ಕೇವಲ ಮಾದರಿ — ಏನೂ ಉಳಿಯುವುದಿಲ್ಲ, ಏನೂ ಬ್ಲಾಕ್ ಆಗುವುದಿಲ್ಲ. ಆ್ಯಪ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ ಎಂದು ತೋರಿಸಲು ಮಾತ್ರ.",
    "Applying…": "ಅನ್ವಯಿಸಲಾಗುತ್ತಿದೆ…",
