    "Blocked by Demora": "Demora ದಿಂದ ಬ್ಲಾಕ್ ಆಗಿದೆ",
    "Blocking is enforced by iOS itself through Screen Time, the same system parental controls use.": "ಬ್ಲಾಕ್ ಮಾಡುವುದನ್ನು iOS ಸ್ವತಃ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಮೂಲಕ ಜಾರಿಗೊಳಿಸುತ್ತದೆ, ಪೋಷಕ ನಿಯಂತ್ರಣಗಳು ಬಳಸುವ ಅದೇ ವ್ಯವಸ್ಥೆ.",
    "Cancel": "ರದ್ದುಮಾಡಿ",
    "Change %@ to %d min/day": "%@ ಅನ್ನು ದಿನಕ್ಕೆ %d ನಿಮಿಷಕ್ಕೆ ಬದಲಿಸಿ",
    "Changes that make things LESS STRICT (raise a limit, remove a block, add a free period) wait out your second delay — usually set longer.": "ವಿಷಯಗಳನ್ನು ಕಡಿಮೆ ಕಠಿಣಗೊಳಿಸುವ ಬದಲಾವಣೆಗಳು (ಮಿತಿ ಹೆಚ್ಚಿಸುವುದು, ಬ್ಲಾಕ್ ತೆಗೆಯುವುದು, ಮುಕ್ತ ಅವಧಿ ಸೇರಿಸುವುದು) ನಿಮ್ಮ ಎರಡನೇ ಕಾಯುವಿಕೆಯನ್ನು ಮುಗಿಸಬೇಕು — ಸಾಮಾನ್ಯವಾಗಿ ಹೆಚ್ಚು ಉದ್ದ.",
    "Changes that make things STRICTER (add a limit, lower minutes, add a schedule) wait out your first delay.": "ವಿಷಯಗಳನ್ನು ಹೆಚ್ಚು ಕಠಿಣಗೊಳಿಸುವ ಬದಲಾವಣೆಗಳು (ಮಿತಿ ಸೇರಿಸುವುದು, ನಿಮಿಷ ಕಡಿಮೆ ಮಾಡುವುದು, ವೇಳಾಪಟ್ಟಿ ಸೇರಿಸುವುದು) ನಿಮ್ಮ ಮೊದಲ ಕಾಯುವಿಕೆಯನ್ನು ಮುಗಿಸಬೇಕು.",
    "Changes you make will appear here with a countdown.": "ನೀವು ಮಾಡುವ ಬದಲಾವಣೆಗಳು ಕೌಂಟ್‌ಡೌನ್‌ನೊಂದಿಗೆ ಇಲ್ಲಿ ಕಾಣುತ್ತವೆ.",
    "Choose apps": "ಆ್ಯಪ್‌ಗಳನ್ನು ಆರಿಸಿ",
