    "Couldn't submit — make sure you're signed into iCloud and try again.": "ಸಲ್ಲಿಸಲಾಗಲಿಲ್ಲ — iCloud ಗೆ ಸೈನ್ ಇನ್ ಆಗಿದ್ದೀರಿ ಎಂದು ಖಚಿತಪಡಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
