    "Done": "ಮುಗಿಯಿತು",
    "Duration": "ಅವಧಿ",
    "During a free period, limits don't block and usage inside the window doesn't count toward them — time used before the window still does.": "ಮುಕ್ತ ಅವಧಿಯಲ್ಲಿ ಮಿತಿಗಳು ಬ್ಲಾಕ್ ಮಾಡುವುದಿಲ್ಲ, ಮತ್ತು ಅವಧಿಯೊಳಗಿನ ಬಳಕೆ ಅವುಗಳಿಗೆ ಎಣಿಕೆಯಾಗುವುದಿಲ್ಲ — ಅವಧಿಗೆ ಮೊದಲು ಬಳಸಿದ ಸಮಯ ಇನ್ನೂ ಎಣಿಕೆಯಾಗುತ್ತದೆ.",
