    "Enable/update password override": "ಪಾಸ್‌ವರ್ಡ್ ಒಪ್ಪಿಗೆ ಸಕ್ರಿಯಗೊಳಿಸಿ/ಅಪ್‌ಡೇಟ್ ಮಾಡಿ",
