    "End session early: %@": "ಸೆಷನ್ ಬೇಗ ಮುಗಿಸಿ: %@",
    "Ends": "ಮುಗಿಯುತ್ತದೆ",
    "Enter password": "ಪಾಸ್‌ವರ್ಡ್ ನಮೂದಿಸಿ",
    "Every change you make waits out a delay you chose, counting down in the background. You can always change your rules — just not in a moment of weakness.": "ನೀವು ಮಾಡುವ ಪ್ರತಿ ಬದಲಾವಣೆ ನೀವು ಆರಿಸಿದ ಕಾಯುವಿಕೆಯನ್ನು ಮುಗಿಸುತ್ತದೆ, ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಎಣಿಸುತ್ತಾ. ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ಯಾವಾಗಲೂ ಬದಲಿಸಬಹುದು — ದುರ್ಬಲ ಕ್ಷಣದಲ್ಲಿ ಅಲ್ಲ.",
    "Every day": "ಪ್ರತಿ ದಿನ",
    "Everything on the iPhone is blocked during the window except the apps picked here.": "ಅವಧಿಯಲ್ಲಿ ಇಲ್ಲಿ ಆರಿಸಿದ ಆ್ಯಪ್‌ಗಳನ್ನು ಬಿಟ್ಟು iPhone ನ ಎಲ್ಲವೂ ಬ್ಲಾಕ್ ಆಗುತ್ತದೆ.",
    "Free period": "ಮುಕ್ತ ಅವಧಿ",
    "Today's usage is reported by iOS Screen Time, which can be slow to load or briefly show nothing. If it looks empty, tap the refresh arrow a couple of times.": "ಇಂದಿನ ಬಳಕೆಯನ್ನು iOS ಸ್ಕ್ರೀನ್ ಟೈಮ್ ವರದಿ ಮಾಡುತ್ತದೆ; ಅದು ಲೋಡ್ ಆಗಲು ನಿಧಾನವಾಗಬಹುದು ಅಥವಾ ಕ್ಷಣಕಾಲ ಖಾಲಿ ತೋರಬಹುದು. ಖಾಲಿ ಕಂಡರೆ ರಿಫ್ರೆಶ್ ಬಾಣವನ್ನು ಒಂದೆರಡು ಬಾರಿ ಟ್ಯಾಪ್ ಮಾಡಿ.",
    "Free": "ಮುಕ್ತ",
    "Free period: %@ (%d min)": "ಮುಕ್ತ ಅವಧಿ: %@ (%d ನಿಮಿ)",
    "Free period — nothing is blocked": "ಮುಕ್ತ ಅವಧಿ — ಏನೂ ಬ್ಲಾಕ್ ಆಗಿಲ್ಲ",
    "Temporarily lifts everything — no app blocks apply, and usage during the free period doesn't count toward your limits.": "ಎಲ್ಲವನ್ನೂ ತಾತ್ಕಾಲಿಕವಾಗಿ ಎತ್ತುತ್ತದೆ — ಯಾವ ಆ್ಯಪ್ ಬ್ಲಾಕ್ ಇಲ್ಲ, ಮತ್ತು ಮುಕ್ತ ಅವಧಿಯ ಬಳಕೆ ನಿಮ್ಮ ಮಿತಿಗಳಿಗೆ ಎಣಿಕೆಯಾಗುವುದಿಲ್ಲ.",
    "Free periods": "ಮುಕ್ತ ಅವಧಿಗಳು",
    "Friction, not passwords": "ಪಾಸ್‌ವರ್ಡ್ ಅಲ್ಲ, ಅಡಚಣೆ",
    "Get started": "ಆರಂಭಿಸಿ",
