    "Language": "ಭಾಷೆ",
    "Demora needs Screen Time authorization to set app limits and block apps. iOS will ask for your confirmation.": "ಆ್ಯಪ್ ಮಿತಿಗಳನ್ನು ಹೊಂದಿಸಲು ಮತ್ತು ಆ್ಯಪ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡಲು Demora ಗೆ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಅಧಿಕಾರ ಬೇಕು. iOS ನಿಮ್ಮ ದೃಢೀಕರಣ ಕೇಳುತ್ತದೆ.",
    "Demora wouldn't exist without the people who tested it, broke it, and told me about it. Thank you. ❤️": "ಪರೀಕ್ಷಿಸಿ, ಮುರಿದು, ನನಗೆ ತಿಳಿಸಿದ ಜನರಿಲ್ಲದೆ Demora ಇರುತ್ತಿರಲಿಲ್ಲ. ಧನ್ಯವಾದಗಳು. ❤️",
    "Less strict": "ಕಡಿಮೆ ಕಠಿಣ",
    "Less-strict delay": "ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆ",
    "Limit": "ಮಿತಿ",
    "Limits": "ಮಿತಿಗಳು",
    "Limits won't block and usage won't count during this window.": "ಈ ಅವಧಿಯಲ್ಲಿ ಮಿತಿಗಳು ಬ್ಲಾಕ್ ಮಾಡುವುದಿಲ್ಲ ಮತ್ತು ಬಳಕೆ ಎಣಿಕೆಯಾಗುವುದಿಲ್ಲ.",
    "Limits: daily time budgets per app. When the minutes run out, the app is blocked until midnight.": "ಮಿತಿಗಳು: ಪ್ರತಿ ಆ್ಯಪ್‌ಗೆ ದೈನಂದಿನ ಸಮಯ ಬಜೆಟ್. ನಿಮಿಷಗಳು ಮುಗಿದಾಗ ಮಧ್ಯರಾತ್ರಿಯವರೆಗೆ ಆ್ಯಪ್ ಬ್ಲಾಕ್ ಆಗುತ್ತದೆ.",
    "Looser changes": "ಸಡಿಲ ಬದಲಾವಣೆಗಳು",
    "Looser changes wait %@": "ಸಡಿಲ ಬದಲಾವಣೆಗಳು %@ ಕಾಯುತ್ತವೆ",
    "Math problems": "ಗಣಿತ ಸಮಸ್ಯೆಗಳು",
    "Medium": "ಮಧ್ಯಮ",
    "Minutes": "ನಿಮಿಷಗಳು",
    "Mode": "ಮೋಡ್",
    "Monthly schedules can't cross midnight — set the end time after the start time.": "ಮಾಸಿಕ ವೇಳಾಪಟ್ಟಿಗಳು ಮಧ್ಯರಾತ್ರಿ ದಾಟಲಾಗದು — ಅಂತ್ಯ ಸಮಯವನ್ನು ಆರಂಭದ ನಂತರ ಇಡಿ.",
    "More strict": "ಹೆಚ್ಚು ಕಠಿಣ",
    "More-strict delay": "ಹೆಚ್ಚು-ಕಠಿಣ ಕಾಯುವಿಕೆ",
    "Most screen-time apps protect your rules with a password — which you know, so you cave. Demora protects them with time instead.": "ಹೆಚ್ಚಿನ ಸ್ಕ್ರೀನ್-ಟೈಮ್ ಆ್ಯಪ್‌ಗಳು ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ಪಾಸ್‌ವರ್ಡ್‌ನಿಂದ ರಕ್ಷಿಸುತ್ತವೆ — ಅದು ನಿಮಗೆ ಗೊತ್ತಿರುವುದರಿಂದ ನೀವು ಮಣಿಯುತ್ತೀರಿ. Demora ಅವನ್ನು ಸಮಯದಿಂದ ರಕ್ಷಿಸುತ್ತದೆ.",
    "Name": "ಹೆಸರು",
    "Names will appear here soon.": "ಹೆಸರುಗಳು ಶೀಘ್ರದಲ್ಲಿ ಇಲ್ಲಿ ಕಾಣುತ್ತವೆ.",
    "New free period": "ಹೊಸ ಮುಕ್ತ ಅವಧಿ",
