    "OK": "OK",
    "Off": "ಆಫ್",
    "On": "ಆನ್",
    "One-off and unplanned, but still delay-gated. A block session waits %@; an unblock session waits %@. Ending early flips the rule (or use an override).": "ಒಂದು ಬಾರಿ ಮತ್ತು ಯೋಜಿಸದ್ದು, ಆದರೂ ಕಾಯುವಿಕೆಗೆ ಒಳಪಡುತ್ತದೆ. ಬ್ಲಾಕ್ ಸೆಷನ್ %@ ಕಾಯುತ್ತದೆ; ಅನ್‌ಬ್ಲಾಕ್ ಸೆಷನ್ %@ ಕಾಯುತ್ತದೆ. ಬೇಗ ಮುಗಿಸುವುದು ನಿಯಮವನ್ನು ತಿರುಗಿಸುತ್ತದೆ (ಅಥವಾ ಒಪ್ಪಿಗೆ ಬಳಸಿ).",
    "Only the apps picked here are blocked during the window.": "ಅವಧಿಯಲ್ಲಿ ಇಲ್ಲಿ ಆರಿಸಿದ ಆ್ಯಪ್‌ಗಳು ಮಾತ್ರ ಬ್ಲಾಕ್ ಆಗುತ್ತವೆ.",
    "Overrides": "ಒಪ್ಪಿಗೆಗಳು",
    "Overrides enabled": "ಒಪ್ಪಿಗೆಗಳು ಸಕ್ರಿಯ",
    "Overrides let you skip a pending change's countdown. They're off by default. Adding one later counts as a less-strict change; removing one counts as stricter — both go through delays.": "ಒಪ್ಪಿಗೆಗಳು ಬಾಕಿ ಬದಲಾವಣೆಯ ಕೌಂಟ್‌ಡೌನ್ ಬಿಡಲು ಅವಕಾಶ ನೀಡುತ್ತವೆ. ಅವು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಆಫ್. ನಂತರ ಒಂದನ್ನು ಸೇರಿಸುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ; ತೆಗೆಯುವುದು ಹೆಚ್ಚು ಕಠಿಣ — ಎರಡೂ ಕಾಯುವಿಕೆಗಳ ಮೂಲಕ ಹೋಗುತ್ತವೆ.",
    "Overrides skip a pending change's countdown. Enabling or weakening one is a less-strict change; disabling or strengthening one is stricter. All edits here go through the matching delay.": "ಒಪ್ಪಿಗೆಗಳು ಬಾಕಿ ಬದಲಾವಣೆಯ ಕೌಂಟ್‌ಡೌನ್ ಬಿಡುತ್ತವೆ. ಒಂದನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದು ಅಥವಾ ದುರ್ಬಲಗೊಳಿಸುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆ; ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದು ಅಥವಾ ಬಲಪಡಿಸುವುದು ಹೆಚ್ಚು ಕಠಿಣ. ಇಲ್ಲಿನ ಎಲ್ಲ ಬದಲಾವಣೆಗಳು ಅನುಗುಣವಾದ ಕಾಯುವಿಕೆಯ ಮೂಲಕ ಹೋಗುತ್ತವೆ.",
    "A change for this setting is already pending. Cancel it on the Home tab first if you want something different.": "ಈ ಸೆಟ್ಟಿಂಗ್‌ನ ಬದಲಾವಣೆ ಈಗಾಗಲೇ ಬಾಕಿ ಇದೆ. ಬೇರೆ ಬೇಕಿದ್ದರೆ ಮೊದಲು ಅದನ್ನು ಮುಖಪುಟ ಟ್ಯಾಬ್‌ನಲ್ಲಿ ರದ್ದುಮಾಡಿ.",
    "Already pending": "ಈಗಾಗಲೇ ಬಾಕಿ",
