    "%@ — Note: %@": "%@ — ಟಿಪ್ಪಣಿ: %@",
    "Cancels this request and lets you pick contacts again.": "ಈ ವಿನಂತಿಯನ್ನು ರದ್ದುಮಾಡಿ ಸಂಪರ್ಕಗಳನ್ನು ಮತ್ತೆ ಆರಿಸಲು ಬಿಡುತ್ತದೆ.",
