    "an iPhone app that protects your screen-time rules with definition 1 instead of a password.": "ಪಾಸ್‌ವರ್ಡ್ ಬದಲು ವ್ಯಾಖ್ಯೆ 1 ರಿಂದ ನಿಮ್ಮ ಸ್ಕ್ರೀನ್-ಟೈಮ್ ನಿಯಮಗಳನ್ನು ರಕ್ಷಿಸುವ iPhone ಆ್ಯಪ್.",
