    "Pending changes show on the Home tab with a live countdown. You can cancel them anytime before they apply.": "ಬಾಕಿ ಬದಲಾವಣೆಗಳು ಮುಖಪುಟ ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಲೈವ್ ಕೌಂಟ್‌ಡೌನ್‌ನೊಂದಿಗೆ ಕಾಣುತ್ತವೆ. ಅವು ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ಯಾವಾಗ ಬೇಕಾದರೂ ರದ್ದುಮಾಡಬಹುದು.",
    "Plan %@: %@ (%@)": "ಯೋಜಿಸಿ %@: %@ (%@)",
