    "Plan ahead for specific dates — a trip, a weekend, an exam. Doesn't repeat. Planning a block is stricter; planning a free period is less strict.": "ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕಗಳಿಗೆ ಮೊದಲೇ ಯೋಜಿಸಿ — ಪ್ರವಾಸ, ವಾರಾಂತ್ಯ, ಪರೀಕ್ಷೆ. ಪುನರಾವರ್ತಿಸುವುದಿಲ್ಲ. ಬ್ಲಾಕ್ ಯೋಜಿಸುವುದು ಹೆಚ್ಚು ಕಠಿಣ; ಮುಕ್ತ ಅವಧಿ ಯೋಜಿಸುವುದು ಕಡಿಮೆ ಕಠಿಣ.",
