    "Repeating windows: every day, chosen weekdays, or monthly patterns. Adding waits %@; removing waits %@.": "ಪುನರಾವರ್ತಿಸುವ ಅವಧಿಗಳು: ಪ್ರತಿದಿನ, ಆಯ್ದ ವಾರದ ದಿನಗಳು, ಅಥವಾ ಮಾಸಿಕ ಮಾದರಿ. ಸೇರಿಸುವುದು %@ ಕಾಯುತ್ತದೆ; ತೆಗೆಯುವುದು %@ ಕಾಯುತ್ತದೆ.",
