    "Schedules: recurring or one-off windows that block chosen apps — or everything except a chosen few. Plus free periods where time doesn't count.": "ವೇಳಾಪಟ್ಟಿಗಳು: ಆಯ್ದ ಆ್ಯಪ್‌ಗಳನ್ನು — ಅಥವಾ ಆಯ್ದ ಕೆಲವನ್ನು ಬಿಟ್ಟು ಎಲ್ಲವನ್ನೂ — ಬ್ಲಾಕ್ ಮಾಡುವ ಪುನರಾವರ್ತಿತ ಅಥವಾ ಒಂದು ಬಾರಿಯ ಅವಧಿಗಳು. ಜೊತೆಗೆ ಸಮಯ ಎಣಿಕೆಯಾಗದ ಮುಕ್ತ ಅವಧಿಗಳು.",
