    "Start using Demora": "Demora ಬಳಸಲು ಆರಂಭಿಸಿ",
    "Starts": "ಆರಂಭ",
    "Stricter changes": "ಹೆಚ್ಚು ಕಠಿಣ ಬದಲಾವಣೆಗಳು",
    "Stricter changes wait %@": "ಹೆಚ್ಚು ಕಠಿಣ ಬದಲಾವಣೆಗಳು %@ ಕಾಯುತ್ತವೆ",
    "Temporarily lifts limits, schedules, and block sessions for the chosen apps.": "ಆಯ್ದ ಆ್ಯಪ್‌ಗಳಿಗೆ ಮಿತಿಗಳು, ವೇಳಾಪಟ್ಟಿಗಳು ಮತ್ತು ಬ್ಲಾಕ್ ಸೆಷನ್‌ಗಳನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ಎತ್ತುತ್ತದೆ.",
    "Thanks for testing Demora!": "Demora ಪರೀಕ್ಷಿಸಿದ್ದಕ್ಕೆ ಧನ್ಯವಾದಗಳು!",
    "This app is blocked right now — by a limit, a schedule, or a session. Changing your rules takes a delay; open Demora to queue a change.": "ಈ ಆ್ಯಪ್ ಈಗ ಬ್ಲಾಕ್ ಆಗಿದೆ — ಮಿತಿ, ವೇಳಾಪಟ್ಟಿ ಅಥವಾ ಸೆಷನ್‌ನಿಂದ. ನಿಯಮಗಳನ್ನು ಬದಲಿಸಲು ಕಾಯುವಿಕೆ ಬೇಕು; ಬದಲಾವಣೆ ಸರದಿಯಲ್ಲಿಡಲು Demora ತೆರೆಯಿರಿ.",
    "If it should already be unblocked, iOS is sometimes slow to apply a background change — open Demora for an immediate unblock.": "ಈಗಾಗಲೇ ಅನ್‌ಬ್ಲಾಕ್ ಆಗಬೇಕಿತ್ತು ಎಂದರೆ, iOS ಕೆಲವೊಮ್ಮೆ ಹಿನ್ನೆಲೆ ಬದಲಾವಣೆ ಅನ್ವಯಿಸಲು ನಿಧಾನ — ತಕ್ಷಣ ಅನ್‌ಬ್ಲಾಕ್‌ಗಾಗಿ Demora ತೆರೆಯಿರಿ.",
    "Two delays rule everything": "ಎರಡು ಕಾಯುವಿಕೆಗಳು ಎಲ್ಲವನ್ನೂ ನಡೆಸುತ್ತವೆ",
    "Type": "ಪ್ರಕಾರ",
    "Unblock": "ಅನ್‌ಬ್ಲಾಕ್",
    "Unblock apps": "ಆ್ಯಪ್‌ಗಳನ್ನು ಅನ್‌ಬ್ಲಾಕ್ ಮಾಡಿ",
    "Wait this long before any change that loosens your rules takes effect. Usually set longer than the first.": "ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ಸಡಿಲಿಸುವ ಯಾವುದೇ ಬದಲಾವಣೆ ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ಇಷ್ಟು ಕಾಲ ಕಾಯಿರಿ. ಸಾಮಾನ್ಯವಾಗಿ ಮೊದಲನೆಯದಕ್ಕಿಂತ ಉದ್ದ ಇಡಲಾಗುತ್ತದೆ.",
    "Wait this long before any change that tightens your rules takes effect.": "ನಿಮ್ಮ ನಿಯಮಗಳನ್ನು ಬಿಗಿಗೊಳಿಸುವ ಯಾವುದೇ ಬದಲಾವಣೆ ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ಇಷ್ಟು ಕಾಲ ಕಾಯಿರಿ.",
    "Want your name in the app's beta-tester thanks page? Pick whatever you'd like to be called.": "ಆ್ಯಪ್‌ನ ಬೀಟಾ-ಪರೀಕ್ಷಕರ ಧನ್ಯವಾದ ಪುಟದಲ್ಲಿ ನಿಮ್ಮ ಹೆಸರು ಬೇಕೇ? ನಿಮ್ಮನ್ನು ಏನೆಂದು ಕರೆಯಬೇಕೋ ಅದನ್ನು ಆರಿಸಿ.",
    "Weekday": "ವಾರದ ದಿನ",
    "Weekdays": "ವಾರದ ದಿನಗಳು",
    "What can it do?": "ಇದು ಏನು ಮಾಡಬಲ್ಲದು?",
    "What's in the box": "ಒಳಗೇನಿದೆ",
    "When": "ಯಾವಾಗ",
    "When on, deleting ANY app from this iPhone is blocked — including Demora itself, so blocks can't be bypassed by uninstalling.": "ಆನ್ ಇದ್ದಾಗ, ಈ iPhone ನಿಂದ ಯಾವುದೇ ಆ್ಯಪ್ ಅಳಿಸುವುದು ತಡೆಯಲಾಗುತ್ತದೆ — Demora ಸೇರಿದಂತೆ, ಹಾಗಾಗಿ ಅಳಿಸಿ ಬ್ಲಾಕ್‌ಗಳನ್ನು ತಪ್ಪಿಸಲಾಗದು.",
    "Which one": "ಯಾವುದು",
    "Window": "ಅವಧಿ",
    "Wrong — new problem": "ತಪ್ಪು — ಹೊಸ ಸಮಸ್ಯೆ",
    "You're in! Your name will appear in the beta testers page once it's approved.": "ನೀವು ಸೇರಿದ್ದೀರಿ! ಒಪ್ಪಿಗೆಯಾದ ನಂತರ ನಿಮ್ಮ ಹೆಸರು ಬೀಟಾ ಪರೀಕ್ಷಕರ ಪುಟದಲ್ಲಿ ಕಾಣುತ್ತದೆ.",
    "You're set": "ನೀವು ಸಿದ್ಧ",
    "Your name is in — it'll show up once approved.": "ನಿಮ್ಮ ಹೆಸರು ಸೇರಿದೆ — ಒಪ್ಪಿಗೆಯಾದ ನಂತರ ಕಾಣುತ್ತದೆ.",
    "Your name or nickname": "ನಿಮ್ಮ ಹೆಸರು ಅಥವಾ ಅಡ್ಡಹೆಸರು",
    "e.g. Airport, weekend trip": "ಉದಾ. ವಿಮಾನ ನಿಲ್ದಾಣ, ವಾರಾಂತ್ಯ ಪ್ರವಾಸ",
    "e.g. Bedtime": "ಉದಾ. ಮಲಗುವ ಸಮಯ",
    "e.g. Deep work": "ಉದಾ. ಆಳವಾದ ಕೆಲಸ",
    "e.g. Instagram": "ಉದಾ. Instagram",
    "e.g. Lunch break": "ಉದಾ. ಊಟದ ವಿರಾಮ",
    "free period": "ಮುಕ್ತ ಅವಧಿ",
    "limit": "ಮಿತಿ",
    "now": "ಈಗ",
    "planned window": "ಯೋಜಿತ ಅವಧಿ",
    "schedule": "ವೇಳಾಪಟ್ಟಿ",
    "session": "ಸೆಷನ್",
    // Prevent disabling, walkthrough replay — added after the
    // 2026-07 update (App Attest, ContactCrypto, LatchReport extension).
    "A passcode is saved. Open the guide below to view it.": "ಪಾಸ್‌ಕೋಡ್ ಉಳಿಸಲಾಗಿದೆ. ಅದನ್ನು ನೋಡಲು ಕೆಳಗಿನ ಮಾರ್ಗದರ್ಶಿ ತೆರೆಯಿರಿ.",
    "Can't reach this contact right now — they may have removed Demora or signed out. They won't be able to approve until they're back.": "ಈ ಸಂಪರ್ಕವನ್ನು ಈಗ ತಲುಪಲಾಗುತ್ತಿಲ್ಲ — ಅವರು Demora ತೆಗೆದಿರಬಹುದು ಅಥವಾ ಸೈನ್ ಔಟ್ ಆಗಿರಬಹುದು. ಅವರು ಮರಳುವವರೆಗೆ ಒಪ್ಪಲಾಗದು.",
    "Couldn't start the walkthrough": "ವಾಕ್‌ಥ್ರೂ ಆರಂಭಿಸಲಾಗಲಿಲ್ಲ",
    "Bug tracker": "ದೋಷ ಟ್ರ್ಯಾಕರ್",
    "Demora can't stop you from turning off its Screen Time access in iOS Settings — but a friend can. If Screen Time itself is locked with someone else's passcode, iOS blocks any change to Demora's access, while Demora keeps doing all the blocking.": "iOS ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ Demora ದ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪ್ರವೇಶವನ್ನು ಆಫ್ ಮಾಡುವುದನ್ನು Demora ತಡೆಯಲಾಗದು — ಆದರೆ ಸ್ನೇಹಿತ ತಡೆಯಬಹುದು. ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಬೇರೊಬ್ಬರ ಪಾಸ್‌ಕೋಡ್‌ನಿಂದ ಲಾಕ್ ಆಗಿದ್ದರೆ, Demora ಎಲ್ಲ ಬ್ಲಾಕ್ ಮಾಡುತ್ತಲೇ ಇರುವಾಗ iOS ಅದರ ಪ್ರವೇಶದ ಯಾವುದೇ ಬದಲಾವಣೆಯನ್ನು ತಡೆಯುತ್ತದೆ.",
    "Demora couldn't safely back up your current setup, so the replay was cancelled to protect your limits. Nothing was changed. Please try again in a moment.": "Demora ನಿಮ್ಮ ಈಗಿನ ಸೆಟಪ್ ಅನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಬ್ಯಾಕಪ್ ಮಾಡಲಾಗಲಿಲ್ಲ, ಹಾಗಾಗಿ ನಿಮ್ಮ ಮಿತಿಗಳನ್ನು ರಕ್ಷಿಸಲು ಮರುಪ್ರದರ್ಶನ ರದ್ದಾಯಿತು. ಏನೂ ಬದಲಾಗಿಲ್ಲ. ಸ್ವಲ್ಪ ಸಮಯದ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Done. Now you can't disable Demora's access — or change the passcode — without your friend. To undo it later, your friend enters the passcode and turns it off.": "ಆಯಿತು. ಈಗ ನಿಮ್ಮ ಸ್ನೇಹಿತನ ಸಹಾಯವಿಲ್ಲದೆ Demora ದ ಪ್ರವೇಶ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗದು — ಪಾಸ್‌ಕೋಡ್ ಕೂಡ ಬದಲಿಸಲಾಗದು. ನಂತರ ರದ್ದುಮಾಡಲು, ಸ್ನೇಹಿತ ಪಾಸ್‌ಕೋಡ್ ನಮೂದಿಸಿ ಅದನ್ನು ಆಫ್ ಮಾಡುತ್ತಾರೆ.",
    "Email limit": "ಇಮೇಲ್ ಮಿತಿ",
    "Emoji": "ಎಮೋಜಿ",
    "Friend: save the passcode here so it isn't lost. It's only shown from this page, which is behind your delay.": "ಸ್ನೇಹಿತರೇ: ಕಳೆದುಹೋಗದಂತೆ ಪಾಸ್‌ಕೋಡ್ ಅನ್ನು ಇಲ್ಲಿ ಉಳಿಸಿ. ಇದು ನಿಮ್ಮ ಕಾಯುವಿಕೆಯ ಹಿಂದಿರುವ ಈ ಪುಟದಿಂದ ಮಾತ್ರ ಕಾಣುತ್ತದೆ.",
    "Hand your phone to your friend. Have THEM enter a 4-digit passcode you don't see — don't watch.": "ನಿಮ್ಮ ಫೋನ್ ಅನ್ನು ಸ್ನೇಹಿತನಿಗೆ ಕೊಡಿ. ನೀವು ನೋಡದಂತೆ ಅವರೇ 4 ಅಂಕಿಯ ಪಾಸ್‌ಕೋಡ್ ನಮೂದಿಸಲಿ — ನೋಡಬೇಡಿ.",
    "Heads up: on your iOS version, a limit only counts screen time from the moment you add it — time you already spent earlier today isn't included. Update to iOS 17.4 or later for exact daily counting.": "ಗಮನಿಸಿ: ನಿಮ್ಮ iOS ಆವೃತ್ತಿಯಲ್ಲಿ, ಮಿತಿ ಸೇರಿಸಿದ ಕ್ಷಣದಿಂದ ಮಾತ್ರ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಎಣಿಕೆಯಾಗುತ್ತದೆ — ಇಂದು ಮೊದಲೇ ಕಳೆದ ಸಮಯ ಸೇರುವುದಿಲ್ಲ. ನಿಖರ ದೈನಂದಿನ ಎಣಿಕೆಗೆ iOS 17.4 ಅಥವಾ ನಂತರಕ್ಕೆ ಅಪ್‌ಡೇಟ್ ಮಾಡಿ.",
    "Onboarding demo — you can skip below. It's always available again in Settings → Help.": "ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಡೆಮೊ — ಕೆಳಗೆ ಬಿಟ್ಟುಬಿಡಬಹುದು. ಇದು ಯಾವಾಗಲೂ ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಸಹಾಯದಲ್ಲಿ ಮತ್ತೆ ಲಭ್ಯ.",
    "One more safeguard": "ಇನ್ನೊಂದು ಸುರಕ್ಷತೆ",
    "Open Settings → Screen Time on this iPhone. If it's off, turn it on.": "ಈ iPhone ನಲ್ಲಿ ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಸ್ಕ್ರೀನ್ ಟೈಮ್ ತೆರೆಯಿರಿ. ಆಫ್ ಇದ್ದರೆ ಆನ್ ಮಾಡಿ.",
    "Open the guide": "ಮಾರ್ಗದರ್ಶಿ ತೆರೆಯಿರಿ",
    "Passcode": "ಪಾಸ್‌ಕೋಡ್",
    "Pick someone you trust and can reach. If the passcode and its recovery Apple ID are both lost, removing it may require erasing the device.": "ನೀವು ನಂಬುವ, ಸಂಪರ್ಕಿಸಬಹುದಾದ ಒಬ್ಬರನ್ನು ಆರಿಸಿ. ಪಾಸ್‌ಕೋಡ್ ಮತ್ತು ಅದರ ಮರುಪ್ರಾಪ್ತಿ Apple ID ಎರಡೂ ಕಳೆದುಹೋದರೆ, ಅದನ್ನು ತೆಗೆಯಲು ಸಾಧನವನ್ನು ಅಳಿಸಬೇಕಾಗಬಹುದು.",
    "Prevent disabling": "ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದನ್ನು ತಡೆಯಿರಿ",
    "Protection": "ರಕ್ಷಣೆ",
    "Replay walkthrough": "ವಾಕ್‌ಥ್ರೂ ಮತ್ತೆ ನೋಡಿ",
    "Request access": "ಪ್ರವೇಶ ವಿನಂತಿಸಿ",
    "Save": "ಉಳಿಸಿ",
    "Saved passcode: %@": "ಉಳಿಸಿದ ಪಾಸ್‌ಕೋಡ್: %@",
    "Unlock viewing the stored passcode": "ಉಳಿಸಿದ ಪಾಸ್‌ಕೋಡ್ ನೋಡುವುದನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಿ",
    "Screen Time passcode": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪಾಸ್‌ಕೋಡ್",
    "Enter passcode": "ಪಾಸ್‌ಕೋಡ್ ನಮೂದಿಸಿ",
    "View passcode": "ಪಾಸ್‌ಕೋಡ್ ನೋಡಿ",
    "Change the passcode?": "ಪಾಸ್‌ಕೋಡ್ ಬದಲಿಸಬೇಕೇ?",
    "Are you sure? There is no way to undo this — the saved passcode is replaced only when you save a new one.": "ಖಚಿತವೇ? ಇದನ್ನು ರದ್ದುಮಾಡಲು ದಾರಿಯಿಲ್ಲ — ಹೊಸದನ್ನು ಉಳಿಸಿದಾಗ ಮಾತ್ರ ಉಳಿಸಿದ ಪಾಸ್‌ಕೋಡ್ ಬದಲಾಗುತ್ತದೆ.",
    "The friend who set the Screen Time passcode can store it here so it isn't lost. Going back without saving keeps the current one.": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪಾಸ್‌ಕೋಡ್ ಹೊಂದಿಸಿದ ಸ್ನೇಹಿತ ಅದು ಕಳೆದುಹೋಗದಂತೆ ಇಲ್ಲಿ ಉಳಿಸಬಹುದು. ಉಳಿಸದೆ ಹಿಂದೆ ಹೋದರೆ ಈಗಿರುವುದು ಹಾಗೇ ಇರುತ್ತದೆ.",
    "Viewing the stored passcode is behind your less-strict delay: request it, wait out the delay, and you get one look. After that it locks again.": "ಉಳಿಸಿದ ಪಾಸ್‌ಕೋಡ್ ನೋಡುವುದು ನಿಮ್ಮ ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯ ಹಿಂದಿದೆ: ವಿನಂತಿಸಿ, ಕಾಯುವಿಕೆ ಮುಗಿಸಿ, ಒಂದು ಬಾರಿ ನೋಡಬಹುದು. ನಂತರ ಮತ್ತೆ ಲಾಕ್ ಆಗುತ್ತದೆ.",
    "Access is spent — viewing it again needs a new request.": "ಪ್ರವೇಶ ಬಳಕೆಯಾಗಿದೆ — ಮತ್ತೆ ನೋಡಲು ಹೊಸ ವಿನಂತಿ ಬೇಕು.",
    "Screen Time usually only allows a 4-digit passcode — are you sure this is correct?": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಸಾಮಾನ್ಯವಾಗಿ 4 ಅಂಕಿಯ ಪಾಸ್‌ಕೋಡ್ ಮಾತ್ರ ಅನುಮತಿಸುತ್ತದೆ — ಇದು ಸರಿ ಎಂದು ಖಚಿತವೇ?",
    "Saved ✓": "ಉಳಿಸಲಾಗಿದೆ ✓",
    "Show me how": "ಹೇಗೆಂದು ತೋರಿಸಿ",
    "Skip and set up manually": "ಬಿಟ್ಟು ಕೈಯಾರೆ ಹೊಂದಿಸಿ",
    "Skip walkthrough": "ವಾಕ್‌ಥ್ರೂ ಬಿಟ್ಟುಬಿಡಿ",
    "Skip — set up manually": "ಬಿಟ್ಟುಬಿಡಿ — ಕೈಯಾರೆ ಹೊಂದಿಸಿ",
    "Store the Screen Time passcode": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪಾಸ್‌ಕೋಡ್ ಉಳಿಸಿ",
    "Take photo": "ಫೋಟೋ ತೆಗೆಯಿರಿ",
    "Takes about 2 minutes, and you need a second person physically with you.": "ಸುಮಾರು 2 ನಿಮಿಷ ಬೇಕು, ಮತ್ತು ಪಕ್ಕದಲ್ಲೇ ಎರಡನೇ ವ್ಯಕ್ತಿ ಇರಬೇಕು.",
    "Tap “Lock Screen Time Settings” (or “Use Screen Time Passcode”).": "\"ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಲಾಕ್ ಮಾಡಿ\" (ಅಥವಾ \"ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪಾಸ್‌ಕೋಡ್ ಬಳಸಿ\") ಟ್ಯಾಪ್ ಮಾಡಿ.",
    "Thank you. ❤️": "ಧನ್ಯವಾದಗಳು. ❤️",
    "That's okay. Without Screen Time access Demora can't block apps, but you can continue and turn it on later.": "ಪರವಾಗಿಲ್ಲ. ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪ್ರವೇಶವಿಲ್ಲದೆ Demora ಆ್ಯಪ್‌ಗಳನ್ನು ಬ್ಲಾಕ್ ಮಾಡಲಾಗದು, ಆದರೆ ಮುಂದುವರಿದು ನಂತರ ಆನ್ ಮಾಡಬಹುದು.",
    "That's the whole loop. Your real limits, schedules, and settings are still here — nothing changed.": "ಇದೇ ಇಡೀ ಚಕ್ರ. ನಿಮ್ಮ ನಿಜವಾದ ಮಿತಿಗಳು, ವೇಳಾಪಟ್ಟಿಗಳು ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಇನ್ನೂ ಇಲ್ಲೇ ಇವೆ — ಏನೂ ಬದಲಾಗಿಲ್ಲ.",
    "There's a way to make Demora impossible to turn off — with a friend's help. It takes about 2 minutes and needs a second person physically with you.": "ಸ್ನೇಹಿತನ ಸಹಾಯದಿಂದ Demora ಅನ್ನು ಆಫ್ ಮಾಡಲಾಗದಂತೆ ಮಾಡುವ ದಾರಿ ಇದೆ. ಸುಮಾರು 2 ನಿಮಿಷ ಬೇಕು, ಮತ್ತು ಪಕ್ಕದಲ್ಲೇ ಎರಡನೇ ವ್ಯಕ್ತಿ ಇರಬೇಕು.",
    "They call themselves “%@”.": "ಅವರು ತಮ್ಮನ್ನು \"%@\" ಎಂದು ಕರೆದುಕೊಳ್ಳುತ್ತಾರೆ.",
    "This guide is behind your less-strict delay: request it, wait out the delay, and you get one open. After you view it, it locks again.": "ಈ ಮಾರ್ಗದರ್ಶಿ ನಿಮ್ಮ ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯ ಹಿಂದಿದೆ: ವಿನಂತಿಸಿ, ಕಾಯುವಿಕೆ ಮುಗಿಸಿ, ಒಂದು ಬಾರಿ ತೆರೆಯಬಹುದು. ನೋಡಿದ ನಂತರ ಮತ್ತೆ ಲಾಕ್ ಆಗುತ್ತದೆ.",
    "Unavailable": "ಲಭ್ಯವಿಲ್ಲ",
    "Unlock the “Prevent disabling” guide": "\"ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದನ್ನು ತಡೆಯಿರಿ\" ಮಾರ್ಗದರ್ಶಿ ಅನ್‌ಲಾಕ್ ಮಾಡಿ",
    "Use photo": "ಫೋಟೋ ಬಳಸಿ",
    "When asked for Screen Time Passcode Recovery, your friend signs in with THEIR OWN Apple ID — not yours. That's what stops you from resetting the passcode on your own.": "ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪಾಸ್‌ಕೋಡ್ ಮರುಪ್ರಾಪ್ತಿ ಕೇಳಿದಾಗ, ನಿಮ್ಮ ಸ್ನೇಹಿತ ನಿಮ್ಮದಲ್ಲ, ತಮ್ಮದೇ Apple ID ಯಿಂದ ಸೈನ್ ಇನ್ ಮಾಡುತ್ತಾರೆ. ಅದೇ ನೀವೇ ಪಾಸ್‌ಕೋಡ್ ರೀಸೆಟ್ ಮಾಡುವುದನ್ನು ತಡೆಯುತ್ತದೆ.",
    "You can always find this later under Help — but there it's behind a delay.": "ಇದನ್ನು ನಂತರ ಸಹಾಯದಲ್ಲಿ ಯಾವಾಗಲೂ ಕಾಣಬಹುದು — ಆದರೆ ಅಲ್ಲಿ ಅದು ಕಾಯುವಿಕೆಯ ಹಿಂದಿದೆ.",
    "You can change these any time under General blocking. Each change then goes through your delays.": "ಇವನ್ನು ಯಾವಾಗ ಬೇಕಾದರೂ ಸಾಮಾನ್ಯ ಬ್ಲಾಕ್‌ನಲ್ಲಿ ಬದಲಿಸಬಹುದು. ಪ್ರತಿ ಬದಲಾವಣೆ ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳ ಮೂಲಕ ಹೋಗುತ್ತದೆ.",
    "Your one-time access is ready.": "ನಿಮ್ಮ ಒಂದು ಬಾರಿಯ ಪ್ರವೇಶ ಸಿದ್ಧ.",
    "your setup stays safe": "ನಿಮ್ಮ ಸೆಟಪ್ ಸುರಕ್ಷಿತವಾಗಿರುತ್ತದೆ",
    "—": "—",
    "A backup, if you want one.": "ಬೇಕಿದ್ದರೆ ಒಂದು ಬ್ಯಾಕಪ್.",
    "Optional: add a trusted contact, a phrase, or a password. Choose exactly what each can approve or unlock.": "ಐಚ್ಛಿಕ: ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ, ವಾಕ್ಯ ಅಥವಾ ಪಾಸ್‌ವರ್ಡ್ ಸೇರಿಸಿ. ಪ್ರತಿಯೊಂದು ಏನನ್ನು ಒಪ್ಪಬಹುದು ಅಥವಾ ಅನ್‌ಲಾಕ್ ಮಾಡಬಹುದು ಎಂದು ನಿಖರವಾಗಿ ಆರಿಸಿ.",
    "These choices apply when you finish setup. Later additions and permission changes follow your delays.": "ಸೆಟಪ್ ಮುಗಿಸಿದಾಗ ಈ ಆಯ್ಕೆಗಳು ಅನ್ವಯಿಸುತ್ತವೆ. ನಂತರದ ಸೇರ್ಪಡೆಗಳು ಮತ್ತು ಅನುಮತಿ ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳನ್ನು ಅನುಸರಿಸುತ್ತವೆ.",
    "Background monitoring limit": "ಹಿನ್ನೆಲೆ ಮೇಲ್ವಿಚಾರಣೆ ಮಿತಿ",
    "This change needs %d background monitors, but iOS allows %d. Remove a schedule, split budget or pending change, then try again.": "ಈ ಬದಲಾವಣೆಗೆ %d ಹಿನ್ನೆಲೆ ಮಾನಿಟರ್‌ಗಳು ಬೇಕು, ಆದರೆ iOS %d ಅನುಮತಿಸುತ್ತದೆ. ಒಂದು ವೇಳಾಪಟ್ಟಿ, ಹಂಚಿದ ಬಜೆಟ್ ಅಥವಾ ಬಾಕಿ ಬದಲಾವಣೆಯನ್ನು ತೆಗೆದು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    // Change receipt (Today redesign)
    "Looser change": "ಸಡಿಲ ಬದಲಾವಣೆ",
