    "Right away": "ತಕ್ಷಣ",
    "Until then nothing changes. You can cancel it from Today.": "ಅಲ್ಲಿಯವರೆಗೆ ಏನೂ ಬದಲಾಗುವುದಿಲ್ಲ. ಇದನ್ನು ಇಂದು ಟ್ಯಾಬ್‌ನಿಂದ ರದ್ದುಮಾಡಬಹುದು.",
