    "Changes you make wait here until they apply.": "ನೀವು ಮಾಡುವ ಬದಲಾವಣೆಗಳು ಜಾರಿಗೆ ಬರುವವರೆಗೆ ಇಲ್ಲಿ ಕಾಯುತ್ತವೆ.",
