    "%d blocks are on. The first ends at %@.": "%d ಬ್ಲಾಕ್‌ಗಳು ಆನ್ ಇವೆ. ಮೊದಲನೆಯದು %@ ಕ್ಕೆ ಮುಗಿಯುತ್ತದೆ.",
