    "Good morning. Your apps wait until you wake up.": "ಶುಭೋದಯ. ನೀವು ಎಚ್ಚರಗೊಳ್ಳುವವರೆಗೆ ನಿಮ್ಮ ಆ್ಯಪ್‌ಗಳು ಕಾಯುತ್ತವೆ.",
    "Your apps open at %@.": "ನಿಮ್ಮ ಆ್ಯಪ್‌ಗಳು %@ ಕ್ಕೆ ತೆರೆಯುತ್ತವೆ.",
