    "%d words, typed one by one": "%d ಪದಗಳು, ಒಂದೊಂದಾಗಿ ಟೈಪ್ ಮಾಡಿ",
    "+%d min": "+%d ನಿಮಿ",
    "Any one approval is enough.": "ಯಾವುದೇ ಒಂದು ಒಪ್ಪಿಗೆ ಸಾಕು.",
    "Ask again": "ಮತ್ತೆ ಕೇಳಿ",
    "Can't reach right now": "ಈಗ ತಲುಪಲಾಗುತ್ತಿಲ್ಲ",
