    "Enter the code %@ received. It expires in 15 minutes.": "%@ ಗೆ ಬಂದ ಕೋಡ್ ನಮೂದಿಸಿ. ಇದು 15 ನಿಮಿಷಗಳಲ್ಲಿ ಮುಗಿಯುತ್ತದೆ.",
    "Lands %@ · in": "%@ ಕ್ಕೆ ಜಾರಿ · ಇನ್ನು",
    "None of your ways can skip this change.": "ನಿಮ್ಮ ಯಾವ ಮಾರ್ಗವೂ ಈ ಬದಲಾವಣೆಯ ಕಾಯುವಿಕೆ ಬಿಡಲಾಗದು.",
    "Only ways allowed to skip this change are listed.": "ಈ ಬದಲಾವಣೆ ಬಿಡಲು ಅನುಮತಿಸಿದ ಮಾರ್ಗಗಳನ್ನು ಮಾತ್ರ ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ.",
    "Phrase": "ವಾಕ್ಯ",
    "Sent · waiting": "ಕಳುಹಿಸಲಾಗಿದೆ · ಕಾಯುತ್ತಿದೆ",
    "That password doesn't match, or this change is no longer waiting.": "ಆ ಪಾಸ್‌ವರ್ಡ್ ಹೊಂದಿಕೆಯಾಗುತ್ತಿಲ್ಲ, ಅಥವಾ ಈ ಬದಲಾವಣೆ ಇನ್ನು ಕಾಯುತ್ತಿಲ್ಲ.",
