    // Ways to skip a wait: add, edit, remove (docs/you-redesign.md §5.9–5.10)
    "%@ gets the request now and can approve once they accept and the wait ends.": "%@ ಗೆ ಈಗ ವಿನಂತಿ ಹೋಗುತ್ತದೆ; ಅವರು ಸ್ವೀಕರಿಸಿ ಕಾಯುವಿಕೆ ಮುಗಿದ ನಂತರ ಒಪ್ಪಬಹುದು.",
    "%d random words": "%d ಯಾದೃಚ್ಛಿಕ ಪದಗಳು",
    "A change is already waiting": "ಒಂದು ಬದಲಾವಣೆ ಈಗಾಗಲೇ ಕಾಯುತ್ತಿದೆ",
    "Adding, removing or pausing trusted contacts": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕಗಳನ್ನು ಸೇರಿಸುವುದು, ತೆಗೆಯುವುದು ಅಥವಾ ವಿರಾಮಗೊಳಿಸುವುದು",
    "Also needs a limit whose extra time asks for this.": "ಇದಕ್ಕಾಗಿ ಹೆಚ್ಚುವರಿ ಸಮಯ ಕೇಳುವ ಮಿತಿಯೂ ಬೇಕು.",
    "Also turns on contact approvals": "ಸಂಪರ್ಕ ಒಪ್ಪಿಗೆಗಳನ್ನೂ ಆನ್ ಮಾಡುತ್ತದೆ",
    "App deletion lock, websites and Prevent disabling access": "ಆ್ಯಪ್ ಅಳಿಸುವಿಕೆ ಲಾಕ್, ವೆಬ್‌ಸೈಟ್‌ಗಳು ಮತ್ತು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದನ್ನು ತಡೆಯುವ ಪ್ರವೇಶ",
    "Ask them for the code under You → Your code. Yours is %@.": "ನೀವು → ನಿಮ್ಮ ಕೋಡ್ ಅಡಿಯ ಕೋಡ್ ಅವರನ್ನು ಕೇಳಿ. ನಿಮ್ಮದು %@.",
    "Best if someone else keeps it, or it's written down somewhere out of reach.": "ಬೇರೊಬ್ಬರು ಇಟ್ಟುಕೊಂಡರೆ, ಅಥವಾ ಕೈಗೆ ಸಿಗದ ಕಡೆ ಬರೆದಿಟ್ಟರೆ ಉತ್ತಮ.",
    "Change now": "ಈಗ ಬದಲಿಸಿ",
    "Change the password": "ಪಾಸ್‌ವರ್ಡ್ ಬದಲಿಸಿ",
    "Change the words": "ಪದಗಳನ್ನು ಬದಲಿಸಿ",
    "Changes that wait": "ಕಾಯುವ ಬದಲಾವಣೆಗಳು",
    "Choose at least one thing it can skip.": "ಇದು ಬಿಡಬಹುದಾದ ಕನಿಷ್ಠ ಒಂದನ್ನು ಆರಿಸಿ.",
    "Current password": "ಈಗಿನ ಪಾಸ್‌ವರ್ಡ್",
    "Demora code %@": "Demora ಕೋಡ್ %@",
    "From %@: %@": "%@ ರಿಂದ: %@",
    "Mistakes allowed: %d": "ಅನುಮತಿಸಿದ ತಪ್ಪುಗಳು: %d",
    "Mistakes allowed: unlimited": "ಅನುಮತಿಸಿದ ತಪ್ಪುಗಳು: ಮಿತಿಯಿಲ್ಲ",
    "Name, e.g. Mom or Alex": "ಹೆಸರು, ಉದಾ. ಅಮ್ಮ ಅಥವಾ ಅಲೆಕ್ಸ್",
    "Part of this was saved and is waiting in Changes. The rest couldn't be saved.": "ಇದರ ಒಂದು ಭಾಗ ಉಳಿದು ಬದಲಾವಣೆಗಳಲ್ಲಿ ಕಾಯುತ್ತಿದೆ. ಉಳಿದದ್ದನ್ನು ಉಳಿಸಲಾಗಲಿಲ್ಲ.",
    "Password set": "ಪಾಸ್‌ವರ್ಡ್ ಹೊಂದಿಸಲಾಗಿದೆ",
    "Save changes": "ಬದಲಾವಣೆಗಳನ್ನು ಉಳಿಸಿ",
    "Takes effect right away. What it can skip stays the same.": "ತಕ್ಷಣ ಜಾರಿಗೆ ಬರುತ್ತದೆ. ಅದು ಬಿಡಬಹುದಾದವು ಹಾಗೇ ಇರುತ್ತವೆ.",
    "The current password is wrong or a change is already pending.": "ಈಗಿನ ಪಾಸ್‌ವರ್ಡ್ ತಪ್ಪು, ಅಥವಾ ಒಂದು ಬದಲಾವಣೆ ಈಗಾಗಲೇ ಬಾಕಿ ಇದೆ.",
    "They approve from their Demora app, or with a code you email them.": "ಅವರು ತಮ್ಮ Demora ಆ್ಯಪ್‌ನಿಂದ, ಅಥವಾ ನೀವು ಇಮೇಲ್ ಮಾಡುವ ಕೋಡ್‌ನಿಂದ ಒಪ್ಪುತ್ತಾರೆ.",
    "They approve from their Demora app.": "ಅವರು ತಮ್ಮ Demora ಆ್ಯಪ್‌ನಿಂದ ಒಪ್ಪುತ್ತಾರೆ.",
    "This contact": "ಈ ಸಂಪರ್ಕ",
    "This is no longer available.": "ಇದು ಇನ್ನು ಲಭ್ಯವಿಲ್ಲ.",
    "Typed word by word. Slow on purpose.": "ಪದ ಪದವಾಗಿ ಟೈಪ್ ಮಾಡಿ. ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ನಿಧಾನ.",
    "What it can skip": "ಅದು ಏನನ್ನು ಬಿಡಬಹುದು",
    // You build: Guide, help and pointers to You (docs/you-redesign.md §8, Y10)
    "Demora protects deliberate decisions with time. In Rules → Your waits, choose separate waits for stricter and less-strict changes, one shared wait, or immediate tightening with a wait only for loosening. Lowering a budget tightens it; raising or removing it loosens it. Changing the policy follows your current policy, not the new one.": "Demora ಉದ್ದೇಶಪೂರ್ವಕ ನಿರ್ಧಾರಗಳನ್ನು ಸಮಯದಿಂದ ರಕ್ಷಿಸುತ್ತದೆ. ನಿಯಮಗಳು → ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳಲ್ಲಿ, ಕಠಿಣ ಮತ್ತು ಕಡಿಮೆ-ಕಠಿಣ ಬದಲಾವಣೆಗಳಿಗೆ ಬೇರೆಬೇರೆ ಕಾಯುವಿಕೆ, ಒಂದೇ ಹಂಚಿದ ಕಾಯುವಿಕೆ, ಅಥವಾ ತಕ್ಷಣ ಬಿಗಿಗೊಳಿಸಿ ಸಡಿಲಿಸುವಾಗ ಮಾತ್ರ ಕಾಯುವುದನ್ನು ಆರಿಸಿ. ಬಜೆಟ್ ಕಡಿಮೆ ಮಾಡುವುದು ಅದನ್ನು ಬಿಗಿಗೊಳಿಸುತ್ತದೆ; ಹೆಚ್ಚಿಸುವುದು ಅಥವಾ ತೆಗೆಯುವುದು ಸಡಿಲಿಸುತ್ತದೆ. ನೀತಿಯನ್ನು ಬದಲಿಸುವುದು ಹೊಸದನ್ನಲ್ಲ, ನಿಮ್ಮ ಈಗಿನ ನೀತಿಯನ್ನು ಅನುಸರಿಸುತ್ತದೆ.",
    "Changes on Today shows queued changes and their countdowns. Cancel one there before it applies, or skip its wait with an eligible way to skip a wait. Current rules stay active until the change applies. Existing countdowns keep their deadlines when you edit delay settings or reopen Demora. Background application depends on iOS callbacks; open Demora if a due change has not appeared.": "ಇಂದು ಟ್ಯಾಬ್‌ನ ಬದಲಾವಣೆಗಳು ಸರದಿಯಲ್ಲಿರುವ ಬದಲಾವಣೆಗಳನ್ನು ಮತ್ತು ಅವುಗಳ ಕೌಂಟ್‌ಡೌನ್‌ಗಳನ್ನು ತೋರಿಸುತ್ತದೆ. ಅದು ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ಅಲ್ಲಿ ರದ್ದುಮಾಡಿ, ಅಥವಾ ಅರ್ಹ ಕಾಯುವಿಕೆ ಬಿಡುವ ಮಾರ್ಗದಿಂದ ಅದರ ಕಾಯುವಿಕೆ ಬಿಡಿ. ಬದಲಾವಣೆ ಜಾರಿಯಾಗುವವರೆಗೆ ಈಗಿನ ನಿಯಮಗಳು ಸಕ್ರಿಯವಾಗಿರುತ್ತವೆ. ಕಾಯುವಿಕೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಬದಲಿಸಿದರೂ ಅಥವಾ Demora ಮರುತೆರೆದರೂ ಈಗಿನ ಕೌಂಟ್‌ಡೌನ್‌ಗಳು ತಮ್ಮ ಗಡುವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತವೆ. ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಅನ್ವಯಿಸುವುದು iOS ಕಾಲ್‌ಬ್ಯಾಕ್‌ಗಳ ಮೇಲೆ ಅವಲಂಬಿತ; ಬರಬೇಕಾದ ಬದಲಾವಣೆ ಕಾಣದಿದ್ದರೆ Demora ತೆರೆಯಿರಿ.",
    "In Rules, tap New rule → Daily limit, name a limit, choose apps, categories or websites, and set usage minutes. A group shares one allowance across its selection. Zero minutes blocks it all day. Open an existing limit to edit it. Different limits by weekday replaces the default budget on each chosen day. Daily allowances reset at midnight; on iOS 17.4 or later, earlier usage that day also counts.": "ನಿಯಮಗಳಲ್ಲಿ, ಹೊಸ ನಿಯಮ → ದೈನಂದಿನ ಮಿತಿ ಟ್ಯಾಪ್ ಮಾಡಿ, ಮಿತಿಗೆ ಹೆಸರಿಡಿ, ಆ್ಯಪ್‌ಗಳು, ವರ್ಗಗಳು ಅಥವಾ ವೆಬ್‌ಸೈಟ್‌ಗಳನ್ನು ಆರಿಸಿ, ಬಳಕೆಯ ನಿಮಿಷಗಳನ್ನು ಹೊಂದಿಸಿ. ಗುಂಪು ತನ್ನ ಆಯ್ಕೆಯಾದ್ಯಂತ ಒಂದೇ ಮಿತಿಯನ್ನು ಹಂಚುತ್ತದೆ. ಶೂನ್ಯ ನಿಮಿಷ ಅದನ್ನು ದಿನವಿಡೀ ಬ್ಲಾಕ್ ಮಾಡುತ್ತದೆ. ಈಗಿರುವ ಮಿತಿಯನ್ನು ಬದಲಿಸಲು ತೆರೆಯಿರಿ. ವಾರದ ದಿನಕ್ಕೆ ಬೇರೆ ಮಿತಿಗಳು ಆಯ್ದ ಪ್ರತಿ ದಿನದ ಡೀಫಾಲ್ಟ್ ಬಜೆಟ್ ಅನ್ನು ಬದಲಿಸುತ್ತವೆ. ದೈನಂದಿನ ಮಿತಿಗಳು ಮಧ್ಯರಾತ್ರಿ ರೀಸೆಟ್ ಆಗುತ್ತವೆ; iOS 17.4 ಅಥವಾ ನಂತರದಲ್ಲಿ ಆ ದಿನದ ಹಿಂದಿನ ಬಳಕೆಯೂ ಎಣಿಕೆಯಾಗುತ್ತದೆ.",
    "In a limit's editor, Manual extra time sets up to five ordered uses, each with its own usage minutes and a wait, named password, phrase or contact approval. Request a use on Today only after the full daily budget is spent. These are app-usage minutes, not a timed unblock session. Requests survive reopening Demora and reset at midnight. Extra time does not skip an early split portion, wake wait or unrelated block.": "ಮಿತಿಯ ಎಡಿಟರ್‌ನಲ್ಲಿ, ಕೈಯಾರೆ ಹೆಚ್ಚುವರಿ ಸಮಯ ಐದರವರೆಗೆ ಕ್ರಮಬದ್ಧ ಬಳಕೆಗಳನ್ನು ಹೊಂದಿಸುತ್ತದೆ; ಪ್ರತಿಯೊಂದಕ್ಕೂ ತನ್ನದೇ ಬಳಕೆಯ ನಿಮಿಷಗಳು ಮತ್ತು ಕಾಯುವಿಕೆ, ಹೆಸರಿಸಿದ ಪಾಸ್‌ವರ್ಡ್, ವಾಕ್ಯ ಅಥವಾ ಸಂಪರ್ಕದ ಒಪ್ಪಿಗೆ. ಪೂರ್ಣ ದೈನಂದಿನ ಬಜೆಟ್ ಮುಗಿದ ನಂತರವೇ ಇಂದು ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಬಳಕೆಯನ್ನು ವಿನಂತಿಸಿ. ಇವು ಆ್ಯಪ್ ಬಳಕೆಯ ನಿಮಿಷಗಳು, ಸಮಯದ ಅನ್‌ಬ್ಲಾಕ್ ಸೆಷನ್ ಅಲ್ಲ. ವಿನಂತಿಗಳು Demora ಮರುತೆರೆದರೂ ಉಳಿಯುತ್ತವೆ ಮತ್ತು ಮಧ್ಯರಾತ್ರಿ ರೀಸೆಟ್ ಆಗುತ್ತವೆ. ಹೆಚ್ಚುವರಿ ಸಮಯ ಆರಂಭಿಕ ಹಂಚಿಕೆ ಭಾಗ, ಎಚ್ಚರದ ಕಾಯುವಿಕೆ ಅಥವಾ ಸಂಬಂಧವಿಲ್ಲದ ಬ್ಲಾಕ್ ಅನ್ನು ಬಿಡುವುದಿಲ್ಲ.",
    "In Rules, tap New rule → Day & night to create up to five named groups. Check existing limits and choose extra apps, then set wake-up and sleep times and weekdays. One optional all-other-apps group automatically excludes explicitly timed groups; whole-category exceptions are not supported. Existing general wake/sleep settings and Group wake-up gates still apply alongside these groups.": "ನಿಯಮಗಳಲ್ಲಿ, ಹೊಸ ನಿಯಮ → ಹಗಲು ಮತ್ತು ರಾತ್ರಿ ಟ್ಯಾಪ್ ಮಾಡಿ ಐದರವರೆಗೆ ಹೆಸರಿಸಿದ ಗುಂಪುಗಳನ್ನು ರಚಿಸಿ. ಈಗಿರುವ ಮಿತಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಹೆಚ್ಚುವರಿ ಆ್ಯಪ್‌ಗಳನ್ನು ಆರಿಸಿ, ನಂತರ ಎಚ್ಚರ ಮತ್ತು ನಿದ್ರೆ ಸಮಯ ಹಾಗೂ ವಾರದ ದಿನಗಳನ್ನು ಹೊಂದಿಸಿ. ಐಚ್ಛಿಕ ಒಂದು ಇತರ-ಎಲ್ಲಾ-ಆ್ಯಪ್‌ಗಳ ಗುಂಪು ಸ್ಪಷ್ಟ ಸಮಯದ ಗುಂಪುಗಳನ್ನು ತಾನಾಗಿ ಹೊರಗಿಡುತ್ತದೆ; ಇಡೀ ವರ್ಗದ ವಿನಾಯಿತಿಗಳು ಬೆಂಬಲಿತವಲ್ಲ. ಈಗಿರುವ ಸಾಮಾನ್ಯ ಎಚ್ಚರ/ನಿದ್ರೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಮತ್ತು ಗುಂಪು ಎಚ್ಚರದ ಗೇಟ್‌ಗಳು ಈ ಗುಂಪುಗಳ ಜೊತೆಗೇ ಅನ್ವಯಿಸುತ್ತವೆ.",
    "Set a wake-up start and wait, with optional per-weekday start and wait overrides. Tap Wake up on Today to start every eligible group's wait together; tapping again does not restart it. An optional latest wake-up time, also configurable by weekday, ends only that wake gate even without a tap or during a wait. It does not end sleep blocking or restore a spent daily budget.": "ಎಚ್ಚರದ ಆರಂಭ ಮತ್ತು ಕಾಯುವಿಕೆ ಹೊಂದಿಸಿ, ಐಚ್ಛಿಕವಾಗಿ ವಾರದ ದಿನಕ್ಕೆ ಬೇರೆ ಆರಂಭ ಮತ್ತು ಕಾಯುವಿಕೆ. ಪ್ರತಿ ಅರ್ಹ ಗುಂಪಿನ ಕಾಯುವಿಕೆಯನ್ನು ಒಟ್ಟಿಗೇ ಆರಂಭಿಸಲು ಇಂದು ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಎಚ್ಚರ ಟ್ಯಾಪ್ ಮಾಡಿ; ಮತ್ತೆ ಟ್ಯಾಪ್ ಮಾಡಿದರೆ ಅದು ಮರುಆರಂಭವಾಗುವುದಿಲ್ಲ. ವಾರದ ದಿನದ ಪ್ರಕಾರವೂ ಹೊಂದಿಸಬಹುದಾದ ಐಚ್ಛಿಕ ಕೊನೆಯ ಎಚ್ಚರದ ಸಮಯ, ಟ್ಯಾಪ್ ಇಲ್ಲದಿದ್ದರೂ ಅಥವಾ ಕಾಯುವಿಕೆಯ ನಡುವೆಯೂ ಆ ಎಚ್ಚರದ ಗೇಟ್ ಅನ್ನು ಮಾತ್ರ ಮುಗಿಸುತ್ತದೆ. ಅದು ನಿದ್ರೆ ಬ್ಲಾಕ್ ಅನ್ನು ಮುಗಿಸುವುದಿಲ್ಲ ಅಥವಾ ಬಳಸಿದ ದೈನಂದಿನ ಬಜೆಟ್ ಅನ್ನು ಮರುಸ್ಥಾಪಿಸುವುದಿಲ್ಲ.",
    "In Rules, tap New rule and choose New session, Plan a block or Repeating block; New session also sits at the bottom of Today. Create a block, unblock or free period. New session starts after any required delay; its duration starts when it takes effect. Planned uses a specific date. Repeating runs daily, on weekdays or on a monthly pattern, and can cross midnight. Blocking rules can target selected apps or everything except a selection. Rules → Calendar shows occurrences.": "ನಿಯಮಗಳಲ್ಲಿ, ಹೊಸ ನಿಯಮ ಟ್ಯಾಪ್ ಮಾಡಿ ಹೊಸ ಸೆಷನ್, ಬ್ಲಾಕ್ ಯೋಜಿಸಿ ಅಥವಾ ಪುನರಾವರ್ತಿತ ಬ್ಲಾಕ್ ಆರಿಸಿ; ಹೊಸ ಸೆಷನ್ ಇಂದು ಟ್ಯಾಬ್‌ನ ಕೆಳಭಾಗದಲ್ಲೂ ಇದೆ. ಬ್ಲಾಕ್, ಅನ್‌ಬ್ಲಾಕ್ ಅಥವಾ ಮುಕ್ತ ಅವಧಿ ರಚಿಸಿ. ಹೊಸ ಸೆಷನ್ ಅಗತ್ಯ ಕಾಯುವಿಕೆಯ ನಂತರ ಆರಂಭವಾಗುತ್ತದೆ; ಅದರ ಅವಧಿ ಜಾರಿಗೆ ಬಂದಾಗ ಆರಂಭ. ಯೋಜಿತ ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕ ಬಳಸುತ್ತದೆ. ಪುನರಾವರ್ತಿತ ಪ್ರತಿದಿನ, ವಾರದ ದಿನಗಳಲ್ಲಿ ಅಥವಾ ಮಾಸಿಕ ಮಾದರಿಯಲ್ಲಿ ನಡೆಯುತ್ತದೆ, ಮತ್ತು ಮಧ್ಯರಾತ್ರಿ ದಾಟಬಹುದು. ಬ್ಲಾಕ್ ನಿಯಮಗಳು ಆಯ್ದ ಆ್ಯಪ್‌ಗಳನ್ನು ಅಥವಾ ಆಯ್ಕೆಯನ್ನು ಬಿಟ್ಟು ಎಲ್ಲವನ್ನೂ ಗುರಿಯಾಗಿಸಬಹುದು. ನಿಯಮಗಳು → ಕ್ಯಾಲೆಂಡರ್ ಘಟನೆಗಳನ್ನು ತೋರಿಸುತ್ತದೆ.",
    "In Rules, tap Conflicts to review the next week's potential overlaps. Default application order is wake/sleep → recurring → planned → sessions. Later effects apply only within their scope: an allowlist is not a global unblock, does not reset daily usage, and does not clear unrelated specific blocks. Category membership is hidden by Apple, and untapped wake windows are estimates, so some overlaps are uncertain.": "ನಿಯಮಗಳಲ್ಲಿ, ಮುಂದಿನ ವಾರದ ಸಂಭಾವ್ಯ ಅತಿಕ್ರಮಣಗಳನ್ನು ನೋಡಲು ಸಂಘರ್ಷಗಳು ಟ್ಯಾಪ್ ಮಾಡಿ. ಡೀಫಾಲ್ಟ್ ಅನ್ವಯ ಕ್ರಮ: ಎಚ್ಚರ/ನಿದ್ರೆ → ಪುನರಾವರ್ತಿತ → ಯೋಜಿತ → ಸೆಷನ್‌ಗಳು. ನಂತರದ ಪರಿಣಾಮಗಳು ತಮ್ಮ ವ್ಯಾಪ್ತಿಯೊಳಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತವೆ: ಅನುಮತಿ ಪಟ್ಟಿ ಜಾಗತಿಕ ಅನ್‌ಬ್ಲಾಕ್ ಅಲ್ಲ, ದೈನಂದಿನ ಬಳಕೆಯನ್ನು ರೀಸೆಟ್ ಮಾಡುವುದಿಲ್ಲ, ಮತ್ತು ಸಂಬಂಧವಿಲ್ಲದ ನಿರ್ದಿಷ್ಟ ಬ್ಲಾಕ್‌ಗಳನ್ನು ತೆಗೆಯುವುದಿಲ್ಲ. ವರ್ಗ ಸದಸ್ಯತ್ವವನ್ನು Apple ಮರೆಮಾಡುತ್ತದೆ, ಮತ್ತು ಟ್ಯಾಪ್ ಮಾಡದ ಎಚ್ಚರದ ಅವಧಿಗಳು ಅಂದಾಜುಗಳು, ಹಾಗಾಗಿ ಕೆಲವು ಅತಿಕ್ರಮಣಗಳು ಅನಿಶ್ಚಿತ.",
    "Open You → Ways to skip a wait to add, change or remove named passwords and phrases. Each has its own allowed uses; it cannot approve an unrelated change. Phrases can be custom or random on-device words, typed word by word with your chosen mistake allowance. Adding one or expanding what it may skip waits through the less-strict delay. Knowing the current password permits an immediate secret-only change, not an immediate permissions change.": "ಹೆಸರಿಸಿದ ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಮತ್ತು ವಾಕ್ಯಗಳನ್ನು ಸೇರಿಸಲು, ಬದಲಿಸಲು ಅಥವಾ ತೆಗೆಯಲು ನೀವು → ಕಾಯುವಿಕೆ ಬಿಡುವ ಮಾರ್ಗಗಳು ತೆರೆಯಿರಿ. ಪ್ರತಿಯೊಂದಕ್ಕೂ ತನ್ನದೇ ಅನುಮತಿಸಿದ ಬಳಕೆಗಳಿವೆ; ಅದು ಸಂಬಂಧವಿಲ್ಲದ ಬದಲಾವಣೆಯನ್ನು ಒಪ್ಪಲಾಗದು. ವಾಕ್ಯಗಳು ಕಸ್ಟಮ್ ಅಥವಾ ಸಾಧನದಲ್ಲೇ ಮಾಡಿದ ಯಾದೃಚ್ಛಿಕ ಪದಗಳಾಗಿರಬಹುದು, ನೀವು ಆರಿಸಿದ ತಪ್ಪಿನ ಅನುಮತಿಯೊಂದಿಗೆ ಪದ ಪದವಾಗಿ ಟೈಪ್ ಮಾಡಿ. ಒಂದನ್ನು ಸೇರಿಸುವುದು ಅಥವಾ ಅದು ಬಿಡಬಹುದಾದ್ದನ್ನು ವಿಸ್ತರಿಸುವುದು ಕಡಿಮೆ-ಕಠಿಣ ಕಾಯುವಿಕೆಯ ಮೂಲಕ ಹೋಗುತ್ತದೆ. ಈಗಿನ ಪಾಸ್‌ವರ್ಡ್ ತಿಳಿದಿರುವುದು ತಕ್ಷಣದ ಗುಪ್ತ-ಮಾತ್ರ ಬದಲಾವಣೆಗೆ ಅವಕಾಶ ನೀಡುತ್ತದೆ, ತಕ್ಷಣದ ಅನುಮತಿ ಬದಲಾವಣೆಗಲ್ಲ.",
    "In Rules, Recheck blocked limits takes around 30 seconds and keeps current blocks in place while iOS verifies usage. Confirmed spent limits stay blocked; a failed or interrupted check changes nothing. This is not a bypass for a real spent budget, split boundary, wake wait or schedule. Safe rechecking needs iOS 17.4 or later; wait until an active free period ends before trying.": "ನಿಯಮಗಳಲ್ಲಿ, ಬ್ಲಾಕ್ ಆದ ಮಿತಿಗಳನ್ನು ಮರುಪರಿಶೀಲಿಸಿ ಸುಮಾರು 30 ಸೆಕೆಂಡ್ ಬೇಕು ಮತ್ತು iOS ಬಳಕೆಯನ್ನು ಪರಿಶೀಲಿಸುವಾಗ ಈಗಿನ ಬ್ಲಾಕ್‌ಗಳನ್ನು ಹಾಗೇ ಇಡುತ್ತದೆ. ದೃಢೀಕೃತ ಮುಗಿದ ಮಿತಿಗಳು ಬ್ಲಾಕ್ ಆಗಿಯೇ ಉಳಿಯುತ್ತವೆ; ವಿಫಲ ಅಥವಾ ಅಡಚಣೆಯಾದ ಪರಿಶೀಲನೆ ಏನನ್ನೂ ಬದಲಿಸುವುದಿಲ್ಲ. ಇದು ನಿಜವಾಗಿ ಮುಗಿದ ಬಜೆಟ್, ಹಂಚಿಕೆ ಗಡಿ, ಎಚ್ಚರದ ಕಾಯುವಿಕೆ ಅಥವಾ ವೇಳಾಪಟ್ಟಿಯನ್ನು ತಪ್ಪಿಸುವ ದಾರಿ ಅಲ್ಲ. ಸುರಕ್ಷಿತ ಮರುಪರಿಶೀಲನೆಗೆ iOS 17.4 ಅಥವಾ ನಂತರ ಬೇಕು; ಪ್ರಯತ್ನಿಸುವ ಮೊದಲು ಸಕ್ರಿಯ ಮುಕ್ತ ಅವಧಿ ಮುಗಿಯುವವರೆಗೆ ಕಾಯಿರಿ.",
    "In You → Notifications, choose five-minute limit warnings and optional free-period boundary reminders. Limit warnings are only for budgets longer than five minutes and are suppressed during free periods. iOS notification permission is separate from Screen Time access, and alerts can arrive late or not at all. Now & Next and Pending Change widgets are read-only summaries; they do not apply overrides or show raw usage.": "ನೀವು → ಅಧಿಸೂಚನೆಗಳಲ್ಲಿ, ಐದು ನಿಮಿಷದ ಮಿತಿ ಎಚ್ಚರಿಕೆಗಳು ಮತ್ತು ಐಚ್ಛಿಕ ಮುಕ್ತ-ಅವಧಿ ಗಡಿ ಜ್ಞಾಪನೆಗಳನ್ನು ಆರಿಸಿ. ಮಿತಿ ಎಚ್ಚರಿಕೆಗಳು ಐದು ನಿಮಿಷಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಬಜೆಟ್‌ಗಳಿಗೆ ಮಾತ್ರ, ಮತ್ತು ಮುಕ್ತ ಅವಧಿಗಳಲ್ಲಿ ತಡೆಹಿಡಿಯಲಾಗುತ್ತದೆ. iOS ಅಧಿಸೂಚನೆ ಅನುಮತಿ ಸ್ಕ್ರೀನ್ ಟೈಮ್ ಪ್ರವೇಶದಿಂದ ಪ್ರತ್ಯೇಕ, ಮತ್ತು ಎಚ್ಚರಿಕೆಗಳು ತಡವಾಗಿ ಬರಬಹುದು ಅಥವಾ ಬಾರದಿರಬಹುದು. ಈಗ ಮತ್ತು ಮುಂದೆ ಹಾಗೂ ಬಾಕಿ ಬದಲಾವಣೆ ವಿಜೆಟ್‌ಗಳು ಓದು-ಮಾತ್ರ ಸಾರಾಂಶಗಳು; ಅವು ಒಪ್ಪಿಗೆಗಳನ್ನು ಅನ್ವಯಿಸುವುದಿಲ್ಲ ಅಥವಾ ಕಚ್ಚಾ ಬಳಕೆಯನ್ನು ತೋರಿಸುವುದಿಲ್ಲ.",
    "contacts, passwords and phrases": "ಸಂಪರ್ಕಗಳು, ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಮತ್ತು ವಾಕ್ಯಗಳು",
    "How Demora works": "Demora ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ",
    "four short pages": "ನಾಲ್ಕು ಚಿಕ್ಕ ಪುಟಗಳು",
    "Your past decision wins": "ನಿಮ್ಮ ಹಿಂದಿನ ನಿರ್ಧಾರ ಗೆಲ್ಲುತ್ತದೆ",
    "You set your rules when you're calm. Later, when an impulse says \"just this once\", the rule you chose still holds.": "ನೀವು ಶಾಂತವಾಗಿರುವಾಗ ನಿಯಮಗಳನ್ನು ಹೊಂದಿಸುತ್ತೀರಿ. ನಂತರ ಆವೇಗ \"ಈ ಒಂದು ಬಾರಿ\" ಎಂದಾಗ, ನೀವು ಆರಿಸಿದ ನಿಯಮ ಇನ್ನೂ ಉಳಿಯುತ್ತದೆ.",
    "Stricter is quick, looser waits": "ಕಠಿಣ ಬೇಗ, ಸಡಿಲ ಕಾಯುತ್ತದೆ",
    "Making a rule stricter can apply right away. Making it looser waits through the wait you chose in Rules → Your waits.": "ನಿಯಮವನ್ನು ಕಠಿಣಗೊಳಿಸುವುದು ತಕ್ಷಣ ಜಾರಿಯಾಗಬಹುದು. ಸಡಿಲಿಸುವುದು ನಿಯಮಗಳು → ನಿಮ್ಮ ಕಾಯುವಿಕೆಗಳಲ್ಲಿ ನೀವು ಆರಿಸಿದ ಕಾಯುವಿಕೆಯನ್ನು ಕಾಯುತ್ತದೆ.",
    "Changes wait in Changes": "ಬದಲಾವಣೆಗಳು ಬದಲಾವಣೆಗಳಲ್ಲಿ ಕಾಯುತ್ತವೆ",
    "A looser change waits in Changes on Today with its countdown. Until it lands nothing changes, and you can cancel it any time.": "ಸಡಿಲ ಬದಲಾವಣೆ ಇಂದು ಟ್ಯಾಬ್‌ನ ಬದಲಾವಣೆಗಳಲ್ಲಿ ತನ್ನ ಕೌಂಟ್‌ಡೌನ್‌ನೊಂದಿಗೆ ಕಾಯುತ್ತದೆ. ಅದು ಜಾರಿಗೆ ಬರುವವರೆಗೆ ಏನೂ ಬದಲಾಗುವುದಿಲ್ಲ, ಮತ್ತು ಯಾವಾಗ ಬೇಕಾದರೂ ರದ್ದುಮಾಡಬಹುದು.",
    "A trusted contact, a password or a phrase can let a change apply early, but only for the kinds of change you allowed. Changes to them wait too. Set them up in You → Ways to skip a wait.": "ನಂಬಿಕಸ್ಥ ಸಂಪರ್ಕ, ಪಾಸ್‌ವರ್ಡ್ ಅಥವಾ ವಾಕ್ಯ ಬದಲಾವಣೆ ಬೇಗ ಜಾರಿಯಾಗಲು ಬಿಡಬಹುದು, ಆದರೆ ನೀವು ಅನುಮತಿಸಿದ ಬದಲಾವಣೆಗಳ ವಿಧಗಳಿಗೆ ಮಾತ್ರ. ಅವುಗಳ ಬದಲಾವಣೆಗಳೂ ಕಾಯುತ್ತವೆ. ಅವನ್ನು ನೀವು → ಕಾಯುವಿಕೆ ಬಿಡುವ ಮಾರ್ಗಗಳಲ್ಲಿ ಹೊಂದಿಸಿ.",
    "How Demora works is always in You → Help & guide.": "Demora ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ ಎಂಬುದು ಯಾವಾಗಲೂ ನೀವು → ಸಹಾಯ ಮತ್ತು ಮಾರ್ಗದರ್ಶಿಯಲ್ಲಿದೆ.",
    "Find practical instructions and troubleshooting in You → Help & guide → Guide.": "ಪ್ರಾಯೋಗಿಕ ಸೂಚನೆಗಳು ಮತ್ತು ದೋಷ ನಿವಾರಣೆ ನೀವು → ಸಹಾಯ ಮತ್ತು ಮಾರ್ಗದರ್ಶಿ → ಮಾರ್ಗದರ್ಶಿಯಲ್ಲಿ ಸಿಗುತ್ತವೆ.",
    "Contact invitations are sent after setup. Contacts must confirm before they can approve; manage them in You → Ways to skip a wait.": "ಸಂಪರ್ಕ ಆಹ್ವಾನಗಳನ್ನು ಸೆಟಪ್ ನಂತರ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಸಂಪರ್ಕಗಳು ಒಪ್ಪುವ ಮೊದಲು ದೃಢೀಕರಿಸಬೇಕು; ಅವನ್ನು ನೀವು → ಕಾಯುವಿಕೆ ಬಿಡುವ ಮಾರ್ಗಗಳಲ್ಲಿ ನಿರ್ವಹಿಸಿ.",
    "A person you choose approves skipping a countdown — by email code or from their own Demora app. You can also add more later in You → Ways to skip a wait.": "ನೀವು ಆರಿಸಿದ ವ್ಯಕ್ತಿ ಕೌಂಟ್‌ಡೌನ್ ಬಿಡಲು ಒಪ್ಪುತ್ತಾರೆ — ಇಮೇಲ್ ಕೋಡ್ ಮೂಲಕ ಅಥವಾ ತಮ್ಮ Demora ಆ್ಯಪ್‌ನಿಂದ. ಇನ್ನಷ್ಟು ಜನರನ್ನು ನಂತರ ನೀವು → ಕಾಯುವಿಕೆ ಬಿಡುವ ಮಾರ್ಗಗಳಲ್ಲಿ ಸೇರಿಸಬಹುದು.",
    "Choose your language here. You can change it anytime under You → Appearance → Language.": "ನಿಮ್ಮ ಭಾಷೆಯನ್ನು ಇಲ್ಲಿ ಆರಿಸಿ. ಯಾವಾಗ ಬೇಕಾದರೂ ನೀವು → ರೂಪ → ಭಾಷೆಯಲ್ಲಿ ಬದಲಿಸಬಹುದು.",
    "Ask them for the code under You → Your code in their Demora. They'll get a request to accept before they can approve for you.": "ಅವರ Demora ದಲ್ಲಿ ನೀವು → ನಿಮ್ಮ ಕೋಡ್ ಅಡಿಯ ಕೋಡ್ ಅವರನ್ನು ಕೇಳಿ. ನಿಮಗಾಗಿ ಒಪ್ಪುವ ಮೊದಲು ಅವರಿಗೆ ಸ್ವೀಕರಿಸಲು ವಿನಂತಿ ಬರುತ್ತದೆ.",
    // You review fix: what can never be skipped early
    "Changes to passwords, phrases and what anyone may skip can never be skipped early.": "ಪಾಸ್‌ವರ್ಡ್‌ಗಳು, ವಾಕ್ಯಗಳು ಮತ್ತು ಯಾರು ಏನನ್ನು ಬಿಡಬಹುದು ಎಂಬ ಬದಲಾವಣೆಗಳ ಕಾಯುವಿಕೆಯನ್ನು ಎಂದೂ ಬೇಗ ಬಿಡಲಾಗದು.",
