    "%d times a day": "ದಿನಕ್ಕೆ %d ಬಾರಿ",
    "%d × %@ free": "%d × %@ ಮುಕ್ತ",
    "%d × %@ unblocked": "%d × %@ ಅನ್‌ಬ್ಲಾಕ್",
    "A block starts when you check in at a place or in a country, and runs until the end you choose. Leaving doesn't end it. It blocks only the apps you choose.": "ನೀವು ಒಂದು ಸ್ಥಳ ಅಥವಾ ದೇಶದಲ್ಲಿ ಚೆಕ್ ಇನ್ ಮಾಡಿದಾಗ ಬ್ಲಾಕ್ ಆರಂಭವಾಗಿ, ನೀವು ಆರಿಸಿದ ಅಂತ್ಯದವರೆಗೆ ನಡೆಯುತ್ತದೆ. ಅಲ್ಲಿಂದ ಹೊರಟರೂ ಅದು ಮುಗಿಯುವುದಿಲ್ಲ. ಇದು ನೀವು ಆರಿಸಿದ ಆ್ಯಪ್‌ಗಳನ್ನು ಮಾತ್ರ ಬ್ಲಾಕ್ ಮಾಡುತ್ತದೆ.",
    "Add at least one condition.": "ಕನಿಷ್ಠ ಒಂದು ಷರತ್ತು ಸೇರಿಸಿ.",
