    "For %@": "%@ ಗೆ",
    "For a while": "ಸ್ವಲ್ಪ ಕಾಲ",
    "Free time": "ಮುಕ್ತ ಸಮಯ",
    "Free time lifts every block, including day & night, while it runs.": "ಮುಕ್ತ ಸಮಯ ನಡೆಯುವಾಗ, ಹಗಲು ಮತ್ತು ರಾತ್ರಿ ಸೇರಿದಂತೆ ಪ್ರತಿ ಬ್ಲಾಕ್ ಅನ್ನು ಎತ್ತುತ್ತದೆ.",
    "Free time or a block that depends on place, day or time": "ಸ್ಥಳ, ದಿನ ಅಥವಾ ಸಮಯವನ್ನು ಅವಲಂಬಿಸಿದ ಮುಕ್ತ ಸಮಯ ಅಥವಾ ಬ್ಲಾಕ್",
    "Free time, up to %@": "ಮುಕ್ತ ಸಮಯ, %@ ವರೆಗೆ",
    "From %@ this blocks on its own. At %@ it starts when you check in.": "%@ ರಿಂದ ಇದು ತಾನಾಗಿ ಬ್ಲಾಕ್ ಮಾಡುತ್ತದೆ. %@ ಕ್ಕೆ ನೀವು ಚೆಕ್ ಇನ್ ಮಾಡಿದಾಗ ಆರಂಭವಾಗುತ್ತದೆ.",
    "If": "ಆದರೆ",
    "If (all of)": "ಆದರೆ (ಎಲ್ಲವೂ)",
    "If (any of)": "ಆದರೆ (ಯಾವುದಾದರೂ)",
    "Last day": "ಕೊನೆಯ ದಿನ",
    "Like Mexico": "ಮೆಕ್ಸಿಕೊದಂತೆ",
    "Like a trip": "ಪ್ರವಾಸದಂತೆ",
    "Like after 22:00": "22:00 ರ ನಂತರದಂತೆ",
    "Like home or school": "ಮನೆ ಅಥವಾ ಶಾಲೆಯಂತೆ",
    "Like weekends": "ವಾರಾಂತ್ಯಗಳಂತೆ",
    "New When & where rule": "ಹೊಸ ಯಾವಾಗ ಮತ್ತು ಎಲ್ಲಿ ನಿಯಮ",
    "None left today": "ಇಂದು ಉಳಿದಿಲ್ಲ",
    "Once a day": "ದಿನಕ್ಕೆ ಒಮ್ಮೆ",
    "Place": "ಸ್ಥಳ",
