    "The last day can't be before the first.": "ಕೊನೆಯ ದಿನ ಮೊದಲ ದಿನಕ್ಕಿಂತ ಮೊದಲು ಇರಬಾರದು.",
    "Then": "ಆಗ",
    "Time": "ಸಮಯ",
