    "Until": "ವರೆಗೆ",
    "Until a time": "ಒಂದು ಸಮಯದವರೆಗೆ",
    "Up to": "ಗರಿಷ್ಠ",
    "Use a shorter name.": "ಚಿಕ್ಕ ಹೆಸರು ಬಳಸಿ.",
    "Use at most four conditions.": "ಗರಿಷ್ಠ ನಾಲ್ಕು ಷರತ್ತುಗಳನ್ನು ಬಳಸಿ.",
    "With “any of”, a block can use times, places and countries, not days or dates.": "\"ಯಾವುದಾದರೂ\" ಜೊತೆ, ಬ್ಲಾಕ್ ಸಮಯ, ಸ್ಥಳ ಮತ್ತು ದೇಶಗಳನ್ನು ಬಳಸಬಹುದು, ದಿನ ಅಥವಾ ದಿನಾಂಕಗಳನ್ನಲ್ಲ.",
    "With “any of”, a time on its own blocks every day, like a repeating block.": "\"ಯಾವುದಾದರೂ\" ಜೊತೆ, ಒಂದೇ ಸಮಯ ಪುನರಾವರ್ತಿತ ಬ್ಲಾಕ್‌ನಂತೆ ಪ್ರತಿ ದಿನ ಬ್ಲಾಕ್ ಮಾಡುತ್ತದೆ.",
    "You can add up to four conditions.": "ಗರಿಷ್ಠ ನಾಲ್ಕು ಷರತ್ತುಗಳನ್ನು ಸೇರಿಸಬಹುದು.",
    "You can have up to five When & where rules.": "ಐದು ಯಾವಾಗ ಮತ್ತು ಎಲ್ಲಿ ನಿಯಮಗಳವರೆಗೆ ಹೊಂದಬಹುದು.",
    // When & where step 3: check-in sheet and Today rows.
    "Free time needs all of these.": "ಮುಕ್ತ ಸಮಯಕ್ಕೆ ಇವೆಲ್ಲವೂ ಬೇಕು.",
    "Free time needs any of these.": "ಮುಕ್ತ ಸಮಯಕ್ಕೆ ಇವುಗಳಲ್ಲಿ ಯಾವುದಾದರೂ ಬೇಕು.",
    "The block needs all of these.": "ಬ್ಲಾಕ್‌ಗೆ ಇವೆಲ್ಲವೂ ಬೇಕು.",
    "The block needs any of these.": "ಬ್ಲಾಕ್‌ಗೆ ಇವುಗಳಲ್ಲಿ ಯಾವುದಾದರೂ ಬೇಕು.",
    "This rule changed. Check in again.": "ಈ ನಿಯಮ ಬದಲಾಗಿದೆ. ಮತ್ತೆ ಚೆಕ್ ಇನ್ ಮಾಡಿ.",
    "Free time is on until %@.": "%@ ವರೆಗೆ ಮುಕ್ತ ಸಮಯ ಆನ್ ಇದೆ.",
    "This rule needs your location.": "ಈ ನಿಯಮಕ್ಕೆ ನಿಮ್ಮ ಸ್ಥಳ ಬೇಕು.",
    "You can have free time now.": "ಈಗ ನಿಮಗೆ ಮುಕ್ತ ಸಮಯ ಸಿಗಬಹುದು.",
    "You've used today's free time.": "ನೀವು ಇಂದಿನ ಮುಕ್ತ ಸಮಯವನ್ನು ಬಳಸಿದ್ದೀರಿ.",
    "Free time didn't start.": "ಮುಕ್ತ ಸಮಯ ಆರಂಭವಾಗಲಿಲ್ಲ.",
    "Not right now.": "ಈಗ ಅಲ್ಲ.",
    "Your clock was changed recently. Free time can start once it's set right again.": "ನಿಮ್ಮ ಗಡಿಯಾರ ಇತ್ತೀಚೆಗೆ ಬದಲಾಗಿದೆ. ಅದನ್ನು ಮತ್ತೆ ಸರಿಯಾಗಿ ಹೊಂದಿಸಿದ ನಂತರ ಮುಕ್ತ ಸಮಯ ಆರಂಭವಾಗಬಹುದು.",
    "Couldn't count today's uses. Try again.": "ಇಂದಿನ ಬಳಕೆಗಳನ್ನು ಎಣಿಸಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
    "Less than a minute is left in this window.": "ಈ ಅವಧಿಯಲ್ಲಿ ಒಂದು ನಿಮಿಷಕ್ಕಿಂತ ಕಡಿಮೆ ಉಳಿದಿದೆ.",
    "It's waiting in Changes instead.": "ಬದಲಿಗೆ ಅದು ಬದಲಾವಣೆಗಳಲ್ಲಿ ಕಾಯುತ್ತಿದೆ.",
    "This check is more than two minutes old. Check in again.": "ಈ ಪರಿಶೀಲನೆ ಎರಡು ನಿಮಿಷಕ್ಕಿಂತ ಹಳೆಯದು. ಮತ್ತೆ ಚೆಕ್ ಇನ್ ಮಾಡಿ.",
    "A new day started. Check in again.": "ಹೊಸ ದಿನ ಆರಂಭವಾಯಿತು. ಮತ್ತೆ ಚೆಕ್ ಇನ್ ಮಾಡಿ.",
    "Your time zone changed. Check in again.": "ನಿಮ್ಮ ಸಮಯ ವಲಯ ಬದಲಾಗಿದೆ. ಮತ್ತೆ ಚೆಕ್ ಇನ್ ಮಾಡಿ.",
    "The conditions aren't met any more.": "ಷರತ್ತುಗಳು ಇನ್ನು ಪೂರೈಸುತ್ತಿಲ್ಲ.",
    "Choose a length this rule allows.": "ಈ ನಿಯಮ ಅನುಮತಿಸುವ ಅವಧಿ ಆರಿಸಿ.",
    "Free time from this rule is already on.": "ಈ ನಿಯಮದ ಮುಕ್ತ ಸಮಯ ಈಗಾಗಲೇ ಆನ್ ಇದೆ.",
    "This check-in was already used. Check in again.": "ಈ ಚೆಕ್-ಇನ್ ಈಗಾಗಲೇ ಬಳಕೆಯಾಗಿದೆ. ಮತ್ತೆ ಚೆಕ್ ಇನ್ ಮಾಡಿ.",
    "A change is still being applied. Try again in a moment.": "ಒಂದು ಬದಲಾವಣೆ ಇನ್ನೂ ಅನ್ವಯವಾಗುತ್ತಿದೆ. ಸ್ವಲ್ಪ ಸಮಯದ ನಂತರ ಪ್ರಯತ್ನಿಸಿ.",
    "Free time couldn't start safely. iOS may not be able to track another session right now. Nothing changed.": "ಮುಕ್ತ ಸಮಯವನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಆರಂಭಿಸಲಾಗಲಿಲ್ಲ. iOS ಈಗ ಇನ್ನೊಂದು ಸೆಷನ್ ಅನ್ನು ಗಮನಿಸಲಾಗದಿರಬಹುದು. ಏನೂ ಬದಲಾಗಿಲ್ಲ.",
    "You're at %@": "ನೀವು %@ ನಲ್ಲಿ ಇದ್ದೀರಿ",
    "You're not at %@": "ನೀವು %@ ನಲ್ಲಿ ಇಲ್ಲ",
