    "Demora checks where you are once, when you tap Check in. It doesn't save or send your location.": "ನೀವು ಚೆಕ್ ಇನ್ ಟ್ಯಾಪ್ ಮಾಡಿದಾಗ Demora ನೀವು ಎಲ್ಲಿದ್ದೀರಿ ಎಂದು ಒಮ್ಮೆ ಮಾತ್ರ ಪರಿಶೀಲಿಸುತ್ತದೆ. ನಿಮ್ಮ ಸ್ಥಳವನ್ನು ಉಳಿಸುವುದಿಲ್ಲ ಅಥವಾ ಕಳುಹಿಸುವುದಿಲ್ಲ.",
