    "Leaving doesn't end it. Ending it early waits like any looser change.": "ಅಲ್ಲಿಂದ ಹೊರಟರೂ ಅದು ಮುಗಿಯುವುದಿಲ್ಲ. ಬೇಗ ಮುಗಿಸುವುದು ಯಾವುದೇ ಸಡಿಲ ಬದಲಾವಣೆಯಂತೆ ಕಾಯುತ್ತದೆ.",
    "Its time blocks on its own, without a check-in.": "ಇದರ ಸಮಯ ಚೆಕ್-ಇನ್ ಇಲ್ಲದೆ ತಾನಾಗಿ ಬ್ಲಾಕ್ ಮಾಡುತ್ತದೆ.",
