    "A block from this rule is already on.": "ಈ ನಿಯಮದ ಬ್ಲಾಕ್ ಈಗಾಗಲೇ ಆನ್ ಇದೆ.",
    "The block couldn't start safely. iOS may not be able to track another session right now. Nothing changed.": "ಬ್ಲಾಕ್ ಅನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಆರಂಭಿಸಲಾಗಲಿಲ್ಲ. iOS ಈಗ ಇನ್ನೊಂದು ಸೆಷನ್ ಅನ್ನು ಗಮನಿಸಲಾಗದಿರಬಹುದು. ಏನೂ ಬದಲಾಗಿಲ್ಲ.",
    "Review": "ಪರಿಶೀಲಿಸಿ",
    "Then runs until %@.": "ನಂತರ %@ ವರೆಗೆ ನಡೆಯುತ್ತದೆ.",
