    "A change to this rule lands first. Check in after it lands.": "ಈ ನಿಯಮದ ಬದಲಾವಣೆ ಮೊದಲು ಜಾರಿಯಾಗುತ್ತದೆ. ಅದು ಜಾರಿಯಾದ ನಂತರ ಚೆಕ್ ಇನ್ ಮಾಡಿ.",
    "Its rule changed while it waited. Cancel it in Changes, then check in again.": "ಕಾಯುತ್ತಿದ್ದಾಗ ಅದರ ನಿಯಮ ಬದಲಾಯಿತು. ಬದಲಾವಣೆಗಳಲ್ಲಿ ಅದನ್ನು ರದ್ದುಮಾಡಿ, ನಂತರ ಮತ್ತೆ ಚೆಕ್ ಇನ್ ಮಾಡಿ.",
