    "Your limits will show here. Pull down to refresh if it stays empty.": "ನಿಮ್ಮ ಮಿತಿಗಳು ಇಲ್ಲಿ ಕಾಣುತ್ತವೆ. ಖಾಲಿಯಾಗಿಯೇ ಇದ್ದರೆ ರಿಫ್ರೆಶ್ ಮಾಡಲು ಕೆಳಗೆ ಎಳೆಯಿರಿ.",
